  ocvth:{name:"OpenCV公式チュートリアル「Thresholding」",url:"https://docs.opencv.org/4.x/d7/d4d/tutorial_py_thresholding.html"},
  ocvmorph:{name:"OpenCV公式チュートリアル「Morphological Transformations」",url:"https://docs.opencv.org/4.x/d9/d61/tutorial_py_morphological_ops.html"},
