  ocveq:{name:"OpenCV公式チュートリアル「Histogram Equalization」",url:"https://docs.opencv.org/4.x/d5/daf/tutorial_py_histogram_equalization.html"},
  ocvfft:{name:"OpenCV公式チュートリアル「Fourier Transform」",url:"https://docs.opencv.org/4.x/de/dbc/tutorial_py_fourier_transform.html"},
  ocvcanny:{name:"OpenCV公式チュートリアル「Canny Edge Detection」",url:"https://docs.opencv.org/4.x/da/d22/tutorial_py_canny.html"},
