  skdt:{name:"scikit-image公式「Image data types and what they mean」",url:"https://scikit-image.org/docs/stable/user_guide/data_types.html"},
  ocvgeo:{name:"OpenCV公式チュートリアル「Geometric Transformations of Images」",url:"https://docs.opencv.org/4.x/da/d6e/tutorial_py_geometric_transformations.html"},
  ocvbg:{name:"OpenCV公式チュートリアル「Background Subtraction」",url:"https://docs.opencv.org/4.x/d1/dc5/tutorial_background_subtraction.html"},
  ocvflow:{name:"OpenCV公式チュートリアル「Optical Flow」",url:"https://docs.opencv.org/4.x/d4/dee/tutorial_optical_flow.html"},
  ocvhough:{name:"OpenCV公式チュートリアル「Hough Line Transform」",url:"https://docs.opencv.org/4.x/d6/d10/tutorial_py_houghlines.html"},
  ocvtpl:{name:"OpenCV公式チュートリアル「Template Matching」",url:"https://docs.opencv.org/4.x/d4/dc6/tutorial_py_template_matching.html"},
  ocvfeat2d:{name:"OpenCV公式チュートリアル「Feature Detection and Description」",url:"https://docs.opencv.org/4.x/db/d27/tutorial_py_table_of_contents_feature2d.html"},
  ocvcalib:{name:"OpenCV公式チュートリアル「Camera Calibration」",url:"https://docs.opencv.org/4.x/dc/dbb/tutorial_py_calibration.html"},
  skrest:{name:"scikit-image公式API「skimage.restoration」",url:"https://scikit-image.org/docs/stable/api/skimage.restoration.html"},
  skfeat:{name:"scikit-image公式API「skimage.feature」",url:"https://scikit-image.org/docs/stable/api/skimage.feature.html"},
