window.IJDATA2.eduLessonCats = { base:"画像の基礎", hist:"濃度変換とヒストグラム", color:"色と視覚", geom:"幾何変換", filt:"空間フィルタリング", freq:"周波数領域", rest:"画像復元", seg:"二値化と領域分割", feat:"特徴抽出とマッチング", eval:"評価と圧縮", video:"動画像処理", recog:"認識と学習", cam:"撮像と3次元", prac:"実践環境" };
window.IJDATA2.eduLessons = [
{id:"G01",cat:"base",title:"デジタル画像とは：標本化と量子化",lead:"アナログの光の分布が、どのようにして画素値の2次元格子になるのか。すべての画像解析はこの変換の理解から始まります。",
 sections:[
  {h:"標本化：連続量を格子点で代表させる",b:["現実の像は、位置についても明るさについても連続量です。デジタル画像にする第一歩は標本化（サンプリング）で、像を等間隔の格子点で区切り、各格子点の明るさを代表値として取り出します。格子点1つ分が画素（ピクセル）であり、格子の間隔が空間解像度を決めます。","標本化の間隔に対して細かすぎる構造は正しく再現できません。元の信号に含まれる最高周波数の2倍より高い頻度で標本化しなければ、折り返し歪み（エイリアシング）が生じるというのが標本化定理の主張です。画像では格子縞や階段状の輪郭として現れます。"],fig:null},
  {h:"量子化：明るさを有限の段数に丸める",b:["第二の変換は量子化で、各画素の明るさ（連続量）を有限個の段階のいずれかに割り当てます。段数がビット深度です。8-bitなら256段階、16-bitなら65,536段階、32-bit floatでは浮動小数としてほぼ連続的に扱えます。","量子化の段数が不足すると、滑らかなグラデーションに偽の輪郭（量子化誤差によるバンディング）が現れます。一方で段数を増やしても、センサーのノイズ以下を細かく刻む意味は薄く、データ量との釣り合いで決まります。"],fig:null},
  {h:"画像は「数値の表」である",b:["標本化と量子化を経た画像は、数学的には行列 f(x, y) です。x, y が画素の位置、f がその位置の画素値（強度）を表します。カラー画像はこれがチャンネル分だけ重なったもの、動画や3次元画像は次元が増えたものと捉えられます。","この見方が重要なのは、後のすべての処理（フィルタ、変換、測定）がこの数値の表への演算として統一的に理解できるからです。表示は LUT による見え方の割り当てにすぎず、データそのものは画素値の表です。"],fig:null},
  {h:"量子化誤差とSNRの目安",b:["量子化の刻み幅を Δ とすると、丸めによる誤差は最大で ±Δ/2 の範囲に分布します。この量子化ノイズを信号と比べた目安として、フルスケールの正弦波に対する信号対雑音比は SNR ≈ 6.02n + 1.76 dB（n はビット深度）と表されます。つまり1ビット増やすごとに約6dBずつ改善します。","この式は「量子化以外のノイズがない理想条件」での上限です。実際の画像ではセンサーの光子ショットノイズや読み出しノイズが支配的になることが多く、ビット深度を上げてもSNRが式どおり伸びるとは限りません。式は設計の目安であり、実効性能は系全体で決まります。"],fig:null}],
 points:["標本化＝位置の離散化、量子化＝明るさの離散化","標本化定理：最高周波数の2倍超の標本化が必要","画像は行列 f(x, y) として扱うのが解析の出発点"],mistakes:["画素数を増やせば細部が蘇る（情報は標本化の時点で決まる）","ビット深度が高いほど常に良い（ノイズとデータ量の釣り合いがある）"],src:"dip",terms:["標本化","量子化","画素","エイリアシング"],related:["G02","G03"]},
{id:"G02",cat:"base",title:"ビット深度とダイナミックレンジ",lead:"8-bit、16-bit、32-bit floatの違いは「段数の多さ」だけではありません。測れる明暗の幅と、演算で失われる情報の量が変わります。",
 sections:[
  {h:"ビット深度が決めるもの",b:["ビット深度 n に対して表せる段階数は 2^n です。8-bitは256段階、12-bitは4,096段階、16-bitは65,536段階。顕微鏡カメラの多くは12-bitや14-bitのセンサー出力を持ち、16-bit画像として保存されます。","段階数が効くのは、暗い部分の微妙な差を測るときです。8-bitでは1段の差が全体の約0.4%に相当し、暗部の数段の差はノイズに埋もれます。定量測定では、対象の信号が何段分に分布しているかが精度を左右します。"],fig:null},
  {h:"ダイナミックレンジ",b:["ダイナミックレンジは、検出できる最も明るい信号と最も暗い信号（ノイズフロア）の比です。ビット深度はこの幅を刻む細かさの上限を与えますが、実際のレンジはセンサーの飽和容量と読み出しノイズで決まります。","保存形式の深度と実効的なレンジは別物です。16-bitで保存されていても、センサーが12-bit相当の情報しか持たなければ、下位ビットはノイズです。逆に8-bit化はレンジの切り捨てであり、後から戻すことはできません。"],fig:null},
  {h:"型変換で失われるもの",b:["16-bitから8-bitへの変換は、通常は値域の線形圧縮（スケーリング）か切り捨てを伴い、階調情報が失われます。ImageJでは変換時に表示範囲でスケールするかどうかで結果が変わり、意図しない圧縮が測定値のずれを生む典型例です。","32-bit floatは加減乗除の途中結果を保持できるため、背景差分や比演算の作業領域として使われます。ただし float 化しても、元の量子化で失われた情報が戻るわけではありません。"],fig:null}],
 points:["段階数は 2^n。定量測定では信号が何段に分布するかが精度を決める","ダイナミックレンジはセンサー特性で決まり、保存深度とは別","深度を下げる変換は不可逆。作業は深い深度で、出力で落とす"],mistakes:["16-bit保存なら16-bit分の情報がある（センサーの実効深度に依存する）","8-bit化しても測定は同じ（画素値そのものが圧縮されている）"],src:"skdt",terms:["ビット深度","ダイナミックレンジ","量子化"],related:["G01","G17"]},
{id:"G03",cat:"base",title:"解像度とエイリアシング",lead:"「解像度が高い」は画素が多いことと同義ではありません。光学系のぼけ（PSF）と標本化間隔の関係が、実際に写る細かさを決めます。",
 sections:[
  {h:"2つの解像度",b:["空間解像度には、光学系がどれだけ細かい構造を分離できるか（光学的解像度）と、センサーがどれだけ細かく刻むか（標本化間隔）の2面があります。実際に記録される細かさは、両者のうち粗い方に制限されます。","光学系のぼけは点像分布関数（PSF）で表されます。点光源が像面で広がる形がPSFで、対物レンズの開口数（NA）と波長がその幅を決めます。画素をPSFより細かく刻んでも、新しい構造は現れません。"],fig:null},
  {h:"エイリアシングとモアレ",b:["標本化間隔に対して周期の短いパターンは、実際とは異なる低い周波数のパターンとして記録されます。これがエイリアシングで、布の織り目や格子状の標本で現れるモアレ（干渉縞）がその典型です。","対策は、標本化を細かくすること（オーバーサンプリング）か、標本化前に光学ローパスで高周波を落とすことです。一度記録されたモアレは、元の構造と区別できないため、後処理での除去は困難です。"],fig:null},
  {h:"適切な標本化間隔の目安",b:["標本化定理からは、再現したい最小構造の周期の半分より細かい間隔が必要だと分かります。顕微鏡ではPSFの幅（レイリー基準の分解能）に対して画素サイズをその1/2〜1/3程度に取るのが実務的な目安です。","逆に細かすぎる標本化は、1画素あたりの光量を減らしてノイズを増やし、データ量も膨らませます。「細かいほど良い」ではなく、対象のスケールに合わせるのが原則です。"],fig:null},
  {h:"分解能の数式：レイリー基準",b:["2点を分離できる限界の古典的な基準がレイリー基準で、分離可能な最小距離は d = 0.61λ/NA と表されます（λ は光の波長、NA は対物レンズの開口数）。アッベの基準 d = λ/(2NA) も同程度の値を与え、どちらも「分解能は波長に比例し、NAに反比例する」ことを示します。","周波数の言葉では、光学系が通す最高周波数（カットオフ）は fc = 2NA/λ です。標本化定理により画素ピッチは 1/(2fc) 以下が必要で、これが「分解能の1/2〜1/3の画素サイズ」という実務目安の理論的な裏付けになっています。"],fig:null}],
 points:["実際の細かさは光学解像度と標本化間隔の粗い方で決まる","モアレはエイリアシングの現れで、記録後の除去は困難","画素サイズは分解能の1/2〜1/3が実務的な目安"],mistakes:["画素数が多いカメラほど解像力が高い（PSFが制限すれば意味がない）","モアレはフィルタで消せる（元信号と区別できない）"],src:"dip",terms:["エイリアシング","モアレ","点像分布関数","ナイキスト周波数"],related:["G01","G11"]},
{id:"G04",cat:"hist",title:"点演算と濃度変換",lead:"各画素を、その画素の値だけから決まる規則で置き換える処理が点演算です。ガンマ補正も反転も、その特別な場合にすぎません。",
 sections:[
  {h:"点演算の一般形",b:["点演算は出力画素値 s が入力画素値 r の関数 s = T(r) で決まる処理です。位置や近傍の画素には依存しません。T が単調増加なら明暗の順序は保たれ、コントラストの分布だけが変わります。","代表例は、反転（s = 最大値 − r）、対数変換（暗部を持ち上げる）、べき乗変換（ガンマ補正）です。ガンマ補正 s = c・r^γ では、γ < 1 で暗部が、γ > 1 で明部が引き伸ばされます。","この変換関数 T を、横軸を入力 r、縦軸を出力 s としてグラフに描いたものがトーンカーブです。直線なら無変換、S字ならコントラスト強調、暗部の区間だけを持ち上げれば影の階調だけを回復できます。ガンマ補正は T の形をべき乗の1種類に固定したもので、トーンカーブは任意の形を許す一般形にあたります。写真編集ソフトの「トーンカーブ」は、この曲線を直接引いて設計する操作です。"],fig:null},
  {h:"表示の調整とデータの変換は違う",b:["ImageJの Brightness/Contrast のような表示調整は、表示範囲（LUTの割り当て）を変えるだけで画素値は変わりません。一方、Apply を伴う濃度変換や Math 演算は画素値そのものを書き換えます。","測定は画素値に対して行われるため、この区別は決定的です。見た目を整える操作と、データを変える操作を意識的に分けることが、定量解析の前提になります。"],fig:null},
  {h:"クリッピングと情報の損失",b:["変換の結果が値域を超えると、8-bitでは 0 や 255 に丸められます（クリッピング／飽和）。丸められた画素同士の差は失われ、後から復元できません。","線形に引き伸ばす変換でも、出力側の段数が同じなら、引き伸ばされた区間では段と段の間に空きができ、圧縮された区間では複数の入力段が同じ出力段に潰れます。点演算は情報を生まない、という原則の現れです。"],fig:null}],
 points:["点演算は s = T(r)。位置・近傍に依存しない","ガンマ補正は点演算の一種で、暗部・明部の伸縮を制御する","表示調整と画素値の書き換えは別物。測定に効くのは後者"],mistakes:["コントラストを上げれば情報が増える（再配分にすぎない）","飽和した画素も後で直せる（差の情報は失われている）"],src:"ocvhist",terms:["濃度変換","ガンマ補正","ルックアップテーブル"],related:["G05","G06"]},
{id:"G05",cat:"hist",title:"ヒストグラムの読み方と統計量",lead:"ヒストグラムは画素値の分布そのものです。平均・分散・歪みの読み取りが、あらゆる自動処理の判断材料になります。",
 sections:[
  {h:"ヒストグラムが表すもの",b:["ヒストグラム h(r) は、各画素値 r を持つ画素の個数（または割合 p(r)）を並べたものです。画像全体の明暗の分布を1本のグラフに圧縮したもので、位置の情報は捨てられています。","同じヒストグラムを持つ画像は無数にあります。ヒストグラムは「何が写っているか」ではなく「明暗がどう分布しているか」の情報であり、この割り切りが点演算の設計を可能にします。"],fig:null},
  {h:"統計量で分布を読む",b:["平均は分布の中心、分散（標準偏差）は広がり、歪度は非対称性、尖度は裾の重さを表します。コントラストの低い画像は狭い範囲に山が寄り、露光過多では明端に画素が張り付きます。","中央値やパーセンタイルは外れ値に強い指標です。背景が大半を占める蛍光画像では、平均より中央値や最頻値が背景レベルの推定に適します。統計量の選択自体が、画像の前提を表しています。"],fig:null},
  {h:"二峰性と閾値処理の見通し",b:["対象と背景で明るさが分かれる画像では、ヒストグラムが2つの山（峰）を持つ二峰性分布になります。谷の位置が自然な閾値の候補であり、大津の方法などの自動閾値決定はこの構造を利用します。","逆に峰が重なって谷が見えない画像では、画素値だけでは分離できないことをヒストグラムが教えてくれます。その場合は照明の改善や別の特徴（形状・色）が必要です。"],fig:null}],
 points:["ヒストグラムは明暗分布の要約で、位置情報は持たない","平均・分散・歪度・尖度と、中央値などの頑健な指標を使い分ける","二峰性が見えれば閾値処理の見通しが立つ"],mistakes:["ヒストグラムが同じなら同じ画像（位置情報がないので無数にありうる）","平均が背景レベルを表すとは限らない（対象の割合に引っ張られる）"],src:"ocvhist",terms:["ヒストグラム","累積ヒストグラム","大津の方法"],related:["G04","G13"]},
{id:"G06",cat:"hist",title:"ヒストグラム平坦化とCLAHE",lead:"分布を均一に広げる平坦化は、コントラスト強調の古典的手法です。その原理と、やりすぎを防ぐCLAHEの工夫を理解します。",
 sections:[
  {h:"平坦化の原理",b:["ヒストグラム平坦化は、累積ヒストグラム（累積分布関数）を変換関数に使う点演算です。画素の多い値域では変換の傾きが大きくなって間隔が広がり、少ない値域では圧縮されます。結果として分布がほぼ一様に近づき、コントラストが自動的に広がります。","変換は入力画像のヒストグラムから決まるため、画像ごとに異なります。同じ対象でも分布が違えば変換も変わる、という点が比較測定での注意点です。"],fig:null},
  {h:"平坦化の副作用",b:["平坦化は背景のノイズも一緒に強調します。もともと画素数の多い背景レベル付近が引き伸ばされると、背景のむらやノイズが目立つようになります。","また、平坦化後の画素値は元の物理量との線形関係を失います。見栄えの改善には有効でも、画素値で定量する解析の前処理には原則として向きません。"],fig:null},
  {h:"CLAHE：局所化と制限",b:["CLAHE（制限付き適応ヒストグラム平坦化）は、画像を小領域（タイル）に分け、各領域で平坦化を行い、ヒストグラムの突出を上限（クリップ限界）で抑えてから平坦化する改良法です。局所的なコントラスト改善と、ノイズ増幅の抑制を両立させます。","領域ごとの変換の継ぎ目は双線形補間で滑らかに接続されます。ImageJでは Fiji の Enhance Local Contrast (CLAHE) プラグインがこの処理にあたります。"],fig:null},
  {h:"平坦化の変換式",b:["離散の場合、平坦化の変換は s_k = (L−1) × Σ_{j=0}^{k} p(r_j) と書けます。p(r_j) は画素値 r_j の出現確率で、その累積和が累積分布関数です。出力値 s_k は「その値以下の画素が全体の何割か」に比例して割り当てられます。","出力のヒストグラムが一様になる理由は、確率変数の累積分布関数による変換が一様分布を生むという統計の基本性質です。画素の多い値域ほど変換の傾き（＝間隔の広がり）が大きくなり、コントラストが自動で再配分されます。CLAHEのクリップは、この傾きに上限を設けることに相当します。"],fig:null}],
 points:["平坦化は累積ヒストグラムを変換に使う点演算","副作用はノイズ強調と、画素値の定量性の喪失","CLAHEは局所化＋クリップ制限で副作用を抑える改良法"],mistakes:["平坦化すれば測定精度も上がる（定量性はむしろ失われる）","CLAHEは全体の平坦化と同じ結果になる（局所処理なので異なる）"],src:"ocveq",terms:["ヒストグラム平坦化","CLAHE","累積ヒストグラム"],related:["G05","G04"]},
{id:"G07",cat:"filt",title:"畳み込みとカーネル",lead:"近傍の画素を重み付きで混ぜ合わせる畳み込みは、空間フィルタリングの共通言語です。カーネルの設計が処理の意味を決めます。",
 sections:[
  {h:"畳み込みの定義",b:["畳み込みでは、カーネル（重みの小行列）を画像上で滑らせ、各位置で「カーネルと重なる画素値の重み付き和」を出力にします。カーネルを反転させてから重ねるのが数学的な畳み込みの定義で、反転しないものは相関と区別されますが、カーネルが対称なら両者は一致します。","カーネルの合計が1なら平均的な明るさは保たれ、合計が0なら一様な領域は0になります。この2つの性質だけでも、平滑化用か微分用かといったカーネルの性格が読み取れます。"],fig:null},
  {h:"境界の扱い",b:["画像の端ではカーネルがはみ出します。はみ出し部分をどう埋めるか（ゼロ埋め、端の値の複製、鏡映、巻き込み）で、端の画素の結果が変わります。暗い枠が出る・端だけ明るいといった現象は、境界処理の違いが原因のことがあります。","測定対象が画像端にかかる場合、この影響を直接受けます。端の扱いはライブラリやソフトごとに既定が異なるため、結果を比較するときの確認点です。"],fig:null},
  {h:"分離可能性と計算量",b:["カーネルが縦と横の1次元フィルタの積に分解できる場合（分離可能）、2次元畳み込みを1次元の連続適用に置き換えられ、計算量が大きく減ります。ガウシアンフィルタや平均フィルタ（ボックスフィルタ）は分離可能です。","カーネルが大きい処理では、周波数領域で積に直して計算する方が速い場合もあります。処理の等価性と計算量を意識することが、大画像を扱う実務では重要です。"],fig:null}],
 points:["畳み込み＝カーネルとの重み付き和。合計1は保存、合計0は微分系","端の埋め方で結果が変わる。比較時は境界処理を確認","分離可能なカーネルは高速化できる（ガウシアン等）"],mistakes:["畳み込みと相関は常に同じ（カーネルが非対称だと異なる）","端の異常はバグとは限らない（境界処理の仕様であることが多い）"],src:"ocvfilt",terms:["畳み込み","カーネル"],related:["G08","G09"]},
{id:"G08",cat:"filt",title:"平滑化フィルタとノイズ除去",lead:"平均、ガウシアン、メディアン。平滑化フィルタの違いは、消したいノイズの種類と、残したい構造の兼ね合いで決まります。",
 sections:[
  {h:"線形平滑化：平均とガウシアン",b:["平均フィルタは近傍の単純平均で、加算性のランダムノイズ（ガウシアンノイズ）を抑えますが、エッジも同じだけぼかします。ガウシアンフィルタは中心に重みを寄せた平均で、より自然なぼけになり、周波数特性も滑らかです。","平滑化の強さはカーネルの広がり（ガウシアンなら標準偏差σ）で決まります。ノイズ低減と解像度はトレードオフであり、σの選択は「どのスケールの構造を残すか」の宣言です。"],fig:null},
  {h:"メディアンフィルタとインパルスノイズ",b:["メディアンフィルタは近傍の中央値を出力する非線形フィルタです。ごま塩ノイズ（インパルスノイズ）のような外れ値の画素は順位の端に追いやられ、出力にほとんど影響しません。","エッジは平均より保存されやすい一方、細い線や点は消えることがあります。ノイズの種類を見極めてフィルタを選ぶことが原則で、万能な平滑化は存在しません。"],fig:null},
  {h:"エッジ保存平滑化",b:["バイラテラルフィルタは、距離の近さに加えて画素値の近さでも重みを付けるため、エッジをまたいだ平均化が抑えられ、エッジを残したまま平滑化できます。","この系統の処理は、平滑化とエッジ検出が表裏一体であることを示しています。何を「構造」で何を「ノイズ」とみなすかは、フィルタの設計思想に埋め込まれています。"],fig:null},
  {h:"ガウシアンカーネルの式",b:["ガウシアンフィルタの重みは、2次元ガウス関数 G(x, y) = (1/(2πσ²)) exp(−(x² + y²)/(2σ²)) を標本化したものです。前の係数は重みの合計を1にする正規化で、明るさが保存されます。σ が大きいほど重みは広がり、ぼけは強くなります。","実務では、σの約3倍の範囲（±3σ）までをカーネルに取るのが目安です。それより外側の重みはごく小さいためです。ガウス関数の数学的な性質（分離可能性・周波数特性）は G20 で扱います。"],fig:null}],
 points:["平均・ガウシアンは線形平滑化。強さはσや窓サイズで決まる","メディアンは外れ値に強く、ごま塩ノイズ向き","バイラテラルは値の近さも重みに使いエッジを保存する"],mistakes:["強い平滑化ほど測定に良い（構造も一緒に消える）","メディアンはあらゆるノイズに最強（対象は主にインパルス性）"],src:"ocvfilt",terms:["ガウシアンフィルタ","メディアンフィルタ","バイラテラルフィルタ","ごま塩ノイズ"],related:["G07","G09"]},
{id:"G09",cat:"filt",title:"微分フィルタと鮮鋭化",lead:"変化の大きい場所を取り出すのが微分フィルタです。エッジ検出と鮮鋭化は、同じ道具の表裏です。",
 sections:[
  {h:"勾配とラプラシアン",b:["1次微分（勾配）は画素値の変化の大きさと向きを与えます。Sobelフィルタは微分と平滑化を組み合わせたカーネルで、x方向・y方向の勾配からエッジの強さ（勾配の大きさ）と方向を計算します。","2次微分のラプラシアンは変化の変化を見るため、エッジの位置でゼロを横切る（ゼロ交差）性質があります。方向に依存しない反面、ノイズにも敏感です。"],fig:null},
  {h:"鮮鋭化とアンシャープマスキング",b:["鮮鋭化は、画像からぼけた成分を差し引くことで高周波を相対的に強める処理です。アンシャープマスキングは「元画像 − 平滑化した画像」を差分（マスク）として元画像に加え、輪郭を強調します。名前の由来は写真暗室の技法です。","強調しすぎると輪郭の両側に光と影の縁（ハロー）が出ます。鮮鋭化は新しい情報を作るのではなく、既存の高周波成分の配分を変えているだけです。"],fig:null},
  {h:"微分とノイズ",b:["微分は高周波を増幅する操作なので、ノイズも一緒に増幅します。微分フィルタの前に平滑化を入れる（例：ガウシアンでぼかしてからラプラシアンを取る LoG）のはこのためです。","Sobelカーネルに平滑化の重みが入っているのも同じ理由です。微分系の処理は、ノイズレベルとセットで設計するのが原則です。"],fig:null}],
 points:["勾配は変化の大きさと向き、ラプラシアンはゼロ交差でエッジを示す","アンシャープマスキングは差分の加算による高周波強調","微分はノイズも増幅する。前段の平滑化とセットで使う"],mistakes:["鮮鋭化で解像度が上がる（高周波の配分が変わるだけ）","ラプラシアンはノイズに強い（2次微分は特に敏感）"],src:"ocvfilt",terms:["Sobelフィルタ","ラプラシアン","アンシャープマスキング","画像勾配"],related:["G07","G14"]},
{id:"G10",cat:"freq",title:"フーリエ変換と周波数スペクトル",lead:"画像を「波の重ね合わせ」として見る周波数領域の考え方は、フィルタ設計と周期構造の解析の基盤です。",
 sections:[
  {h:"周波数で画像を見る",b:["フーリエ変換は、画像をさまざまな周波数・向き・位相の正弦波の重ね合わせに分解します。離散画像には離散フーリエ変換（DFT）が使われ、計算には高速フーリエ変換（FFT）のアルゴリズムを用います。","変換結果（周波数スペクトル）の中心付近が低周波（緩やかな変化）、外側が高周波（細かい変化・エッジ・ノイズ）に対応します。周期的なパターンは、スペクトル上に点や線として現れます。"],fig:null},
  {h:"畳み込み定理",b:["空間領域での畳み込みは、周波数領域では単なる掛け算に対応します（畳み込み定理）。フィルタ処理を「周波数ごとの倍率を変えること」と捉え直せるため、周波数領域はフィルタ設計の見通しを劇的に良くします。","逆に、周波数領域での点同士の積は空間での畳み込みに対応します。大きなカーネルの処理をFFT経由で高速化できるのも、この定理のおかげです。"],fig:null},
  {h:"位相の重要性",b:["スペクトルは振幅と位相からなります。振幅は「その周波数成分がどれだけあるか」、位相は「波がどこに位置するか」を持ちます。画像の構造（ものの形と配置）は主に位相側に担われています。","2枚の画像で振幅と位相を入れ替えて再構成すると、位相を与えた側の画像に似た結果になることが知られています。周波数＝細かさだけ、という理解では不十分な理由です。"],fig:null},
  {h:"DFTの定義式と性質",b:["M×N の画像に対する2次元DFTは、F(u, v) = Σ_{x=0}^{M−1} Σ_{y=0}^{N−1} f(x, y) exp(−j2π(ux/M + vy/N)) と定義されます。逆変換は指数の符号を反転し、1/(MN) で割る形で、情報の損失なく元に戻ります。各 F(u, v) が、周波数 (u, v) の正弦波成分の振幅と位相を複素数として持っています。","重要な性質として、(1) 線形性、(2) 空間での平行移動は位相の回転に対応する（シフト定理）、(3) 空間と周波数でエネルギーの総和が対応する（パーセバルの定理）、(4) 実数画像のスペクトルは共役対称 F(−u, −v) = F*(u, v) になる、があります。画像を回転させるとスペクトルも同じ角度だけ回転する、といった対応もこの枠組みで説明できます。"],fig:null}],
 points:["DFTは画像を正弦波の重ね合わせに分解する。中心が低周波","畳み込み定理：空間の畳み込み＝周波数の積","構造の情報は主に位相が担う"],mistakes:["高周波＝ノイズだけ（エッジや細部も高周波）","振幅だけ見れば画像が分かる（位相が構造を決める）"],src:"ocvfft",terms:["フーリエ変換","離散フーリエ変換","高速フーリエ変換","周波数スペクトル"],related:["G11","G12"]},
{id:"G11",cat:"freq",title:"標本化定理と周波数フィルタリング",lead:"周波数領域で倍率を変えるフィルタリングと、標本化定理が結びつくとき、エイリアシングの正体が周波数の言葉で説明できます。",
 sections:[
  {h:"周波数フィルタの基本形",b:["周波数フィルタリングは、DFTで得たスペクトルの各成分に倍率 H を掛けてから逆変換する処理です。低周波だけを通すローパスは平滑化に、高周波だけを通すハイパスはエッジ強調に対応します。","理想的な（急峻な）遮断は、空間領域ではリンギング（波打ち状の偽構造）を生みます。ガウシアン型のように滑らかな特性を持つフィルタが実務で好まれる理由です。"],fig:null},
  {h:"標本化定理の周波数的な意味",b:["標本化は、周波数領域ではスペクトルの周期的な複製に対応します。標本化周波数が不足すると、隣り合う複製同士が重なり、高周波が低周波に化けて記録されます。これがエイリアシングの周波数的な説明です。","重なりが起きない限界がナイキスト周波数（標本化周波数の半分）です。顕微鏡の画素サイズの目安（G03）も、この言葉で統一的に理解できます。"],fig:null},
  {h:"周期ノイズの除去",b:["電気的な干渉や走査の周期性によるノイズは、スペクトル上で特定の点に集中します。その点だけを落とすノッチフィルタで、空間領域のフィルタでは難しい選択的な除去ができます。","ただし点を落とすことは、その周波数成分を画像全体から消すことでもあります。対象の構造が同じ周波数を持つ場合は一緒に失われるため、適用は慎重に判断します。"],fig:null},
  {h:"フィルタ関数の形：理想・バターワース・ガウシアン",b:["中心からの距離 D(u, v) の関数としてフィルタを書くと、代表的なローパスの形が見えてきます。理想ローパスは、遮断周波数 D0 の内側を1、外側を0とする矩形の特性です。バターワースローパスは H = 1/(1 + (D/D0)^{2n})（n は次数）で、D = D0 でちょうど 1/2 になります。ガウシアンローパスは H = exp(−D²/(2σ²)) という滑らかな形です。","特性が急峻なほど空間領域の応答は振動的になり、リンギングが強くなります。理想フィルタが最も激しく、バターワースは次数 n を上げるほど理想に近づいて振動も増え、ガウシアン型は振動のない応答を持ちます。この関係の詳細は G22 で扱います。"],fig:null}],
 points:["周波数フィルタ＝スペクトルへの倍率付け。急峻な遮断はリンギングを生む","エイリアシングはスペクトルの複製の重なりとして説明できる","周期ノイズはノッチフィルタで選択的に除去できる"],mistakes:["ローパスと平滑化は別物（周波数と空間の対応で同じ処理）","ナイキスト周波数は標本化周波数そのもの（半分が正しい）"],src:"ocvfft",terms:["標本化定理","ナイキスト周波数","ローパスフィルタ","ハイパスフィルタ"],related:["G03","G10"]},
{id:"G12",cat:"freq",title:"FFTの実務：ImageJでの周波数処理",lead:"理論を道具として使う段階です。ImageJのFFT表示の読み方と、バンドパスや周期構造の解析への応用を押さえます。",
 sections:[
  {h:"ImageJのFFT表示",b:["ImageJの Process > FFT > FFT は、周波数スペクトルを対数スケールで表示します。中心が直流成分（平均の明るさ＝低周波の極限）で、外側ほど高周波です。表示は見やすくするための対数圧縮であり、データそのものは複素数です。","スペクトル表示で明るい点や線が見えれば、画像内にその周波数・向きの周期成分が強いことを意味します。縞の向きとスペクトルの点の向きは直交する関係にあります。"],fig:null},
  {h:"バンドパスと方向フィルタ",b:["特定の周波数帯だけを通すバンドパスフィルタは、対象のスケールを選ぶ処理です。ImageJの Bandpass Filter は、大きな構造（背景のむら）と細かいノイズを同時に抑え、粒子解析の前処理などに使われます。","向きの成分を選ぶ方向フィルタと組み合わせると、繊維状の構造など方向性のある対象を抽出できます。周波数領域の操作は「スケールと向きで選ぶ」道具だと捉えると応用が利きます。"],fig:null},
  {h:"自己相関と周期の測定",b:["スペクトルの二乗（パワースペクトル）の逆変換は自己相関を与え、周期構造の間隔を測るのに使えます。格子状標本の周期や、繰り返しパターンの定量化がその応用です。","FFTを使う処理では、画像サイズが2の累乗でない場合のゼロ埋めや、端の不連続が作る十字状のアーティファクト（端効果）にも注意が必要です。窓関数や端の処理が結果に影響します。"],fig:null}],
 points:["ImageJのFFT表示は対数スケール。中心が低周波","バンドパスはスケールで選ぶ前処理として使う","端の不連続はアーティファクトの原因。ゼロ埋めと窓の扱いに注意"],mistakes:["FFT表示の明るさがそのまま成分の強さ（対数圧縮されている）","縞の向きとスペクトルの点の向きは同じ（直交する）"],src:"ijfft",terms:["高速フーリエ変換","周波数スペクトル","ローパスフィルタ"],related:["G10","G11"]},
{id:"G13",cat:"seg",title:"閾値処理と大津の方法",lead:"画素値を手がかりに対象と背景を分ける二値化は、定量解析の入り口です。大津の方法の原理は、自動化の考え方の原型でもあります。",
 sections:[
  {h:"二値化とは",b:["閾値処理は、画素値が閾値 T 以上か未満かで画素を2クラスに分ける処理です。出力は対象か背景かを示す二値画像で、面積・個数・形状の測定はこの二値画像を土台に行われます。","閾値の決め方が結果を支配します。手で決める方法は再現性の説明が難しく、ヒストグラムに基づく自動決定法が実務では重視されます。"],fig:null},
  {h:"大津の方法の原理",b:["大津の方法は、閾値で分けた2クラスの「クラス間分散」が最大になる閾値を選びます。クラス間分散が大きいとは、2クラスの平均が離れ、かつそれぞれのクラス内ではばらつきが小さい状態です。","すべての閾値候補についてクラス間分散を計算し、最大のものを採用するため、決定的で再現性があります。ただし前提は「明暗で2クラスに分かれる」ことであり、二峰性が弱い画像では自動的に妥当な閾値になるとは限りません。"],fig:null},
  {h:"大域的処理の限界と適応的閾値",b:["照明むら（シェーディング）がある画像では、場所によって背景レベルが変わるため、単一の閾値では分離できません。適応的閾値処理は、近傍ごとの統計（平均や中央値）から場所ごとの閾値を決める方法です。","ImageJの Auto Local Threshold はこの系統の手法群です。局所化は万能ではなく、窓の大きさが新たなパラメータとして結果に影響します。"],fig:null},
  {h:"大津の方法の導出：分散の分解",b:["大津の方法の背後にあるのは、全分散の分解 σ_T² = σ_W² + σ_B² です。σ_W² はクラス内分散（各クラス内部のばらつきの重み付き平均）、σ_B² はクラス間分散（クラス平均同士の離れ具合）です。全分散 σ_T² は閾値によらず一定なので、クラス間分散の最大化は、クラス内分散の最小化と等価になります。","閾値 t でのクラス間分散は、2クラスの出現確率 ω0(t), ω1(t) と平均 μ0(t), μ1(t) を使って σ_B²(t) = ω0(t) ω1(t) [μ0(t) − μ1(t)]² と書けます。ω と μ はヒストグラムの累積和から全候補について効率よく計算でき、この最大化は統計学の判別分析（1次元の線形判別）と同じ構造をしています。"],fig:null}],
 points:["二値化は測定の土台。閾値の決め方が結果を支配する","大津の方法はクラス間分散最大の閾値を自動決定する","照明むらには適応的（局所）閾値。窓サイズが新たな前提になる"],mistakes:["自動閾値なら常に正しい（前提は二峰性。検証は必要）","閾値は画像が決めるもので条件ではない（手法と前提が結果を変える）"],src:"ocvth",terms:["閾値処理","大津の方法","適応的閾値処理"],related:["G05","G15"]},
{id:"G14",cat:"seg",title:"エッジ検出の考え方",lead:"エッジは「画素値が急に変わる場所」です。勾配に基づく検出の流れと、Cannyの多段階処理が解決した問題を理解します。",
 sections:[
  {h:"エッジと勾配",b:["エッジは対象の境界や構造の境目に対応し、画素値の急変として現れます。勾配（1次微分）の大きさが急変の強さ、方向がエッジの向きを与えます。Sobelなどの微分フィルタで勾配場を作るのが第一歩です。","勾配の大きさに閾値を適用すればエッジ候補が得られますが、それだけでは線が太く、ノイズ由来の点も混ざります。実用的な検出器は、この後に複数の工程を重ねます。"],fig:null},
  {h:"Cannyエッジ検出の工程",b:["Cannyの検出器は、(1) ガウシアン平滑化でノイズを抑え、(2) 勾配を計算し、(3) 非極大抑制でエッジを細線化し、(4) 2つの閾値によるヒステリシスで、強いエッジにつながる弱いエッジだけを残す、という多段階処理です。","ヒステリシスは「単独では弱いが、確かなエッジの延長なら採用する」という考え方で、途切れと誤検出のバランスを取る工夫です。各工程が何を解決しているかを読むと、パラメータの意味が見えてきます。"],fig:null},
  {h:"エッジと領域は相補的",b:["エッジ検出は境界の情報、閾値処理などの領域ベースの手法は内部の情報を扱います。境界が閉じていないと領域は決まらず、領域の均一性が崩れると境界も乱れます。","実務の分割では両者を組み合わせることが多く、形態学演算による穴埋めや整形が橋渡しをします。手法の選択は、対象のコントラストが「面」で出るか「線」で出るかで決まります。"],fig:null},
  {h:"Cannyの設計基準",b:["Cannyの検出器は、場当たり的な工程の寄せ集めではなく、3つの最適化基準から設計されています。(1) 良い検出：本物のエッジを見逃さず、偽のエッジを出さない（信号対雑音比の最大化）。(2) 良い局在：検出位置が本物のエッジ位置に近い。(3) 単一応答：1本のエッジに複数の応答を返さない。","ヒステリシス閾値は基準 (1) の具体化です。高閾値を超えた画素を確かなエッジの種とし、低閾値以上の画素は種につながっている場合にだけ採用することで、検出の確かさと輪郭の接続を両立させています。2つの閾値の比（典型的には2:1〜3:1）が設計パラメータになります。"],fig:null}],
 points:["エッジ検出の基礎は勾配の大きさと方向","Cannyは平滑化→勾配→細線化→ヒステリシスの多段階処理","エッジベースと領域ベースは相補的。対象の出方で選ぶ"],mistakes:["勾配に閾値を掛ければ十分（太さとノイズの問題が残る）","Cannyは単一のフィルタ（複数工程の組み合わせ）"],src:"ocvcanny",terms:["エッジ","画像勾配","Cannyエッジ検出"],related:["G09","G13"]},
{id:"G15",cat:"seg",title:"形態学演算：二値画像の整形",lead:"膨張・収縮を土台に、二値画像の形を整える演算群です。集合論に基づく定義が、見た目の操作に正確な意味を与えます。",
 sections:[
  {h:"膨張と収縮",b:["形態学演算（モルフォロジー演算）は、構造要素と呼ばれる小さな図形を二値画像に当てはめて形を変える処理です。膨張は対象を構造要素の分だけ太らせ、収縮は細らせます。","定義は集合演算で与えられ、ノイズのような小さな突起や穴は、対象本体より先に影響を受けます。この性質がノイズ除去や分離・連結への応用の土台です。"],fig:null},
  {h:"オープニングとクロージング",b:["収縮の後に膨張を行うオープニングは、小さな突起や細い連結を消して形を滑らかにします。逆の順序のクロージングは、小さな穴や切れ目を埋めます。どちらも大きな構造の形はほぼ保ちます。","粒子解析の前処理で「小さなゴミを消す」「輪郭の欠けを埋める」といった操作は、これらの組み合わせです。構造要素の大きさが、消える／残るの境目を決めます。"],fig:null},
  {h:"グレースケールへの拡張と応用",b:["膨張・収縮は、最大値・最小値フィルタとしてグレースケール画像にも拡張できます。背景推定（広い構造要素でのオープニング）や、トップハット変換によるむらの補正がその応用です。","ImageJの背景差分（Subtract Background、ローリングボール）は、形態学的な背景推定と親戚の考え方です。前処理の多くは、形態学の言葉で統一的に説明できます。"],fig:null},
  {h:"集合としての定義と双対性",b:["構造要素 B による膨張は A ⊕ B = {z | (B̂)_z ∩ A ≠ ∅} と定義されます。B̂ は B を原点について反転したもので、(B̂)_z はそれを z だけ平行移動したもの、つまり「構造要素を置いた範囲が対象 A に触れる位置の集合」が膨張です。これはミンコフスキー和と呼ばれる演算です。収縮は A ⊖ B = {z | (B)_z ⊆ A}、構造要素がすっぽり収まる位置の集合です。","この2つには双対性があり、収縮は「背景を膨張させたものの補集合」と等しくなります。また、オープニングとクロージングには冪等性（同じ操作を繰り返しても2回目以降は変わらない）という性質があり、単なる平滑化フィルタとの違いになっています。"],fig:null}],
 points:["膨張・収縮は構造要素で形を変える集合演算","オープニングは突起除去、クロージングは穴・切れ目埋め","グレースケール拡張は背景推定など前処理の基礎"],mistakes:["オープニングとクロージングは逆操作で元に戻る（完全には戻らない）","構造要素の大きさは結果に無関係（消える規模の境目を決める）"],src:"ocvmorph",terms:["膨張","収縮","オープニング","クロージング"],related:["G13","G16"]},
{id:"G16",cat:"feat",title:"形状特徴と画像モーメント",lead:"領域を数値で表す特徴量のうち、面積・重心・周囲長といった基本量と、その一般化である画像モーメントを扱います。",
 sections:[
  {h:"基本の形状量",b:["二値化された領域からは、面積（画素数×1画素の実面積）、重心（画素位置の平均）、周囲長、円形度（4π×面積/周囲長²、真円で1）などの形状量が計算できます。これらは対象の大きさ・位置・形の要約です。","周囲長は画素の階段状の輪郭をどう測るかに依存し、解像度の影響を受けやすい量です。形状量の比較は、同じ取得条件・同じ前処理の範囲でのみ意味を持ちます。"],fig:null},
  {h:"画像モーメント",b:["画像モーメントは、画素位置のべき乗で重み付けした総和 m_pq = ΣΣ x^p y^q f(x, y) で定義される量の族です。0次モーメントは面積（質量）、1次を0次で割ると重心、2次からは広がりや向きが得られます。","重心で正規化した中心モーメント、さらにスケールで正規化したモーメントからは、位置・大きさ・回転に対して不変な特徴（Huモーメント）が構成できます。「不変量を作る」という発想は、特徴設計の基本形です。"],fig:null},
  {h:"特徴量の落とし穴",b:["特徴量は前処理の産物です。閾値が変われば面積も重心も変わります。特徴の差を主張するには、前処理の条件を固定し、その感度を把握しておく必要があります。","また、多数の特徴を機械的に測っても、対象の本質と結びつかなければ解釈できません。特徴量は「何を区別したいか」から逆算して選ぶものです。"],fig:null},
  {h:"Huモーメント：不変量の作り方",b:["不変量は正規化の積み重ねで作ります。まず重心まわりの中心モーメント μ_pq を取り（位置不変）、次に η_pq = μ_pq / μ_00^γ（γ = (p + q)/2 + 1）で割ってスケール不変にします。この正規化モーメントの組み合わせから、Huは回転にも不変な7つの量を構成しました。","例として第1不変量は φ1 = η20 + η02、第2不変量は φ2 = (η20 − η02)² + 4η11² です。φ1 は「重心まわりの広がりの総量」を表し、対象を回転させても拡大縮小しても（理想的には）同じ値になります。ただし次数の高い不変量ほどノイズや量子化の影響を受けやすく、実務では低次の数個を使うことが多い点に注意が必要です。"],fig:null}],
 points:["面積・重心・円形度が基本の形状量。周囲長は解像度依存に注意","モーメントは面積・重心・向きを統一的に与える量の族","特徴量は前処理条件の産物。条件固定と比較が前提"],mistakes:["円形度は解像度によらない（周囲長の測り方に依存する）","特徴は多く測るほど良い（目的から逆算して選ぶ）"],src:"ijana",terms:["重心","画像モーメント","円形度","連結成分"],related:["G15","G17"]},
{id:"G17",cat:"eval",title:"校正と測定の妥当性",lead:"画素単位の数値を、長さ・濃度といった意味のある量に変えるのが校正です。測定の信頼性はここで決まります。",
 sections:[
  {h:"空間校正",b:["空間校正は、1画素が実世界で何 μm かという対応付けです。既知の長さ（スケールバーや対物ミクロメータ）を写し、画素数との比から設定します。面積はこの比の2乗、体積は3乗で効くため、校正の誤差は増幅されます。","対物レンズやカメラを変えれば校正は変わります。倍率ごとに校正を持ち、画像のメタデータと対応付けて管理することが、再現性の土台です。"],fig:null},
  {h:"強度の校正と線形性",b:["画素値を物理量（濃度・蛍光量）として扱うには、既知の濃度の標準試料で画素値との対応（検量線）を取る必要があります。前提は、センサー応答の線形性と、背景（オフセット）の差し引きです。","ガンマが掛かった画像や、8-bitに圧縮された画像では線形性が崩れており、画素値の比が量の比を表しません。定量の前に、取得形式そのものを確認することが必要です。"],fig:null},
  {h:"妥当性の検証",b:["測定の妥当性は、既知の対象を測って真値と比べる、同じ対象を繰り返し測ってばらつきを見る、といった検証で支えられます。前処理（平滑化・二値化）の条件を変えたときに結論がどう動くか（感度分析）も重要な検証です。","自動処理のパイプラインは、途中の1つの前提が崩れると全体が静かに狂います。要所に検証用の既知サンプルを挟む設計が、実務の防御策です。"],fig:null}],
 points:["空間校正の誤差は面積で2乗、体積で3乗に効く","強度の定量には検量線と線形性の確認が前提","真値比較・繰り返し・感度分析で妥当性を支える"],mistakes:["校正は一度すれば終わり（光学構成ごとに変わる）","画素値の比はそのまま量の比（線形性が前提）"],src:"ijana",terms:["空間校正","重心","ダイナミックレンジ"],related:["G02","G16"]},
{id:"G18",cat:"eval",title:"画像圧縮と画質評価",lead:"JPEGに代表される非可逆圧縮の仕組みと、劣化を数値で測るPSNR・SSIMの考え方、そして解析用途での注意をまとめます。",
 sections:[
  {h:"可逆圧縮と非可逆圧縮",b:["可逆（ロスレス）圧縮は、元のデータを完全に復元できる圧縮で、PNGやTIFF（LZW等）が該当します。画素値の統計的な偏り（冗長性）を利用するため、圧縮率は控えめです。","非可逆（ロッシー）圧縮は、人間の目に目立ちにくい成分を捨てることで高い圧縮率を得ます。JPEGはその代表で、捨てられた情報は復元できません。解析用データは可逆形式で保持するのが原則です。"],fig:null},
  {h:"JPEGの仕組みとアーティファクト",b:["JPEGは、画像を8×8画素のブロックに分け、離散コサイン変換（DCT）で周波数成分に直し、高周波成分を粗く量子化することで情報を捨てます。圧縮率を上げるほど、ブロック境界の段差（ブロッキング）や輪郭周りのモスキートノイズが現れます。","これらのアーティファクトは、エッジ検出やテクスチャ解析の結果を汚染します。圧縮画像での測定は、アーティファクトの影響範囲を意識して行う必要があります。"],fig:null},
  {h:"画質の指標：PSNRとSSIM",b:["PSNRは原画像との平均二乗誤差から計算される指標で、値が大きいほど誤差が小さいことを示します。計算は簡単ですが、人間の見た目の印象とはずれやすいことが知られています。","SSIMは輝度・コントラスト・構造の類似度を組み合わせた指標で、見た目との対応がPSNRより良いとされます。どちらの指標も「原画像との近さ」を測るもので、解析タスクへの適否そのものは測っていない点に注意が必要です。"],fig:null},
  {h:"圧縮と評価の数式",b:["画素値の分布 p_i に対するエントロピーは H = −Σ p_i log2 p_i（単位はビット）で定義され、可逆圧縮で達成できる平均符号長の下限を与えます。JPEGのDCTは、8×8ブロックの各行・各列に F(u) ∝ Σ_x f(x) cos((2x + 1)uπ/16) の形の変換を適用するもので、エネルギーを低周波側の少数の係数に集中させる性質（エネルギー圧縮）が圧縮の源泉です。","PSNRは PSNR = 10 log10(MAX²/MSE) と定義されます（MAXは最大画素値、MSEは平均二乗誤差）。例えば8-bit画像で MSE = 100 なら PSNR = 10 log10(255²/100) ≈ 28.1 dB です。SSIMは局所領域ごとに輝度・コントラスト・構造の3つの比較項の積で構成され、画像全体ではその平均を取ります。"],fig:null}],
 points:["解析用データは可逆形式で保持するのが原則","JPEGはDCT＋高周波の粗い量子化。ブロック歪みが解析を汚染する","PSNRは誤差ベース、SSIMは構造ベース。タスク適否は別に判断する"],mistakes:["JPEG保存でも画素値は元どおり（非可逆で失われている）","PSNRが高ければ解析にも適する（近さと適否は別）"],src:"dip",terms:["エントロピー","PSNR","SSIM","離散フーリエ変換"],related:["G10","G17"]},
{id:"G19",cat:"filt",title:"線形フィルタリングの理論：LSI系とインパルス応答",lead:"フィルタを「系」として捉える理論の回です。線形性とシフト不変性が成り立つ世界では、すべてのフィルタが1つの関数で完全に記述できます。",
 sections:[
  {h:"線形シフト不変（LSI）系",b:["フィルタが線形であるとは、入力の和と定数倍が出力の和と定数倍に対応すること（重ね合わせの原理）です。シフト不変とは、入力を平行移動すると出力も同じだけ平行移動すること、つまり場所によって振る舞いが変わらないことです。この2つを満たす系を線形シフト不変（LSI）系と呼びます。","平均フィルタ・ガウシアンフィルタ・微分フィルタはいずれもLSI系です。一方、メディアンフィルタ、形態学演算、バイラテラルフィルタ、適応的閾値処理は、どちらかの性質を満たさない非線形系であり、扱いの理論が異なります。"],fig:null},
  {h:"インパルス応答と畳み込み",b:["LSI系に点（インパルス）を入力したときの出力がインパルス応答 h です。重ね合わせの原理により、任意の入力 f に対する出力は、f の各画素を重みとしてインパルス応答を足し合わせたもの、すなわち畳み込み g = f ∗ h になります。カーネルとはインパルス応答を離散化したものにほかなりません。","この事実が畳み込みの重要性の根拠です。LSIフィルタの設計とは、インパルス応答（カーネル）の設計そのものであり、カーネルを見れば処理の全てが分かります。"],fig:null},
  {h:"周波数応答",b:["インパルス応答のフーリエ変換 H(u, v) を周波数応答と呼びます。畳み込み定理により、出力のスペクトルは G = F・H となるため、周波数応答は「周波数ごとの倍率表」として読めます。|H| が振幅の倍率、H の偏角が位相のずれを表します。","フィルタを縦に2つつなぐ（カスケード）と、全体のインパルス応答は2つの畳み込み、周波数応答は2つの積になります。空間領域で設計するか周波数領域で設計するかは、同じ対象への2つの見方です。"],fig:null}],
 points:["LSI系では出力＝入力とインパルス応答の畳み込み","周波数応答はインパルス応答のフーリエ変換＝周波数ごとの倍率","非線形系（メディアン・形態学など）はこの理論の対象外"],mistakes:["どんなフィルタにも周波数応答が定義できる（LSI系に限る）","カーネルは処理の近似（LSI系では完全な記述）"],src:"dip",terms:["線形シフト不変系","インパルス応答","周波数応答","畳み込み"],related:["G07","G20"]},
{id:"G20",cat:"filt",title:"ガウシアンフィルタの数学",lead:"ガウス関数が特別扱いされるのには理由があります。分離可能性、周波数特性、スケールスペースとの関係を数式で押さえます。",
 sections:[
  {h:"分離可能性",b:["2次元ガウス関数は G(x, y) = g(x)・g(y) と、1次元ガウス関数の積に分解できます。したがって2次元畳み込みは「横方向に1次元フィルタ→縦方向に1次元フィルタ」と分けて実行でき、1画素あたりの乗算回数はカーネル幅を k として k² 回から 2k 回に減ります。","分離可能性はガウシアンとボックスフィルタなどの限られたカーネルの性質です。Sobelのようなカーネルも、微分と平滑化の1次元フィルタへの分解が知られています。大きなカーネルほど分離の効果は大きくなります。"],fig:null},
  {h:"周波数特性と不確定性",b:["ガウス関数のフーリエ変換は、またガウス関数になります。空間での広がり σ に対して、周波数での広がりは反比例します（σ_f = 1/(2πσ)）。空間で局在させようとすると周波数では広がり、その逆も成り立つという不確定性の関係です。","このためガウシアンフィルタの周波数応答は、リンギングの原因になる振動や急峻な遮断を持たず、単調に減衰します。「空間でも周波数でも滑らか」なことが、ガウシアンが既定の平滑化として選ばれる理論的な理由です。"],fig:null},
  {h:"スケールスペースとDoG・LoG",b:["σ を連続的に変えた平滑化画像の族 L(x, y; σ) をスケールスペースと呼びます。ガウシアンによる平滑化は熱の拡散方程式と等価であり、スケールを上げる過程で新しい極大や構造は生まれない（因果性）ことが知られています。この性質が、スケールをまたいだ特徴追跡（SIFTなど）の土台になっています。","異なるσのガウシアンの差 DoG はバンドパス特性を持ち、ガウシアンのラプラシアン LoG の近似になります。LoGのゼロ交差はMarrとHildrethによる古典的なエッジ検出法で、DoGは網膜の受容野のモデルとしても知られます。"],fig:null}],
 points:["ガウシアンは分離可能で、計算量が k² から 2k に減る","ガウス関数のフーリエ変換はガウス関数。リンギングが出ない","スケールスペースでは、スケールを上げても新構造は生まれない"],mistakes:["σを大きくすれば周波数でも局在する（反比例の関係がある）","DoGは平滑化フィルタ（差を取るのでバンドパス）"],src:"ocvfilt",terms:["ガウシアンフィルタ","スケールスペース","LoG","DoG"],related:["G08","G19"]},
{id:"G21",cat:"freq",title:"FFTのアルゴリズム",lead:"DFTの定義式をそのまま計算すると画像サイズでは破綻します。FFTが何を工夫して、どれだけ速いのかを理解します。",
 sections:[
  {h:"計算量の問題",b:["N点のDFTを定義どおりに計算すると、出力1点あたり N 回の乗算が必要で、全体では N² 回になります。2次元画像では行と列に分離できても、1024×1024 の画像では約10億回規模の演算になり、現実的ではありません。","FFT（高速フーリエ変換）は、同じDFTを N log N 回の演算で計算するアルゴリズムの総称です。1024点なら N² = 約100万に対して N log2 N = 約1万と、2桁の差がつきます。FFTは近似ではなく、DFTと数学的に同一の結果を返します。"],fig:null},
  {h:"Cooley–Tukey法の考え方",b:["代表的な Cooley–Tukey 法は、数列を偶数番と奇数番に分け、それぞれのDFTの組み合わせで全体を表す分割統治です。再帰が進むと、回転因子と呼ばれる複素数の重みを掛ける「バタフライ演算」の繰り返しに帰着します。","この分割は数列の長さが2の累乗のときに最も単純になります。それ以外の長さでも混合基数などの方法で計算できますが、実装によっては2の累乗サイズが最速になるため、実務ではサイズ調整が行われます。"],fig:null},
  {h:"ゼロ埋めと窓関数の実務",b:["画像の周囲にゼロを足してからFFTするゼロ埋め（ゼロパディング）は、周波数方向のサンプリングを細かくする（スペクトルを補間する）操作です。ただし元の情報は増えないため、周波数分解能そのものは向上しません。見た目の滑らかさと分解能は別の話です。","DFTは信号が周期的に繰り返されると仮定するため、画像の端同士の不連続がスペクトルに十字状の漏れ（端効果）を作ります。窓関数を掛けて端をなだらかに落とす、周期成分を扱うときは端を切り取る、といった前処理が結果を左右します。"],fig:null}],
 points:["FFTはDFTを N log N で計算する厳密なアルゴリズム","分割統治（偶奇分割＋バタフライ演算）が高速化の核","ゼロ埋めはスペクトルの補間であり、分解能は上がらない"],mistakes:["FFTは近似計算（DFTと同一の結果を返す）","ゼロ埋めで周波数分解能が上がる（情報量は増えない）"],src:"ocvfft",terms:["高速フーリエ変換","離散フーリエ変換","ゼロ埋め"],related:["G10","G12"]},
{id:"G22",cat:"freq",title:"理想フィルタとリンギング：ギブス現象",lead:"周波数フィルタの代表的な失敗であるリンギング。その原因が「遮断の鋭さ」にあることを、ギブス現象から理解します。",
 sections:[
  {h:"理想フィルタの応答",b:["理想ローパスフィルタは、遮断周波数の内側を完全に通し、外側を完全に遮断します。周波数領域では理想的ですが、そのインパルス応答は sinc 関数（sin(x)/x の形）で、空間的に無限に広がりながら振動します。","畳み込みの観点では、出力はこの振動する応答との重ね合わせです。エッジの近くでは応答の波がそのまま現れ、輪郭に沿った波打ち＝リンギングになります。フィルタの「理想」は、見る領域を変えると全く異なる顔を見せます。"],fig:null},
  {h:"ギブス現象",b:["不連続な信号をフーリエ級数で近似すると、不連続点のそばに約9%のオーバーシュート（行き過ぎ）が残ります。項数を増やしても、この行き過ぎの大きさは消えず、幅だけが狭くなります。これがギブス現象です。","理想フィルタによるリンギングは、その画像版です。遮断をどれだけ鋭く設計しても、エッジ近傍の振動は避けられません。対策は遮断そのものを滑らかにすることで、現象の理解がフィルタ選択の指針になります。"],fig:null},
  {h:"実務のフィルタ選択",b:["バターワースフィルタは次数 n で急峻さを調整でき、n を上げるほど理想フィルタに近づく一方でリンギングも増えます。低次のバターワースは穏やかな特性と弱いリンギングの折衷です。ガウシアンフィルタは応答が単調で、リンギングは原理的に生じません。","ノッチフィルタで周期ノイズを落とす場合も、落とし方が急峻だと同様の波打ちが出ます。「周波数で切る」操作は常に空間への副作用とセットであり、結果画像での目視確認が欠かせません。"],fig:null}],
 points:["理想フィルタの空間応答は sinc。振動がリンギングになる","ギブス現象：不連続点の約9%の行き過ぎは消えない","急峻さとリンギングはトレードオフ。ガウシアン型は無振動"],mistakes:["リンギングはパラメータ調整で消せる（遮断の鋭さ自体が原因）","理想フィルタが最良のフィルタ（領域によって評価が逆転する）"],src:"dip",terms:["ギブス現象","バターワースフィルタ","理想フィルタ","ローパスフィルタ"],related:["G11","G21"]},
{id:"G23",cat:"rest",title:"劣化モデルと逆フィルタ",lead:"ぼけた画像を復元する問題の定式化です。劣化を数式で書くことで、単純な逆算がなぜ破綻するのかが見えてきます。",
 sections:[
  {h:"劣化モデル",b:["観測画像 g は、元の画像 f が劣化過程 h を受け、ノイズ n が加わったものとして g(x, y) = (h ∗ f)(x, y) + n(x, y) とモデル化されます。h は劣化のインパルス応答で、ぼけの場合は点像分布関数（PSF）そのものです。","周波数領域では畳み込みが積になるため、G(u, v) = H(u, v) F(u, v) + N(u, v) と書けます。復元とは、この式を F について解く問題です。劣化がLSIであるという前提が、この単純な形の根拠になっています。"],fig:null},
  {h:"逆フィルタとその破綻",b:["ノイズがなければ、F̂ = G/H という割り算で元に戻せます。これが逆フィルタです。しかし H は高周波で小さくなり（ぼけは高周波を落とす）、場所によっては0になります。そのような周波数では、わずかなノイズ N が割り算で巨大に増幅され、復元画像はノイズに埋もれます。","実務の逆フィルタは、|H| が閾値以下の周波数を切り捨てる・倍率に上限を設けるなど、破綻する部分を諦める工夫とセットで使われます。「割り算の分母が小さい場所をどう扱うか」が、復元法すべての中心問題です。"],fig:null},
  {h:"PSFの知識が前提",b:["逆フィルタに限らず、復元には劣化 h の知識が必要です。PSFは、点光源（星像・ビーズ像）を撮影して実測するか、焦点ずれや手ぶれのモデルから推定します。PSFが実物とずれていれば、復元は別のアーティファクト（輪郭の二重化など）を生みます。","劣化モデルは「分かったつもりの前提」の置き場です。復元結果を測定に使う場合は、モデルの妥当性（LSI性、ノイズの性質）自体を検証する必要があります。"],fig:null}],
 points:["劣化モデル：g = h ∗ f + n。周波数では G = HF + N","逆フィルタは H の小さい周波数でノイズを爆発させる","復元にはPSFの実測・推定が前提になる"],mistakes:["逆フィルタで完全に戻せる（ノイズと H のゼロが破綻させる）","ぼけの種類によらず同じ復元でよい（PSFごとに異なる）"],src:"skrest",terms:["劣化モデル","逆フィルタ","デコンボリューション","点像分布関数"],related:["G19","G24"]},
{id:"G24",cat:"rest",title:"ウィーナフィルタと反復復元",lead:"ノイズを織り込んで「平均的に最も良い」復元を求めるのがウィーナフィルタです。その式の読み方と、反復法の位置づけを扱います。",
 sections:[
  {h:"最小平均二乗誤差という基準",b:["ウィーナフィルタは、復元誤差の平均二乗（期待値）を最小にする線形フィルタです。周波数領域での解は F̂ = [H*/(|H|² + S_n/S_f)] G と書けます。H* は H の複素共役、S_n と S_f はノイズと原画像のパワースペクトル（周波数ごとの信号とノイズの強さ）です。","この式の分母が鍵です。|H|² に対してノイズ対信号比 S_n/S_f が大きい周波数では倍率が抑えられ、小さい周波数では逆フィルタに近づきます。「信頼できる周波数は戻し、信頼できない周波数は抑える」という重み付けが、式の形そのものに表れています。"],fig:null},
  {h:"極限の振る舞いと実務の近似",b:["ノイズがゼロなら S_n/S_f = 0 で、式は逆フィルタに一致します。逆に信号がほぼない周波数では倍率は0に近づきます。ウィーナフィルタは逆フィルタと「何もしない」の間を、周波数ごとのSNRで連続的につないだものと読めます。","原画像のパワースペクトル S_f は未知であることが多く、実務では S_n/S_f を定数 K で置き換えた形が使われます。K の選択が復元の強さを決めるため、結果を見ながらの調整と、その記録が再現性の条件になります。"],fig:null},
  {h:"反復復元と正則化",b:["Richardson–Lucy法は、光子計数のポアソンノイズを前提に、最尤推定を反復計算で解く復元法です。画素値が負にならない性質を持ち、蛍光顕微鏡のデコンボリューションで標準的に使われます。反復回数が実質的なパラメータで、増やすほど鮮明になる一方ノイズも増幅します。","これらに共通する考え方が正則化です。解が一意に決まらない・ノイズに弱い不良設定問題に対し、「滑らかさ」などの事前の想定を加えて解を安定させる枠組みで、復元だけでなく画像処理の随所に現れます。"],fig:null}],
 points:["ウィーナフィルタは平均二乗誤差を最小化する線形復元","式は周波数ごとのSNRで逆フィルタと抑制を連続的につなぐ","Richardson–Lucy法はポアソン前提の反復法。正則化が共通の考え方"],mistakes:["ウィーナフィルタはノイズを完全に除く（最適な重み付けであって除去ではない）","反復は多いほど良い（ノイズ増幅とのトレードオフ）"],src:"skrest",terms:["ウィーナフィルタ","Richardson-Lucy法","正則化","デコンボリューション"],related:["G23","G25"]},
{id:"G25",cat:"rest",title:"超解像とHDR",lead:"失われた情報を「複数の観測」から補う2つの技術です。情報がどこから来るのか、という問いに答えられることが理解の条件です。",
 sections:[
  {h:"超解像：複数フレームからの再構成",b:["超解像は、わずかにずれた複数の低解像度フレームから、1枚の高解像度画像を再構成する技術です。各フレームは同じ場面を異なるサブピクセル位置で標本化しているため、位置合わせ（レジストレーション）して統合すると、単一フレームにはない標本点が得られます。","情報の源泉はフレーム間の相補性です。ずれが画素の整数倍だけでは新しい標本は得られず、再構成は劣化モデルの逆問題として解かれます。古典的な超解像は、この意味で復元問題の拡張です。"],fig:null},
  {h:"学習ベース超解像の注意",b:["近年の単一画像超解像は、学習データから「ありそうな高周波」を生成します。見た目は鮮明でも、生成された細部は観測に基づかない場合があり、測定・解析の文脈では実在しない構造を数える危険があります。","画像を「証拠」として扱う用途では、超解像の適用可否は見た目ではなく、生成された情報の由来で判断します。復元と生成は、出力が似ていても科学的な意味が異なります。"],fig:null},
  {h:"HDR：複数露光の合成",b:["HDR（ハイダイナミックレンジ）イメージングは、露光時間を変えた複数枚の撮影から、センサーのレンジを超える明暗を1枚に統合します。飽和した画素は長い露光側が、ノイズに埋もれた暗部は短い露光側が担当できないため、各画素で信頼できる露光を選んで重み付け合成します。前提として、カメラの応答（入力光量と画素値の関係）の推定が必要です。","HDR画像を画面に表示するには、レンジを圧縮するトーンマッピングが要ります。トーンマッピングは画素値と物理量の対応を崩すため、表示用と解析用でデータを分けるのが原則です。"],fig:null}],
 points:["超解像の情報源は、ずれた複数フレームの標本の相補性","学習ベースの生成細部は観測ではない。解析用途では要注意","HDRは複数露光の信頼度つき合成。表示用トーンマッピングは定量性を壊す"],mistakes:["超解像で失われた細部が戻る（複数観測か生成のどちらか）","HDR画像はそのまま定量に使える（応答と合成の前提を確認）"],src:"dip",terms:["超解像","HDR","ダイナミックレンジ"],related:["G02","G24"]},
{id:"G26",cat:"color",title:"色の科学：分光分布と表色系",lead:"色は物理量そのものではなく、光の分光分布に対する視覚系の応答です。RGB値の背後にある仕組みを理解します。",
 sections:[
  {h:"分光分布とメタメリズム",b:["光は波長ごとの強さの分布（分光パワー分布）を持ちます。人間の網膜には3種類の錐体があり、色覚はこの分布を3つの応答値に圧縮した結果です。分布が違っても3つの応答が一致すれば同じ色に見えます。これをメタメリズム（条件等色）と呼びます。","カメラも3チャンネルで色を取るため、同じ原理で「人には同じに見えるがカメラでは違う」「その逆」が起こります。色を数値で扱うとは、分光分布ではなく3つの応答値を扱うことだと意識するのが出発点です。"],fig:null},
  {h:"XYZ表色系と等色関数",b:["CIE XYZ表色系は、等色実験から定められた等色関数に基づいて分光分布を3つの値 X, Y, Z に変換する国際標準の表色系です。Y は明るさ（輝度）に対応するよう設計されています。あらゆる色を負の値なしで表せるため、色の「共通言語」としてデバイス間の変換の仲介に使われます。","RGB表色系は、3原色の加法混色で色を表す方式で、ディスプレイやカメラの都合に根ざした表現です。どのRGBか（sRGB、Adobe RGBなど、原色と白色点の定義）を示さなければ、RGB値は色を一意に定めません。"],fig:null},
  {h:"色空間の変換とYUV",b:["YUV（YCbCr）は、輝度 Y と色差 Cb, Cr に分ける表現です。人間の視覚は輝度の変化に敏感で色の変化に鈍いため、色差を間引く（クロマサブサンプリング）ことで、見た目の劣化を抑えてデータ量を減らせます。動画圧縮の基本的な工夫です。","色空間の変換は多くが線形変換（行列）ですが、ガンマ補正の有無や変換の定義域の違いで結果が変わります。色で定量する解析（比色・色素の分離など）では、作業色空間と変換経路を固定することが再現性の条件です。"],fig:null}],
 points:["色は分光分布への3種の錐体の応答。分布が違っても同じ色になる（メタメリズム）","XYZは標準の共通言語。RGB値は色空間の指定なしでは色を定めない","YUVは輝度と色差の分離。色差の間引きが動画圧縮の基礎"],mistakes:["RGB値そのものが色の絶対的な指定（色空間の定義が前提）","カメラと人で色の見え方が違うのは機械の誤差だけ（原理的なメタメリズムがある）"],src:"skcolor",terms:["分光分布","XYZ表色系","等色関数","YUV"],related:["G27","G28"]},
{id:"G27",cat:"color",title:"カラー画像と画像間演算",lead:"カラー画像の扱い方と、2枚以上の画像を組み合わせる演算です。比率や差分による「割り算の画像化」が解析の道具になります。",
 sections:[
  {h:"カラー画像の構造",b:["カラー画像は、チャンネルと呼ばれるグレースケール画像の組です。RGB画像なら赤・緑・青の3枚が重なっています。処理の多くはチャンネルごとに適用でき、色空間の変換によって「明るさ」と「色合い」を分けて扱うこともできます（G26）。","チャンネル分離は解析の基本操作です。蛍光画像の多重染色では、各チャンネルが異なる標識に対応します。チャンネル間の漏れ込み（ブリードスルー）の評価など、色の扱いはそのまま測定の妥当性に直結します。"],fig:null},
  {h:"画像間演算",b:["画像間演算は、2枚の画像の対応画素同士の四則演算です。差分は変化の検出（背景差分・経時変化）、比（割り算）は照明むらの補正や、蛍光の比率イメージング（レシオメトリ）に使われます。和や平均は複数枚のノイズ低減（加算平均）に使われます。","演算には前提があります。位置が合っていること（位置合わせ）、型と値域の扱い（割り算でのゼロ除算、負値やオーバーフローの処理）です。結果の型（8-bitか float か）で保存される情報が変わるため、演算の設計には型の設計が含まれます。"],fig:null},
  {h:"論理演算とマスク",b:["AND・OR・XORなどの論理演算は、二値画像同士や、二値画像をマスクとして使う処理の言語です。「対象領域の中でだけ測る」「この領域を除外する」といった指定は、マスクとのAND演算として実装されます。","マスクは領域の指示を画像として持ち回る仕組みであり、ROIの考え方を画素単位に拡張したものです。マスクの作り方（どの閾値で切ったか）が、その後の全測定の前提条件になります。"],fig:null}],
 points:["カラー画像はチャンネルの組。分離と変換が基本操作","画像間演算は差分＝変化、比＝むら補正と比率測定、平均＝ノイズ低減","マスクは画素単位のROI。作り方が全測定の前提になる"],mistakes:["割り算は型を気にしなくてよい（ゼロ除算と値域で結果が変わる）","マスクは単なる表示の指定（測定範囲そのものを決める）"],src:"skcolor",terms:["画像間演算","チャンネル","色空間"],related:["G26","G04"]},
{id:"G28",cat:"color",title:"人間視覚系",lead:"画像を見る側の仕組みです。視細胞の応答特性が、画像処理の多くの設計（ガンマ、圧縮、画質評価）の前提になっています。",
 sections:[
  {h:"眼球と視細胞",b:["眼球はレンズで網膜に像を結ぶ光学系で、その意味でカメラの原型です。網膜には、色を担う錐体（3種）と、暗所で働く桿体の2系統の視細胞があります。錐体は網膜中心（中心窩）に密集し、周辺では桿体が主になります。","視細胞の分布は一様ではないため、人間の視覚は「画像全体を均一に記録する装置」ではありません。中心と周辺で解像度も感度も違うという性質が、見た目の評価と機械の測定のずれの一因です。","視細胞の信号が脳へ届くまでの流れが視覚情報経路です。網膜で電気信号に変換された情報は視神経を通り、視交叉で左右の視野ごとに振り分けられて外側膝状体（LGN）で中継され、一次視覚野（V1）へ届きます。V1には特定の向きの線分にだけ反応する細胞（HubelとWieselが発見した方位選択性細胞）があり、「網膜像そのもの」ではなく「向きのある輪郭」という特徴の形で処理が進むことが分かっています。画像処理のエッジ検出が初期視覚の仕組みと響き合うのは、この経路の出発点に理由があります。"],fig:null},
  {h:"対数応答とコントラスト感度",b:["視覚の明るさ応答はおおむね対数的で、絶対値ではなく比率（コントラスト）に反応します（ウェーバー・フェヒナーの法則）。同じ1段の差でも、暗部では知覚でき、明部では知覚できない、という非線形性がガンマ補正や対数表示の根拠です。","空間周波数への感度は一様ではなく、中間の周波数で最も高く、高周波と低周波で下がる帯域特性を持ちます（コントラスト感度関数）。JPEGが「目立ちにくい成分」を捨てられるのは、この特性に依存しています。"],fig:null},
  {h:"知覚の効果：マッハバンドなど",b:["明暗の境界では、実際にはない明るい帯と暗い帯が見えるマッハバンドという現象があります。側抑制という網膜の仕組みが境界を強調するためで、視覚が「エッジを強調するフィルタ」を内蔵していることの現れです。","同時対比（同じ灰色が周囲で違って見える）など、知覚は絶対値ではなく相対関係で決まります。画像の目視評価は便利ですが、この系統の効果を理解していないと、表示上の印象をデータの性質と取り違えます。"],fig:null}],
 points:["視覚は錐体3種＋桿体。分布は不均一で、記録装置ではない","明るさ応答は対数的。コントラスト感度は帯域特性を持つ","マッハバンドなど、視覚自体がエッジ強調と相対評価を行う"],mistakes:["目で見た明るさが画素値に比例する（対数的な応答）","視覚評価は客観的（同時対比などの系統的効果がある）"],src:"dip",terms:["視細胞","マッハバンド","コントラスト感度"],related:["G26","G18"]},
{id:"G29",cat:"geom",title:"幾何変換と補間",lead:"画像の形を変える処理です。座標の写像と、格子点の間に値を埋める補間の2つに分けて理解します。",
 sections:[
  {h:"座標変換としての幾何変換",b:["幾何変換は、画素値ではなく画素の位置を変える処理です。並進・回転・拡大縮小・反転などが基本形で、出力画像の各画素が入力画像のどの位置に対応するかを、座標の写像で定めます。","実装では、出力側の格子点から入力側の座標を逆向きにたどる（逆写像）のが原則です。入力側から順に写すと、出力に穴（値の定まらない画素）が開くためです。逆写像で得られる入力座標は一般に格子点の間にあるため、補間が必要になります。"],fig:null},
  {h:"補間法の比較",b:["最近傍補間は最も近い格子点の値をそのまま使います。値は元の集合から外れませんが、輪郭が階段状になります。双線形補間は周囲4点の距離に応じた重み付き平均で、滑らかですがややぼけます。双三次補間は16点を使い、より滑らかでシャープな結果が得られますが、輪郭付近で値域を超える振動（オーバーシュート）が出ることがあります。","測定用の画像では、補間が画素値を「作る」操作であることを意識します。分類済みのラベル画像に双線形補間を使うと、存在しないラベル値が生まれるため、最近傍が必須、といった使い分けが典型です。"],fig:null},
  {h:"回転と再標本化の注意",b:["回転や拡大縮小は再標本化を伴い、標本化定理の制約を受けます。縮小では先にローパスで高周波を落とさないとエイリアシング（モアレ）が生じます。拡大では情報は増えず、補間の滑らかさが変わるだけです。","変換を繰り返すたびに補間の劣化が蓄積します。複合変換は行列を合成して1回で適用するのが原則で、これは後のアフィン変換・射影変換（G30）の話につながります。"],fig:null}],
 points:["幾何変換は座標の写像。実装は逆写像＋補間が原則","補間は最近傍・双線形・双三次で性質が違う。用途で選ぶ","縮小には事前のローパスが必要。変換の繰り返しは劣化が蓄積する"],mistakes:["拡大すれば細部が見えるようになる（補間は情報を増やさない）","ラベル画像にも滑らかな補間でよい（存在しない値が生まれる）"],src:"ocvgeo",terms:["幾何変換","双線形補間","最近傍補間"],related:["G30","G01"]},
{id:"G30",cat:"geom",title:"アフィン変換と射影変換：同次座標",lead:"幾何変換を統一的に表す道具が同次座標と変換行列です。カメラの見え方までつながる、画像処理の基礎言語です。",
 sections:[
  {h:"同次座標と変換行列",b:["同次座標は、2次元の点 (x, y) を3次元ベクトル (x, y, 1) と表す方法です。これにより、並進を含む変換を3×3行列の掛け算1つで表せます。回転・拡大・せん断・並進の合成も、行列の積として1つの変換にまとめられます。","変換を「行列の積」で扱えることは、複合変換を1回の再標本化で実行できる（G29の劣化蓄積を避ける）ことと、変換の逆変換・分解が代数的に扱えることの両方を意味します。"],fig:null},
  {h:"アフィン変換と射影変換",b:["アフィン変換は、3×3行列の下段が (0, 0, 1) の変換で、平行線を平行線に写し、直線性と平行性が保たれます。回転・並進・拡大縮小・せん断がこの仲間です。3組の対応点があれば変換が一意に決まります。","射影変換（ホモグラフィ）は下段も一般の値を取る変換で、平行線が一点に集まるような写り方（平面を斜めから見た像）まで表せます。4組の対応点で決まり、文書画像の台形補正やパノラマ合成（G37）の土台になります。"],fig:null},
  {h:"変換の推定と誤差",b:["実務では対応点から変換を推定します。対応点には測定誤差や誤対応が混ざるため、最小二乗で当てはめる、RANSACなどで外れ値を除く、といった推定の手続きが結果を左右します。","変換後のずれ（再投影誤差）を評価に使うのが原則で、対応点の数と分布（画面の一角に偏っていないか）が推定の安定性を決めます。幾何変換は「式」だけでなく「推定の設計」まで含めて1つの技術です。"],fig:null}],
 points:["同次座標で並進も行列の積に統一できる","アフィン変換は平行性を保つ（3点で決定）、射影変換は4点で決定","実務では対応点からの推定と再投影誤差の評価が要になる"],mistakes:["アフィン変換で台形の写りも直せる（射影変換が必要）","対応点は多ければよい（分布と外れ値の処理が重要）"],src:"ocvgeo",terms:["アフィン変換","射影変換","同次座標"],related:["G29","G37"]},
{id:"G31",cat:"seg",title:"ラベリングと細線化",lead:"二値画像から「個々の対象」を取り出すラベリングと、形を線に痩せさせる細線化です。数える・測る処理の実務的な中核です。",
 sections:[
  {h:"連結成分とラベリング",b:["ラベリング（連結成分ラベリング）は、つながっている画素の集まり（連結成分）ごとに異なる番号を振る処理です。これにより「対象の個数」「対象ごとの面積・重心」が定義できるようになります。粒子解析の土台です。","連結の定義には、上下左右の4連結と、斜めも含む8連結の2通りがあります。対象に8連結を使う場合、背景には4連結を使うのが整合的とされ、定義の選び方で対象の個数自体が変わります。穴の数え方などもこの選択に依存します。"],fig:null},
  {h:"細線化とスケルトン",b:["細線化は、領域の形を保ちながら幅を1画素の線（スケルトン）に痩せさせる処理です。得られる線は領域の中心軸に相当し、分岐点や端点の数が、形のトポロジー（つながり方）を表します。血管や神経突起の分岐解析、文字の構造解析などに使われます。","細線化は境界の小さな凹凸に敏感で、輪郭のノイズが余分な枝（棘）を作ります。実務では平滑化や棘の除去とセットで使います。トポロジーを保存することがアルゴリズムの設計条件です。"],fig:null},
  {h:"距離変換との関係",b:["距離変換は、各対象画素について「最も近い背景画素までの距離」を値として与える処理です。細線化の中心軸は距離変換の尾根に一致し、距離の最大値は内接円の半径を与えます。","距離変換は、くっついた対象の分離（分水嶺処理の前段）や、太さの測定にも使われます。二値画像の「形の情報」を「値の情報」に変換する橋渡しです。"],fig:null}],
 points:["ラベリングは連結成分に番号を振る処理。連結の定義で個数が変わる","細線化はトポロジーを保ちながら中心軸を抽出する","距離変換は形を値に変え、分離や太さ測定の土台になる"],mistakes:["4連結と8連結は好みの問題（数える対象自体が変わる）","細線化すれば輪郭のノイズは消える（枝として増幅される）"],src:"ijana",terms:["連結成分","ラベリング","細線化"],related:["G15","G32"]},
{id:"G32",cat:"seg",title:"領域分割とクラスタリング",lead:"閾値が使えない場面では、特徴空間でのグループ分けが分割の原理になります。k-meansを中心に、クラスタリングによる分割を理解します。",
 sections:[
  {h:"特徴空間での分割",b:["領域分割は、画素を「似た者同士」のグループに分ける問題として定式化できます。画素値そのもの、色、テクスチャ、位置などを特徴ベクトルとし、特徴空間でクラスタリングすれば、ラベルが領域の候補になります。大津の方法は、特徴が画素値1次元の場合の特別な例と見なせます。","この見方では、分割の質は「特徴の選び方」と「似ているの定義（距離）」で決まります。アルゴリズムの選択より、特徴設計が結果を支配する点が重要です。"],fig:null},
  {h:"k-meansとその仲間",b:["k-means法は、クラスタ中心との距離の二乗和を最小化するよう、割り当てと中心の更新を繰り返す方法です。クラスタ数 k を先に決める必要があり、初期値によって局所解に落ちるため、複数回の実行や初期化の工夫が前提になります。","混合ガウスモデル（GMM）は、各クラスタを確率分布として表し、所属を確率で与える拡張です。mean shift は密度の高い方向へ点を移動させて峰を探す方法で、クラスタ数を事前に決めない分割ができます。それぞれ「クラスタの形の想定」が異なります。"],fig:null},
  {h:"空間的なまとまりへの配慮",b:["特徴だけで分けると、空間的にバラバラな画素が同じラベルになり、ノイズ状の小領域が大量に生まれます。実務では、位置を特徴に混ぜる、後処理で小領域を統合する、平滑化項を持つ最適化（G33）を使う、などで空間的な整合性を取り戻します。","分割の評価は目視だけでなく、既知の正解（手作業の注釈）との一致度で行います。クラスタリングは教師なしの方法ですが、評価には教師データが要るという点も実務の構造です。"],fig:null}],
 points:["分割は特徴空間でのクラスタリングとして定式化できる","k-meansは距離二乗和の最小化。kと初期値が前提になる","特徴のみの分割は空間的に乱れる。後処理や平滑化項で補う"],mistakes:["クラスタリングなら閾値の前提が要らない（特徴と距離の前提に置き換わる）","k-meansは実行すれば最適解（局所解に落ちうる）"],src:"dip",terms:["クラスタリング","k-means法","領域分割"],related:["G13","G33"]},
{id:"G33",cat:"seg",title:"動的輪郭モデルとグラフカット",lead:"分割を「エネルギーの最小化」として解く2つの代表手法です。局所的な手がかりと大域的な整合性をどう両立させるかが主題です。",
 sections:[
  {h:"動的輪郭モデル（スネーク）",b:["動的輪郭モデルは、輪郭を表す曲線にエネルギーを定義し、それを最小化する形へ曲線を変形させる方法です。エネルギーには、曲線の滑らかさを保つ内部エネルギーと、画像のエッジに引き寄せる外部エネルギー（画像エネルギー）が入ります。","初期位置から局所的に変形していくため、初期輪郭の置き方に結果が依存します。エッジが弱い場所では漏れやすく、強いパラメータ設定は輪郭を単純化しすぎます。局所最適化の長所と短所を体現した手法です。"],fig:null},
  {h:"グラフカット",b:["グラフカットは、画素をグラフのノードとし、「画素値がラベルに合うコスト」と「隣同士でラベルが違うことへの罰金（平滑化項）」の合計を、グラフの最小カットで大域的に最小化する枠組みです。2値ラベルの場合、正確な大域最適解が得られることが理論的に保証されています。","平滑化項の重みが、境界の滑らかさと細部の保持のバランスを決めます。スネークの局所変形と対照的に、初期位置への依存が小さい代わり、エネルギーの設計そのものが結果を支配します。"],fig:null},
  {h:"最適化としての分割",b:["この2手法に共通するのは、「分割＝目的関数の最小化」という定式化です。何を良い分割とするかを式で書き、その解法を選ぶ、という構造は、近年の学習ベースの手法にも通じる見方です。","手法の比較では、解の質だけでなく、大域最適性の保証の有無、計算量、パラメータの解釈しやすさが観点になります。万能な手法はなく、前提（エッジの強さ、領域の均一性）への適合で選びます。"],fig:null}],
 points:["スネークは輪郭のエネルギーを局所的に最小化する。初期位置に依存","グラフカットは2値で大域最適解が保証される枠組み","分割を目的関数の最小化と見る定式化が共通の土台"],mistakes:["グラフカットは常に正しい分割（最適なのは定義したエネルギーの中だけ）","スネークは初期位置によらない（局所最適化なので依存する）"],src:"dip",terms:["動的輪郭モデル","グラフカット","エネルギー最小化"],related:["G32","G14"]},
{id:"G34",cat:"feat",title:"テクスチャ特徴量",lead:"模様の統計的な性質を数値化する特徴量です。同時生起行列（GLCM）を中心に、テクスチャ解析の発想を理解します。",
 sections:[
  {h:"テクスチャとは何を測るのか",b:["テクスチャは、画素値の空間的な arrangement（並び方）の性質です。単一画素の値でも、領域全体の平均でも捉えられず、「近傍の画素同士の関係」を統計化する必要があります。粗い・細かい・方向性がある、といった質感の言葉を数値に翻訳するのがテクスチャ特徴量です。","組織画像の分類、表面検査、リモートセンシングの土地被覆分類など、形ではなく「模様」で区別するタスクの主役になります。"],fig:null},
  {h:"同時生起行列（GLCM）とHaralick特徴",b:["GLCMは、距離 d・方向 θ を指定した画素のペアについて、値の組み合わせ (i, j) の出現頻度を数えた行列です。模様の繰り返しの統計がこの行列に凝縮されます。","GLCMからは、コントラスト（値の差の大きさ）、均一性、相関、エントロピーなどの指標（Haralick特徴）が計算できます。距離と方向の選び方で見える模様が変わるため、対象のスケールに合わせた設定と、複数方向の平均などの扱いが前提になります。"],fig:null},
  {h:"LBPと他のアプローチ",b:["局所バイナリパターン（LBP）は、中心画素と近傍画素の大小関係を符号化したパターンで、照明の単調な変化に強いテクスチャ記述です。計算が軽く、顔認識などで広く使われました。","ガボールフィルタのような周波数・方向選択的なフィルタ群の応答統計も、テクスチャの有力な表現です。どの表現も「どのスケール・どの関係を見るか」の選択であり、タスクと対象に依存して決まります。"],fig:null}],
 points:["テクスチャは近傍画素の関係の統計。単独の画素値では決まらない","GLCMは画素ペアの値の組み合わせの頻度行列。Haralick特徴の源","距離・方向・スケールの選択が特徴の意味を決める"],mistakes:["テクスチャは画像の粗さそのもの（定義した統計量を通した表現）","GLCMは方向によらない（方向パラメータを持つ）"],src:"skfeat",terms:["テクスチャ","同時生起行列","LBP","エントロピー"],related:["G16","G36"]},
{id:"G35",cat:"feat",title:"テンプレートマッチングとハフ変換",lead:"「探すものの形が分かっている」ときの2つの古典的手法です。相関による探索と、投票による形状検出を対比します。",
 sections:[
  {h:"テンプレートマッチング",b:["テンプレートマッチングは、探したい小画像（テンプレート）を対象画像の上で滑らせ、各位置で類似度を計算し、最も似た位置を答えとする方法です。類似度には差の二乗和や正規化相互相関が使われます。正規化相関は、平均と分散で割ることで、明るさのオフセットとゲインの違いに強くなります。","弱点は、回転・拡大縮小・変形に弱いことです。テンプレートと全く同じ見え方のものしか探せません。位置合わせの初期推定や、工業検査のような条件の固定された場面で力を発揮します。"],fig:null},
  {h:"ハフ変換：投票による直線検出",b:["ハフ変換は、エッジ点が「自分を通る直線の候補すべて」に投票し、票の集まった直線を検出する仕組みです。直線を傾きと切片ではなく、原点からの距離 ρ と角度 θ で表す（ρ = x cosθ + y sinθ）と、1つのエッジ点はパラメータ空間で1本の曲線に対応し、共線な点群の曲線は1点で交わります。","投票という発想により、一部が欠けた直線や、ノイズの中の直線も検出できます。円や一般形状への拡張（一般化ハフ変換）も同じ原理です。パラメータ空間の刻みと票の閾値が、検出の細かさと誤検出のバランスを決めます。"],fig:null},
  {h:"2つの手法の対比",b:["テンプレートマッチングは「見え方そのもの」を探し、ハフ変換は「幾何学的な構造」を探します。前者は画素値の一致、後者はエッジの配置の一致が手がかりです。","どちらも、探す対象のモデルが明確なときに強い手法です。モデルから外れた変形への弱さが、後の特徴点ベースの手法（G36・G37）への動機になりました。"],fig:null}],
 points:["テンプレートマッチングは相関の最大位置を探す。正規化相関は明るさ変化に強い","ハフ変換はパラメータ空間への投票で形状を検出する","モデルが明確な対象に強い。変形への弱さが共通の限界"],mistakes:["ハフ変換は直線そのものをなぞる（投票の集積で判定する）","正規化しない相関で十分（明るさの差に引っ張られる）"],src:"ocvhough",terms:["テンプレートマッチング","ハフ変換","正規化相関"],related:["G36","G14"]},
{id:"G36",cat:"feat",title:"特徴点検出：HarrisとFAST",lead:"画像の中の「目立つ点」を自動で見つける検出器です。構造テンソルによるHarrisの原理と、高速化のFASTを扱います。",
 sections:[
  {h:"なぜ特徴点か",b:["画像同士の対応付け（マッチング）では、全部の画素ではなく、局所的に特徴のある点（コーナーなど）を選んで対応させる方が、効率的で安定します。平坦な場所は位置が定まらず、直線状のエッジは線方向の位置が定まらないため、2方向に変化のあるコーナーが理想的です。","検出器への要求は、視点や照明が変わっても同じ物理点に再現よく検出されること（再現性）と、位置が正確なことです。この要求が検出器の設計を決めます。"],fig:null},
  {h:"Harris：構造テンソルによる判定",b:["Harrisの方法は、近傍の勾配から構造テンソル M（勾配の外積の重み付き平均）を計算し、その固有値 λ1, λ2 で局所構造を分類します。両方大きい＝コーナー、一方だけ大きい＝エッジ、両方小さい＝平坦、という判定です。","固有値を直接計算する代わりに、応答 R = det(M) − k (trace M)² を使うのが実装上の工夫です。det は固有値の積、trace は和に対応し、R が大きく正の場所がコーナーになります。k は経験的な定数（0.04〜0.06程度）です。"],fig:null},
  {h:"FASTと検出器の系譜",b:["FASTは、中心画素と周囲の円上の画素の明暗の並び（連続した明るい画素／暗い画素の弧があるか）だけでコーナーを判定する高速な検出器です。単純な比較の繰り返しで判定でき、リアルタイム処理に向きます。","検出器は「どこを見るか」だけを決め、その点の近傍を記述する記述子（G37）と組み合わせて使います。検出と記述は分業であり、組み合わせの自由度が手法の多様性を生んでいます。"],fig:null}],
 points:["対応付けには2方向に変化のあるコーナーが適する","Harrisは構造テンソルの固有値で平坦・エッジ・コーナーを分類する","FASTは円周上の明暗パターンで高速に判定する"],mistakes:["エッジ上の点は対応付けに最適（線方向の位置が定まらない）","特徴点の検出と記述は一体（分業で組み合わせられる）"],src:"skfeat",terms:["特徴点","構造テンソル","Harrisコーナー検出","FAST"],related:["G35","G37"]},
{id:"G37",cat:"feat",title:"特徴量記述とマッチング：SIFT・ORBとパノラマ",lead:"検出した特徴点を、視点変化に強い数値の組（記述子）に変換し、画像同士を対応付ける技術です。パノラマ合成まで一気につなげます。",
 sections:[
  {h:"記述子の役割とSIFT",b:["記述子は、特徴点の近傍の見え方を、回転やスケール、照明の変化に強い形で数値化したものです。SIFTは、スケールスペース（G20）で特徴点を検出し、主方向を決めて向きを正規化した上で、近傍の勾配方向のヒストグラムを記述子とする古典的な手法です。","この「検出→向きとスケールの正規化→勾配統計の記述」という構成が、後の多くの手法の原型になりました。特許の関係で長く利用が制限され、現在は期限切れにより自由に使えます。"],fig:null},
  {h:"ORB・KAZEとマッチング",b:["ORBは、FAST検出器とBRIEFという二値記述子を組み合わせ、回転への対応を加えた高速な手法です。記述子が二値列であるため、距離計算（ハミング距離）が高速で、リアルタイム用途に向きます。KAZEは非線形スケールスペースを使い、ぼかし方を画像内容に適応させる系統です。","対応付けは、記述子同士の距離が近いペアを探すことで行います。誤対応は避けられないため、距離の比によるふるい分け（最近傍と2番目の比）や、RANSACによる幾何学的な検証（対応点群と整合する変換を多数決的に推定）が必須の後段になります。"],fig:null},
  {h:"パノラマ合成の流れ",b:["パノラマ作成は、特徴点マッチングの代表的な応用です。手順は、(1) 各画像で特徴点を検出・記述し、(2) 対応点から射影変換（ホモグラフィ、G30）を推定し、(3) 全画像を共通の平面に写し、(4) 継ぎ目を選んでブレンドする、という流れです。","露光差の補正や、継ぎ目の位置の最適化（シーム探索）が、見た目の自然さを決めます。各段階がこれまでのレッスンの要素（特徴・幾何変換・画像間演算）の組み合わせになっている点が、この応用の教育的価値です。"],fig:null}],
 points:["記述子は近傍の見え方を変化に強い数値に変換する","マッチングには距離のふるい分けとRANSACによる検証が必須","パノラマは特徴対応→射影変換→ブレンドの統合応用"],mistakes:["記述子の距離が近いペアは全て正対応（誤対応の除去が前提）","パノラマは画像を並べるだけ（幾何推定と継ぎ目処理が本質）"],src:"ocvfeat2d",terms:["記述子","SIFT","ORB","RANSAC"],related:["G36","G30"]},
{id:"G38",cat:"video",title:"動画像処理と動きの検出",lead:"時間軸が加わった画像処理です。背景差分とフレーム間差分という、動きを捉える最も基本的な2つの仕組みを理解します。",
 sections:[
  {h:"動画像の構造",b:["動画像は、空間2次元に時間軸を加えた3次元のデータ f(x, y, t) です。フレームレート（1秒あたりのフレーム数）が時間方向の標本化間隔を決め、G01の標本化の議論が時間方向にもそのまま当てはまります。速すぎる動きはフレーム間で大きくずれて、対応付けが破綻します（時間方向のエイリアシング）。","処理の基本単位はフレームですが、動きの情報はフレームの「間」にあります。動画像処理の多くの手法は、時間方向の差や関係をどう取るかという設計です。"],fig:null},
  {h:"フレーム間差分と背景差分",b:["フレーム間差分は、連続するフレーム同士の差の絶対値を閾値処理し、変化した画素を抽出します。実装は単純ですが、抽出されるのは動く物体の輪郭部分（前後の両端）であり、内部は抜けること、一様な物体では全体像が得られないことが弱点です。","背景差分は、あらかじめ用意した背景画像（または背景モデル）と現在フレームの差を取り、背景から外れた画素を前景とする方法です。物体の全体像が得られますが、照明の変化や、背景自体の変動（木の揺れ、水面）への対処が要ります。実務の背景モデルは、画素ごとに分布を持ち、時間で更新される統計モデル（混合ガウスなど）として実装されます。"],fig:null},
  {h:"動き検出の評価と前提",b:["どちらの方法も、カメラが固定されていることが前提です。カメラ自体が動けば画面全体が「変化」になり、手ぶれ補正や背景の位置合わせが前段に必要になります。","検出結果はノイズ状の小領域や穴を含むため、形態学演算（G15）による整形が定番の後処理です。動画像処理は、静止画処理の部品の組み合わせに、時間方向の設計を加えたものだと分かります。"],fig:null}],
 points:["動画像は f(x, y, t)。フレームレートは時間方向の標本化","フレーム間差分は輪郭だけ、背景差分は全体像が得られる","固定カメラが前提。背景は統計モデルとして更新される"],mistakes:["フレーム間差分で動く物体の全体が取れる（変化した部分だけ）","背景差分は背景画像1枚で完結する（変動へのモデル化が要る）"],src:"ocvbg",terms:["背景差分","フレーム間差分","動画像"],related:["G39","G27"]},
{id:"G39",cat:"video",title:"オプティカルフローと物体追跡",lead:"画素の「動きベクトル」を推定するオプティカルフローと、推定と予測を組み合わせる追跡フィルタの考え方です。",
 sections:[
  {h:"オプティカルフローと亮度恒常",b:["オプティカルフローは、画像上の各点がフレーム間でどちらへどれだけ動いたかという見かけの速度場です。基本仮定は亮度恒常：点の明るさは短時間では変わらない、というものです。この仮定を変分すると、勾配と時間微分を結ぶ拘束式 I_x u + I_y v + I_t = 0 が得られます。","拘束式は1本で未知数 (u, v) が2つあるため、このままでは解けません（開口問題）。解くには追加の仮定が必要です。Lucas–Kanade法は近傍で同じ動きを共有すると仮定して最小二乗で解き、Horn–Schunck法は場全体の滑らかさを正則化として加えます。どちらも「仮定の置き方」が手法の正体です。"],fig:null},
  {h:"追跡：予測と更新",b:["物体追跡は、検出と、時間方向の予測を組み合わせます。カルマンフィルタは、対象の状態（位置・速度など）に線形な運動モデルと観測モデルを置き、予測と観測による修正を繰り返す枠組みです。誤差がガウス分布に従う前提で、最適な推定が解析的に得られます。","パーティクルフィルタは、状態の候補（粒子）を多数持ち、それぞれを観測との合致度で重み付けして分布を近似する方法です。非線形・多峰性の分布も扱える代わりに、計算量と粒子の設計が課題になります。追跡の枠組みの選択は、運動と観測の性質の想定で決まります。"],fig:null},
  {h:"検出と追跡の分業",b:["実務の追跡系は、毎フレーム検出して対応付ける方式（tracking by detection）が主流で、フローやフィルタは対応付けの補助・欠落の補間に使われます。ID の取り違えや、遮蔽（オクルージョン）からの復帰が評価の焦点です。","動画像の解析では、1フレームの精度だけでなく、時間方向の一貫性が品質を決めます。評価指標も、検出精度と追跡の継続性を分けて測るのが普通です。"],fig:null}],
 points:["オプティカルフローは亮度恒常の仮定から拘束式が立つ。追加仮定で解く","カルマンフィルタは線形・ガウス前提の予測と更新","パーティクルフィルタは粒子の重みで分布を近似する"],mistakes:["フローは物体の真の3次元運動（見かけの2次元運動）","拘束式だけでフローが決まる（未知数2に式1本。仮定が要る）"],src:"ocvflow",terms:["オプティカルフロー","カルマンフィルタ","パーティクルフィルタ"],related:["G38","G09"]},
{id:"G40",cat:"recog",title:"パターン認識の基礎",lead:"特徴量を「判断」に変える仕組みです。学習の種類と、代表的な識別器の考え方を押さえます。",
 sections:[
  {h:"学習の3つの形",b:["教師あり学習は、正解ラベルの付いたデータから入出力の対応を学びます。分類（離散ラベル）と回帰（連続値）が代表です。教師なし学習はラベルなしに構造を探し、クラスタリング（G32）がその例です。半教師あり学習は、少量のラベル付きと大量のラベルなしを組み合わせます。","画像の文脈では、学習データの作り方（注釈の基準、クラスの偏り）が性能を大きく左右します。識別器の選択より、データの設計と評価の設計が先に来るのが実務の順序です。"],fig:null},
  {h:"kNNとSVM",b:["k近傍法（kNN）は、特徴空間で最も近い k 個の学習サンプルの多数決で分類する、最も素朴な識別器です。学習は事実上データの保持であり、距離の定義と特徴のスケーリングが性能を決めます。","サポートベクトルマシン（SVM）は、2クラスの間に最も広いマージン（余白）を持つ分離面を求める方法です。マージンの最大化が汎化性能の根拠とされ、カーネル法により非線形な分離も扱えます。サポートベクトルと呼ばれる境界近傍のサンプルだけが解を決める点が特徴です。"],fig:null},
  {h:"アンサンブルと顔検出",b:["Boosting は、弱い識別器を順に訓練し、誤りを重み付けして組み合わせる方法です。Viola–Jones の顔検出は、Haar状の特徴と AdaBoost、さらに識別器のカスケード（簡単な段で大半を棄却）を組み合わせ、リアルタイム顔検出を実現した古典的な成果です。","ランダムフォレストは、データと特徴のランダムな部分集合で多数の決定木を育て、投票で決めるアンサンブルです。これらに共通するのは、単体の工夫より「組み合わせと評価の設計」が性能を作るという視点です。"],fig:null}],
 points:["教師あり・なし・半教師ありはラベルの使い方の違い","kNNは距離の設計、SVMはマージン最大化が核","Boostingとランダムフォレストは弱い判断の組み合わせで強くする"],mistakes:["識別器の選択が性能の全て（データと評価の設計が先）","kNNに学習は不要だが設計も不要（距離とスケーリングが本質）"],src:"dip",terms:["教師あり学習","k近傍法","サポートベクトルマシン","ランダムフォレスト"],related:["G32","G41"]},
{id:"G41",cat:"recog",title:"ニューラルネットワークとCNN",lead:"深層学習の最小構成を理解します。多層パーセプトロンの学習の仕組みと、画像に特化したCNNの構造です。",
 sections:[
  {h:"多層パーセプトロンと誤差逆伝播",b:["多層パーセプトロン（MLP）は、重み付き和と非線形な活性化関数を単位とする層を重ねたモデルです。非線形性がなければ、層を重ねても全体は1つの線形変換に潰れてしまいます。活性化関数の存在が、複雑な関数の近似を可能にします。","学習は、出力と正解の誤差を定義し、その勾配を出力側から入力側へ連鎖率で伝える誤差逆伝播法で重みを更新します。学習率、初期値、正則化などの設計が、収束と汎化を左右します。"],fig:null},
  {h:"CNNの構造",b:["畳み込みニューラルネットワーク（CNN）は、画像の局所性と平行移動への頑健さを構造に埋め込んだモデルです。畳み込み層はカーネル（学習される重み）を画像に適用し、同じ重みを全位置で共有します。プーリング層は近傍の代表値（最大値など）を取って解像度を落とし、位置のずれへの鈍感さと計算量の削減を得ます。","重み共有により、MLPで全結合するよりパラメータ数が大幅に減り、画像の統計に合った学習ができます。G07の畳み込みが、ここでは「学習されるフィルタ」として再登場している点に注目してください。"],fig:null},
  {h:"物体検出と利用上の注意",b:["物体検出は、分類に位置（矩形）の推定を加えたタスクです。領域候補を出して分類する系統と、格子ごとに直接予測する系統（YOLOなど）があり、精度と速度の設計が異なります。セグメンテーションへの拡張（ピクセル単位の分類）も同じ系譜です。","深層学習の性能は学習データに強く依存し、分布の異なる画像では静かに失敗します。解析・測定の文脈では、学習ベースの出力は「検証が必要な推定」として扱い、従来手法との役割分担を設計することが重要です。"],fig:null}],
 points:["MLPは非線形な層の重ね合わせ。学習は誤差逆伝播による勾配更新","CNNは重み共有の畳み込みとプーリングで画像の構造に合わせる","性能はデータ依存。測定文脈では出力は検証対象の推定"],mistakes:["層を深くすれば自動的に賢くなる（データと設計が前提）","CNNの畳み込みは固定フィルタ（重みは学習される）"],src:"dip",terms:["畳み込みニューラルネットワーク","誤差逆伝播法","プーリング"],related:["G40","G07"]},
{id:"G42",cat:"cam",title:"カメラモデルと撮像過程",lead:"3次元の世界が2次元の画像になる幾何を扱います。ピンホールモデルを基準に、レンズの現実と撮像素子の役割を重ねます。",
 sections:[
  {h:"ピンホールカメラモデルと透視投影",b:["ピンホールカメラは、すべての光線が1点（投影中心）を通って像面に届く理想モデルです。このとき像の位置は、焦点距離 f と対象の位置 (X, Y, Z) に対して x = f X/Z のように、Z で割る形（透視投影）になります。遠いものが小さく写り、平行線が一点に集まるのはこの割り算の帰結です。","モデルは内部パラメータ（焦点距離・主点・画素の縦横比）と外部パラメータ（カメラの位置と姿勢）で記述されます。カメラキャリブレーションとは、この内部パラメータと後述の歪みを、既知のパターンから推定する手続きです。"],fig:null},
  {h:"レンズモデルと歪曲収差",b:["実際のレンズでは、像の位置が理想からずれます。代表的なのが放射方向の歪曲で、中心からの距離 r に対する多項式（座標に 1 + k1 r² + k2 r⁴ + … の係数が掛かる形）で表される、樽型・糸巻き型の歪みです。接線方向の歪みも加わります。","歪みは、まっすぐなものが曲がって写るという見た目の問題だけでなく、位置測定の系統誤差になります。キャリブレーションで係数を推定し、補正（歪み除去）してから測定するのが定量的な扱いの前提です。"],fig:null},
  {h:"被写界深度と撮像素子",b:["被写界深度は、ピントが合って見える奥行きの範囲です。絞り（F値）を絞るほど深くなりますが、回折によるぼけが増えるため、最適な絞りが存在します。焦点距離と撮影距離も深度に効きます。G03のPSFの議論と地続きの話です。","撮像素子は、光子を電荷に変える画素の配列です。画素の開口の形（フィルファクタ）、シャッター方式（ローリングシャッターでは動く対象が歪む）、読み出しのノイズが、画像の性質を決めます。撮像過程の理解は、画像の「データとしての癖」の理解です。"],fig:null}],
 points:["透視投影は x = f X/Z。遠近法はこの割り算の帰結","歪曲収差はキャリブレーションで推定・補正する系統誤差","被写界深度と回折はトレードオフ。素子の方式も画像の癖になる"],mistakes:["歪みは見た目だけの問題（位置測定の誤差になる）","絞れば絞るほど鮮明（回折ぼけが増える）"],src:"ocvcalib",terms:["ピンホールカメラモデル","透視投影","歪曲収差","被写界深度"],related:["G43","G03"]},
{id:"G43",cat:"cam",title:"ステレオ視と3次元復元",lead:"複数の視点から奥行きを取り戻す技術です。エピポーラ幾何という制約が、対応付けを現実的な問題にしています。",
 sections:[
  {h:"ステレオ視と視差",b:["左右に離れた2台のカメラで同じ点を見ると、像の位置にずれ（視差）が生じます。基線長 B、焦点距離 f、視差 d に対して、奥行きは Z = fB/d と求まります。視差が小さい（遠い）ほど奥行きの分解能は悪くなる、という性質がこの式から読み取れます。","難所は対応付けです。片方の画像の点が、もう片方のどこに対応するか。テクスチャのない面や繰り返し模様では対応が曖昧になり、奥行きが抜けたり誤ったりします。"],fig:null},
  {h:"エピポーラ幾何",b:["2視点の幾何では、片方の画像の点に対応する点は、もう片方の画像ではエピポーラ線と呼ばれる直線の上に必ず現れます。対応探しが2次元から1次元に減るため、この制約がステレオマッチングを現実的にしています。","この幾何は、基礎行列・基本行列という行列で表され、対応点から推定できます。画像を平行化（レクティフィケーション）してエピポーラ線を水平にそろえるのが、実装の標準的な前処理です。"],fig:null},
  {h:"SfMとアクティブステレオ",b:["Structure from Motion（SfM）は、複数枚の写真から、カメラの動きと場面の3次元構造を同時に推定する技術です。特徴点マッチング（G37）と幾何の推定を束ね、バンドル調整と呼ばれる大規模な最適化で全体を整えます。写真測量や3次元モデルの作成の基盤です。","アクティブステレオは、プロジェクタでパターンを投影して対応付けを助ける方式です。テクスチャのない面でも奥行きが取れる代わりに、投影の届く範囲と環境光が制約になります。受動・能動の選択は、対象と環境で決まります。"],fig:null}],
 points:["奥行きは Z = fB/d。遠方ほど分解能が落ちる","対応点はエピポーラ線上に限られる。探索が1次元になる","SfMは動きと構造の同時推定。アクティブ方式は対応を能動化する"],mistakes:["視差が大きいほど遠い（近いほど大きい）","対応は全画素の探索が要る（エピポーラ線上で済む）"],src:"ocvcalib",terms:["エピポーラ幾何","ステレオ視","SfM","空間校正"],related:["G42","G37"]},
{id:"G44",cat:"prac",title:"Python画像処理の実践環境",lead:"理論を手で動かすための道具立てです。Jupyter、OpenCV、scikit-imageの役割分担と、リアルタイム処理の考え方を押さえます。",
 sections:[
  {h:"Jupyterと対話的実行",b:["Jupyter Notebook は、コードとその出力（画像・グラフ）を1つの文書に混ぜて残せる対話的実行環境です。セル単位で実行し、途中の画像を確認しながら処理を組み立てられるため、探索的な画像処理と教育に広く使われます。","一方で、実行順序が文書の順序とずれる、状態がセル間に残る、といった再現性の落とし穴があります。最終的にはスクリプトとして上から通して実行できる形に整えるのが、共有と再現の前提です。"],fig:null},
  {h:"OpenCVとscikit-image",b:["OpenCVは、速度とリアルタイム性を重視したコンピュータビジョンの総合ライブラリです。画像は主に NumPy 配列（uint8、BGR順）として扱い、フィルタ、特徴点、カメラ、機械学習まで広く揃います。scikit-imageは、科学用途を意識したライブラリで、型の規約（float は 0..1 など）を明示し、測定や形態学、復元のアルゴリズムが充実しています。","両者は同じ NumPy 配列の世界に住むため併用できますが、色の順序（BGR/RGB）や型の規約の違いが、取り違えの典型的な原因です。ライブラリの「流儀」を知ることが、実践の第一歩になります。"],fig:null},
  {h:"リアルタイム処理の制約",b:["カメラ映像のリアルタイム処理では、1フレームあたりの処理時間がフレーム間隔（30 fps なら約33ミリ秒）以内に収まることが絶対条件です。間に合わなければ、フレームを落とすか、遅延が蓄積します。解像度を落とす、処理を軽い順に段階化する、といった設計はこの制約から生まれます。","また、表示や保存などの入出力も時間を消費します。処理そのものだけでなく、取得・処理・出力のパイプライン全体で予算を管理するのが、リアルタイム系の設計の実態です。"],fig:null}],
 points:["Jupyterは対話的探索に強い。再現性には通し実行への整形が要る","OpenCVはBGR・uint8中心、scikit-imageは型規約を明示する科学系","リアルタイムは1フレームの時間予算が絶対条件。パイプライン全体で管理する"],mistakes:["ライブラリ間で配列はそのまま使える（色順や型規約の違いがある）","速い処理を書けばリアルタイムになる（入出力含む全体の予算）"],src:"ocvfeat2d",terms:["OpenCV","scikit-image","Jupyter"],related:["G39","G36"]}
];
window.IJDATA2.eduTermCats = { base:"画像の基礎", hist:"濃度変換とヒストグラム", color:"色と視覚", geom:"幾何変換", filt:"空間フィルタリング", freq:"周波数領域", rest:"画像復元", seg:"二値化と領域分割", feat:"特徴抽出とマッチング", eval:"評価と圧縮", video:"動画像処理", recog:"認識と学習", cam:"撮像と3次元", prac:"実践環境" };
window.IJDATA2.eduTerms = [
{t:"標本化",en:"Sampling",aliases:["サンプリング"],cat:"base",d:"連続した像を等間隔の格子点で区切り、各点の値を代表値として取り出す変換。位置の離散化。",detail:"格子間隔が空間解像度を決める。含まれる最高周波数の2倍より高い頻度で標本化しないとエイリアシングが生じる（標本化定理）。",vs:"量子化は明るさの離散化であり、標本化は位置の離散化である点が異なる。",ex:"カメラの画素ピッチが標本化間隔にあたる。",related:["量子化","エイリアシング"],src:"dip"},
{t:"量子化",en:"Quantization",aliases:[],cat:"base",d:"連続量の明るさを有限個の段階のいずれかに割り当てる変換。明るさの離散化。",detail:"段階数はビット深度で決まる。段数が不足すると滑らかなグラデーションに偽輪郭（バンディング）が現れる。丸めの際に生じる差が量子化誤差。",vs:"標本化は位置の離散化であり、量子化は値の離散化である点が異なる。",ex:"16-bit画像を8-bit化すると量子化が粗くなる。",related:["標本化","ビット深度"],src:"skdt"},
{t:"画素",en:"Pixel",aliases:["ピクセル"],cat:"base",d:"デジタル画像の最小単位の要素。位置と画素値を持つ。",detail:"画素は面積を持つセルの代表値であり、点ではない。体積を持つ要素として扱う場合はボクセルと呼ぶ。画素値そのものがデータであり、表示色はLUTによる割り当てである。",vs:"表示上のドット（画面の発光素子）とは別の概念。",ex:"512×512画素は、標本化点が縦横512個ずつ並んだ画像。",related:["標本化","ルックアップテーブル"],src:"dip"},
{t:"ビット深度",en:"Bit Depth",aliases:["階調数","色深度"],cat:"base",d:"1画素が表せる段階数を決めるビット数。n bitで2^n段階。",detail:"8-bitは256段階、16-bitは65,536段階。定量測定では信号が何段に分布するかが精度を左右する。保存深度とセンサーの実効深度は別物。",vs:"ダイナミックレンジは検出可能な明暗の比であり、深度はその刻みの細かさ。",ex:"蛍光の定量では16-bit取得が推奨されることが多い。",related:["量子化","ダイナミックレンジ"],src:"skdt"},
{t:"ダイナミックレンジ",en:"Dynamic Range",aliases:[],cat:"base",d:"検出できる最も明るい信号と、ノイズフロアで決まる最も暗い信号の比。",detail:"センサーの飽和容量と読み出しノイズで決まる。ビット深度は刻みの上限を与えるが、実際のレンジはセンサー特性に依存する。",vs:"ビット深度は段階数の話であり、レンジは検出可能な幅の話。",ex:"暗い蛍光と明るい構造を同時に写すには広いレンジが要る。",related:["ビット深度"],src:"skdt"},
{t:"点像分布関数",en:"Point Spread Function (PSF)",aliases:["PSF"],cat:"base",d:"点光源が光学系を通して像面に広がる形。光学系のぼけを表す関数。",detail:"対物レンズの開口数と波長で幅が決まる。実画像は、対象とPSFの畳み込みとみなせる。デコンボリューションはこの逆を解く処理。",vs:"画素サイズ（標本化間隔）とは別で、こちらは光学側の広がり。",ex:"蛍光ビーズを写すとPSFの形が直接観察できる。",related:["畳み込み","デコンボリューション"],src:"dip"},
{t:"エイリアシング",en:"Aliasing",aliases:["折り返し歪み"],cat:"base",d:"標本化不足により、高周波成分が低い周波数に化けて記録される現象。",detail:"周波数領域では、スペクトルの周期複製同士の重なりとして説明できる。一度記録されると元の成分と区別できず、除去は困難。",vs:"モアレはエイリアシングが縞模様として目に見える現れの一つ。",ex:"細かい格子を縮小表示すると縞の向きや間隔が変わって見える。",related:["モアレ","標本化定理"],src:"dip"},
{t:"モアレ",en:"Moiré",aliases:["モアレ縞"],cat:"base",d:"規則的なパターン同士の干渉で現れる、実在しない縞模様。",detail:"標本の周期構造と標本化格子の周期が近いときに生じるエイリアシングの現れ。取得条件（倍率・角度）を変えると模様が変わるのが特徴。",vs:"実際の構造とは異なり、条件を変えると消えたり変わったりする。",ex:"格子状の標本で倍率を変えると縞が動いて見える。",related:["エイリアシング"],src:"dip"},
{t:"ナイキスト周波数",en:"Nyquist Frequency",aliases:[],cat:"base",d:"標本化周波数の半分の周波数。正しく再現できる周波数の上限。",detail:"これを超える周波数成分はエイリアシングで低周波に折り返す。画素ピッチ p の画像では 1/(2p) がナイキスト周波数になる。",vs:"標本化周波数そのものではなく、その半分である点に注意。",ex:"画素サイズは再現したい構造の周期の半分以下が目安。",related:["標本化定理","エイリアシング"],src:"dip"},
{t:"ヒストグラム",en:"Histogram",aliases:[],cat:"hist",d:"各画素値を持つ画素の個数（割合）を表した分布。",detail:"位置情報を持たず、明暗の分布だけを要約する。平均・分散などの統計量や、自動閾値決定の材料になる。二峰性が見えれば二値化の見通しが立つ。",vs:"累積ヒストグラムは個数の累積であり、分布そのものではない。",ex:"背景が大半の画像では、背景レベルの位置に大きな峰ができる。",related:["累積ヒストグラム","大津の方法"],src:"ocvhist"},
{t:"累積ヒストグラム",en:"Cumulative Histogram",aliases:["累積分布関数"],cat:"hist",d:"画素値を小さい順に累積した個数（割合）。分布の累積分布関数。",detail:"ヒストグラム平坦化の変換関数として使う。中央値は累積が50%に達する画素値として読める。",vs:"ヒストグラムは各値の個数、累積はそれ以下の合計。",ex:"平坦化では累積ヒストグラムを値域いっぱいに広げて変換する。",related:["ヒストグラム","ヒストグラム平坦化"],src:"ocveq"},
{t:"濃度変換",en:"Intensity Transformation",aliases:["階調変換","点演算"],cat:"hist",d:"各画素の値を、その値だけから決まる関数で置き換える処理の総称。",detail:"s = T(r) の形で表される。反転・対数変換・ガンマ補正・平坦化はすべて点演算。近傍を使うフィルタ処理とは区別される。",vs:"空間フィルタは近傍の画素も使う点が異なる。",ex:"画像の反転（ネガポジ）は最も単純な濃度変換。",related:["ガンマ補正","ヒストグラム平坦化"],src:"ocvhist"},
{t:"ガンマ補正",en:"Gamma Correction",aliases:["べき乗変換"],cat:"hist",d:"s = c・r^γ のべき乗変換による濃度変換。γで暗部・明部の伸縮を制御する。",detail:"γ < 1 で暗部が持ち上がり、γ > 1 で暗部が締まる。表示系の特性補正が本来の用途で、画素値の線形性を崩すため定量解析では扱いに注意が要る。",vs:"線形な引き伸ばし（コントラスト強調）とは変換曲線の形が異なる。",ex:"暗すぎる画像の確認にγ=0.5程度を試す。",related:["濃度変換"],src:"ocvhist"},
{t:"ヒストグラム平坦化",en:"Histogram Equalization",aliases:["ヒストグラム均等化"],cat:"hist",d:"累積ヒストグラムを変換に使い、画素値の分布をほぼ一様に広げる点演算。",detail:"画素数の多い値域ほど引き伸ばされるため、コントラストが自動的に広がる。副作用として背景ノイズの強調と定量性の喪失がある。",vs:"CLAHEは局所化と制限を加えた改良版。",ex:"X線画像の視認性改善など表示目的で使う。",related:["CLAHE","累積ヒストグラム"],src:"ocveq"},
{t:"CLAHE",en:"Contrast Limited Adaptive Histogram Equalization",aliases:["制限付き適応ヒストグラム平坦化"],cat:"hist",d:"画像を小領域に分けて平坦化し、ヒストグラムの突出を上限で抑える改良法。",detail:"局所的なコントラスト改善とノイズ増幅の抑制を両立させる。領域間の継ぎ目は補間で滑らかにする。Fijiの Enhance Local Contrast プラグインが相当する。",vs:"全体平坦化と違い、場所ごとに異なる変換が適用される。",ex:"むらのある顕微鏡画像の局所コントラスト改善に使う。",related:["ヒストグラム平坦化"],src:"ocveq"},
{t:"ルックアップテーブル",en:"Look-Up Table (LUT)",aliases:["LUT"],cat:"hist",d:"画素値を表示色に対応付ける表。画素値そのものは変えず、見え方だけを決める。",detail:"グレーの直線対応、疑似カラー、反転などはLUTの違い。LUTを変えても測定値は変わらない。適用（Apply）して初めて画素値に焼き込まれる場合がある点に注意。",vs:"濃度変換は画素値を書き換えるが、LUTは表示の割り当て。",ex:"FireやGraysなどのカラーマップ切り替えはLUTの変更。",related:["画素","濃度変換"],src:"ijana"},
{t:"畳み込み",en:"Convolution",aliases:["コンボリューション"],cat:"filt",d:"カーネルを反転して画像上を滑らせ、重なる画素の重み付き和を取る演算。",detail:"空間フィルタリングの基本形。反転しない場合は相関と呼ばれる。カーネルの合計が1なら明るさを保存し、0なら一様領域が消える。周波数領域では積に対応する（畳み込み定理）。",vs:"相関とはカーネルの反転の有無が異なり、対称カーネルでは一致する。",ex:"ぼかしもエッジ検出も、畳み込みのカーネルの違いで表せる。",related:["カーネル","フーリエ変換"],src:"ocvfilt"},
{t:"カーネル",en:"Kernel",aliases:["フィルタマスク","オペレータ"],cat:"filt",d:"畳み込みに使う重みの小行列。フィルタの性格を決める。",detail:"大きさは通常奇数×奇数で、中心が注目画素に対応する。重みのパターンが平滑化・微分・鮮鋭化などの違いを生む。分離可能なカーネルは計算を高速化できる。",vs:"構造要素は形態学演算で使う図形で、重みを持つカーネルとは役割が異なる。",ex:"3×3の平均フィルタは全要素が1/9のカーネル。",related:["畳み込み","構造要素"],src:"ocvfilt"},
{t:"ガウシアンフィルタ",en:"Gaussian Filter",aliases:["ガウスぼかし","ガウスフィルタ"],cat:"filt",d:"ガウス関数型の重みで近傍を平均する平滑化フィルタ。",detail:"標準偏差σがぼけの強さを決める。分離可能で高速に計算でき、周波数特性も滑らか。微分と組み合わせたLoGや、DoG（差分）など応用の土台になる。",vs:"平均フィルタは重みが均一で、周波数特性に波打ちが出やすい。",ex:"ノイズ低減の前処理としてσ=1〜2程度がよく使われる。",related:["メディアンフィルタ","ラプラシアン"],src:"ocvfilt"},
{t:"メディアンフィルタ",en:"Median Filter",aliases:["中央値フィルタ"],cat:"filt",d:"近傍画素の中央値を出力する非線形平滑化フィルタ。",detail:"外れ値（ごま塩ノイズ）の影響を受けにくく、エッジを比較的保ちながら平滑化できる。細い線や小さな点は消えることがある。順序統計フィルタの一種。",vs:"平均フィルタは外れ値に引っ張られるが、メディアンは順位で決まるため強い。",ex:"ごま塩ノイズの除去の第一選択。",related:["ごま塩ノイズ","ガウシアンフィルタ"],src:"ocvfilt"},
{t:"バイラテラルフィルタ",en:"Bilateral Filter",aliases:[],cat:"filt",d:"距離の近さと画素値の近さの両方で重みを付けるエッジ保存平滑化フィルタ。",detail:"エッジをまたいだ平均化が抑えられるため、輪郭を残したままむらやノイズを均せる。計算量は大きめ。値の差の重み（レンジカーネル）が肝になる。",vs:"ガウシアンフィルタは距離だけで重みを付け、エッジもぼかす。",ex:"テクスチャを均しつつ対象の輪郭を保ちたい場合に使う。",related:["ガウシアンフィルタ","エッジ"],src:"ocvfilt"},
{t:"ごま塩ノイズ",en:"Salt-and-Pepper Noise",aliases:["インパルスノイズ"],cat:"filt",d:"白と黒の点が散発的に現れるインパルス性のノイズ。",detail:"伝送エラーや読み出しの異常で生じる。平均フィルタでは点が薄く広がるだけで残るため、メディアンフィルタが有効。",vs:"ガウシアンノイズは全画素に小さな揺らぎとして乗るタイプ。",ex:"メディアンフィルタ3×3で大半が除去できる。",related:["メディアンフィルタ"],src:"ocvfilt"},
{t:"ラプラシアン",en:"Laplacian",aliases:["ラプラシアンフィルタ"],cat:"filt",d:"2次微分を近似するフィルタ。変化の変化を捉える。",detail:"エッジ位置でゼロを横切る（ゼロ交差）ため、エッジ位置の特定に使える。等方的（方向に依存しない）が、ノイズに敏感で、前段の平滑化（LoG）と組にすることが多い。カーネル合計は0。",vs:"勾配（1次微分）は変化の大きさと向き、ラプラシアンは曲率に相当する。",ex:"鮮鋭化では元画像からラプラシアンを差し引く形で使う。",related:["画像勾配","アンシャープマスキング"],src:"ocvfilt"},
{t:"Sobelフィルタ",en:"Sobel Filter",aliases:["ソーベルフィルタ"],cat:"filt",d:"微分と平滑化を組み合わせた勾配計算用カーネル。x・y方向の組で使う。",detail:"中心差分に[1 2 1]の平滑化を掛けた構造で、単純な差分よりノイズに強い。勾配の大きさと方向からエッジ候補を作る基本道具。",vs:"Prewittフィルタは平滑化の重みが均一な点が異なる。",ex:"Canny検出の勾配計算にも使われる。",related:["画像勾配","Cannyエッジ検出"],src:"ocvcanny"},
{t:"アンシャープマスキング",en:"Unsharp Masking",aliases:["アンシャープマスク"],cat:"filt",d:"元画像に「元画像 − 平滑化画像」を加えて輪郭を強調する鮮鋭化手法。",detail:"差分は高周波成分に相当する。加える強さと平滑化の半径がパラメータ。強すぎると輪郭の両側にハロー（光と影の縁）が出る。新しい情報を作る処理ではない。",vs:"ラプラシアンによる鮮鋭化とは差分の作り方が異なるが、目的は同じ高周波強調。",ex:"印刷・表示前の見栄え調整によく使う。",related:["ラプラシアン","ガウシアンフィルタ"],src:"ocvfilt"},
{t:"フーリエ変換",en:"Fourier Transform",aliases:[],cat:"freq",d:"信号や画像を、正弦波の重ね合わせ（周波数成分）に分解する変換。",detail:"各成分の振幅と位相が得られる。画像の構造情報は主に位相側が担う。逆変換で元の画像に戻せる。空間での畳み込みは周波数での積に対応する。",vs:"DCTは実数の余弦成分だけを使う関連変換で、JPEGに使われる。",ex:"周期ノイズの解析はフーリエ変換が入口になる。",related:["離散フーリエ変換","周波数スペクトル"],src:"ocvfft"},
{t:"離散フーリエ変換",en:"Discrete Fourier Transform (DFT)",aliases:["DFT"],cat:"freq",d:"離散データに対するフーリエ変換。デジタル画像に適用される形。",detail:"結果は複素数の周波数スペクトル。計算量は画素数の2乗に比例するため、実務ではFFTアルゴリズムで計算する。",vs:"FFTはDFTを高速に計算するアルゴリズムであり、変換そのものは同じ。",ex:"512×512画像のDFTもFFTなら一瞬で終わる。",related:["高速フーリエ変換","フーリエ変換"],src:"ocvfft"},
{t:"高速フーリエ変換",en:"Fast Fourier Transform (FFT)",aliases:["FFT"],cat:"freq",d:"DFTを高速に計算するアルゴリズムの総称。",detail:"分割統治により計算量を N log N のオーダまで下げる。画像サイズが2の累乗だと効率が良い実装が多い。ImageJのFFT表示もこれを使う。",vs:"DFTは変換の定義、FFTはその計算法。結果は同一。",ex:"大きなカーネルの畳み込みをFFT経由で高速化できる。",related:["離散フーリエ変換"],src:"ijfft"},
{t:"周波数スペクトル",en:"Frequency Spectrum",aliases:["パワースペクトル"],cat:"freq",d:"フーリエ変換で得た周波数成分の分布。中心が低周波、外側が高周波。",detail:"振幅スペクトルは成分の強さ、二乗したパワースペクトルはエネルギー分布を表す。周期構造は点や線として現れ、向きは元の縞と直交する。表示は対数圧縮されることが多い。",vs:"位相スペクトルは波の位置の情報で、構造は主にこちらが担う。",ex:"格子画像のFFTでは、格子の周期に対応する点が並ぶ。",related:["フーリエ変換"],src:"ijfft"},
{t:"ローパスフィルタ",en:"Low-pass Filter",aliases:["LPF"],cat:"freq",d:"低周波成分を通し、高周波を抑えるフィルタ。平滑化に対応する。",detail:"周波数領域の設計で、空間領域のぼかしと等価。遮断が急峻だとリンギングが出るため、ガウシアン型の滑らかな特性がよく使われる。",vs:"ハイパスフィルタは逆に低周波を抑えて高周波を通す。",ex:"ノイズ低減や、標本化前のエイリアシング防止に使う。",related:["ハイパスフィルタ","ガウシアンフィルタ"],src:"ocvfft"},
{t:"ハイパスフィルタ",en:"High-pass Filter",aliases:["HPF"],cat:"freq",d:"高周波成分を通し、低周波を抑えるフィルタ。エッジ強調に対応する。",detail:"緩やかな明暗変化（背景のむら）を取り除き、輪郭や細部を残す。元画像からローパス結果を引く形でも実現できる。",vs:"ローパスフィルタとは通す帯域が逆。",ex:"背景むらの除去や鮮鋭化の基礎として使う。",related:["ローパスフィルタ","アンシャープマスキング"],src:"ocvfft"},
{t:"標本化定理",en:"Sampling Theorem",aliases:["ナイキストの定理","サンプリング定理"],cat:"freq",d:"信号の最高周波数の2倍より高い頻度で標本化すれば、元の信号を復元できるという定理。",detail:"周波数領域では、標本化によるスペクトルの周期複製が重ならない条件として説明できる。画像では画素サイズの設計指針になる。",vs:"ナイキスト周波数は標本化周波数の半分という量の定義。",ex:"分解能200nmの構造には100nm以下の画素サイズが要る。",related:["ナイキスト周波数","エイリアシング"],src:"dip"},
{t:"閾値処理",en:"Thresholding",aliases:["しきい値処理","二値化"],cat:"seg",d:"画素値と閾値の比較で画素を2クラスに分ける処理。二値化の基本。",detail:"出力の二値画像が面積・個数・形状測定の土台になる。閾値の決め方（手動・自動・局所）が結果を支配する。反転の向き（対象が明るいか暗いか）の指定も必要。",vs:"適応的閾値処理は場所ごとに閾値を変える拡張。",ex:"核の蛍光画像を閾値で分けて個数を数える。",related:["大津の方法","適応的閾値処理"],src:"ocvth"},
{t:"大津の方法",en:"Otsu's Method",aliases:["大津の二値化","クラス間分散最大化"],cat:"seg",d:"クラス間分散が最大になる閾値を自動で選ぶ二値化手法。",detail:"2クラスの平均の離れとクラス内のまとまりを同時に評価する基準。全候補を評価するため決定的で再現性がある。前提は明暗の二峰性で、弱い場合は妥当性が下がる。判別分析に基づく大津展之の手法（1979）。",vs:"手動閾値は再現性の説明が難しく、大津は自動だが前提依存。",ex:"ImageJの自動閾値の一覧にも Otsu が含まれる。",related:["閾値処理","ヒストグラム"],src:"ocvth"},
{t:"適応的閾値処理",en:"Adaptive Thresholding",aliases:["局所閾値処理","Auto Local Threshold"],cat:"seg",d:"近傍の統計から場所ごとに閾値を決める二値化。",detail:"照明むらで背景レベルが変わる画像に対応できる。窓の大きさと、平均から差し引くオフセットがパラメータになる。ImageJの Auto Local Threshold に手法群がある。",vs:"大域的閾値処理は画像全体で1つの閾値を使う。",ex:"シェーディングのある画像の文字・粒子の抽出に使う。",related:["閾値処理"],src:"ocvth"},
{t:"エッジ",en:"Edge",aliases:[],cat:"seg",d:"画素値が急激に変化する場所。対象の境界や構造の境目に対応する。",detail:"勾配の大きさで強さ、方向で向きが表される。エッジは線の情報であり、内部の均一性を使う領域ベースの手法とは相補的。",vs:"ノイズによる単発の急変も勾配は拾うため、検出には追加の工程が要る。",ex:"細胞の輪郭はエッジとして現れる。",related:["画像勾配","Cannyエッジ検出"],src:"ocvcanny"},
{t:"画像勾配",en:"Image Gradient",aliases:["グラディエント"],cat:"seg",d:"画素値の空間的な変化率。x・y方向の微分の組で表される。",detail:"大きさは変化の強さ、方向は最も変化する向きを示す。Sobelなどで近似計算する。エッジ検出やテクスチャ解析の基礎量。",vs:"ラプラシアンは2次微分で、勾配は1次微分。",ex:"勾配の大きさが大きい画素がエッジ候補になる。",related:["Sobelフィルタ","エッジ"],src:"ocvcanny"},
{t:"Cannyエッジ検出",en:"Canny Edge Detection",aliases:["キャニー法"],cat:"seg",d:"平滑化→勾配→非極大抑制→ヒステリシス閾値からなる多段階のエッジ検出法。",detail:"細く、途切れにくく、誤検出の少ないエッジを目指した設計（Canny, 1986）。2つの閾値によるヒステリシスで、強いエッジに接続する弱いエッジを採用する。",vs:"単純な勾配＋閾値では線の太さとノイズの処理ができない。",ex:"輪郭抽出の標準的な選択肢として広く実装されている。",related:["エッジ","Sobelフィルタ"],src:"ocvcanny"},
{t:"膨張",en:"Dilation",aliases:["ダイレーション"],cat:"seg",d:"二値画像の対象を構造要素の分だけ太らせる形態学演算。",detail:"集合のミンコフスキー和で定義される。小さな穴が埋まり、近い対象同士がつながる。グレースケールでは最大値フィルタに対応する。",vs:"収縮は対象を細らせる逆向きの演算。",ex:"切れた輪郭をつなぐ目的で使う。",related:["収縮","構造要素"],src:"ocvmorph"},
{t:"収縮",en:"Erosion",aliases:["エロージョン"],cat:"seg",d:"二値画像の対象を構造要素の分だけ細らせる形態学演算。",detail:"小さな突起や細い連結が先に消える。くっついた対象の分離や、小ノイズの除去に使う。グレースケールでは最小値フィルタに対応する。",vs:"膨張は対象を太らせる演算。",ex:"接触した粒子を分ける前処理に使う。",related:["膨張","オープニング"],src:"ocvmorph"},
{t:"オープニング",en:"Opening",aliases:[],cat:"seg",d:"収縮の後に膨張を行う形態学演算。突起や細い連結を除き、形を滑らかにする。",detail:"構造要素より小さな対象や突起が消え、大きな構造はほぼ形を保つ。グレースケールでは背景推定にも使う。繰り返しても結果が変わらない冪等性がある。",vs:"クロージングは順序が逆で、穴や切れ目を埋める。",ex:"小さなゴミを取り除いてから粒子解析する。",related:["クロージング","収縮"],src:"ocvmorph"},
{t:"クロージング",en:"Closing",aliases:[],cat:"seg",d:"膨張の後に収縮を行う形態学演算。小さな穴や切れ目を埋める。",detail:"対象内部の小さな欠けや、輪郭の隙間を埋めて形を整える。大きな構造の外形はほぼ保たれる。冪等性がある。",vs:"オープニングは突起を除く処理で、クロージングは欠けを埋める処理。",ex:"輪郭の小さな欠けを埋めて面積測定を安定させる。",related:["オープニング","膨張"],src:"ocvmorph"},
{t:"構造要素",en:"Structuring Element",aliases:["カーネル（形態学）"],cat:"seg",d:"形態学演算で使う小さな図形。形を変える「型」にあたる。",detail:"大きさと形（十字・正方形・円盤など）が、消える構造の規模と方向性を決める。畳み込みのカーネルと違い、重みではなく図形そのものが定義になる。",vs:"カーネルは重み付き和の重み、構造要素は集合演算の型。",ex:"大きな構造要素ほど大きな突起まで消える。",related:["膨張","オープニング"],src:"ocvmorph"},
{t:"連結成分",en:"Connected Component",aliases:["連結領域"],cat:"seg",d:"画素同士のつながりでひとまとまりとみなされる領域。",detail:"つながりの定義（4連結か8連結か）で数え分けが変わる。ラベリングで各成分に番号を振り、成分ごとに面積や重心を測るのが粒子解析の仕組み。",vs:"ROIは人が指定する領域、連結成分は二値画像から自動で決まる領域。",ex:"Analyze Particles は連結成分ごとに測定する。",related:["重心","円形度"],src:"ijana"},
{t:"重心",en:"Centroid",aliases:["図心"],cat:"eval",d:"領域の画素位置の平均。質量中心にあたる座標。",detail:"画像モーメントの1次を0次で割って得られる。画素値で重み付けした場合は加重重心になり、強度分布の中心を表す。追跡や位置測定の基本量。",vs:"外接矩形の中心とは異なり、形の偏りを反映する。",ex:"粒子の重心の動きから移動速度を測る。",related:["画像モーメント","連結成分"],src:"ijana"},
{t:"画像モーメント",en:"Image Moments",aliases:["モーメント特徴"],cat:"feat",d:"画素位置のべき乗で重み付けした総和 m_pq = ΣΣ x^p y^q f(x, y) の族。",detail:"0次は面積、1次/0次は重心、2次は広がりと向きを与える。正規化を重ねると、位置・大きさ・回転に不変なHuモーメントが得られる。",vs:"ヒストグラムの統計モーメントとは対象が異なり、こちらは空間位置のモーメント。",ex:"形の分類に不変モーメントを使う。",related:["重心","円形度"],src:"dip"},
{t:"円形度",en:"Circularity",aliases:["真円度"],cat:"feat",d:"4π×面積/周囲長² で定義される形状指標。真円で1、細長いほど0に近づく。",detail:"ImageJの測定項目 Circularity がこれ。周囲長の測り方（画素の階段の扱い）と解像度に影響されるため、条件を揃えた比較が前提。",vs:"長軸/短軸比（アスペクト比）とは別の観点の指標。",ex:"粒子の選別条件として 0.8以上などを指定する。",related:["連結成分","画像モーメント"],src:"ijana"},
{t:"テクスチャ",en:"Texture",aliases:["質感特徴"],cat:"feat",d:"画素値の空間的な繰り返しや粗さのパターン。表面の質感を表す特徴の総称。",detail:"単一画素の値ではなく、近傍との関係（同時生起行列GLCMなど）で定量化する。コントラスト・均一性・エントロピーなどの指標が使われる。",vs:"形状特徴は輪郭の幾何、テクスチャは内部の模様の特徴。",ex:"組織の種類をテクスチャ指標で分類する。",related:["エントロピー"],src:"dip"},
{t:"エントロピー",en:"Entropy",aliases:["情報量"],cat:"eval",d:"分布の不確かさ・情報量を表す量 H = −Σ p log2 p。",detail:"画素値分布に使うと、階調の使われ方の広がりを示す。圧縮では、エントロピーが理論的な圧縮率の下限を与える。テクスチャ指標としても使われる。",vs:"分散は値のばらつき、エントロピーは分布の形そのものの情報量。",ex:"平坦な画像はエントロピーが低く、ノイズ画像は高い。",related:["テクスチャ"],src:"dip"},
{t:"PSNR",en:"Peak Signal-to-Noise Ratio",aliases:["ピーク信号対雑音比"],cat:"eval",d:"原画像との平均二乗誤差から求める画質指標。単位はdB。",detail:"値が大きいほど誤差が小さい。計算は単純だが、人間の見た目や解析タスクへの適否とはずれることがある。最大画素値をピークとして正規化する。",vs:"SSIMは構造の類似度を見る指標で、誤差ベースのPSNRとは観点が異なる。",ex:"圧縮率を変えたときの劣化の目安に使う。",related:["SSIM"],src:"dip"},
{t:"SSIM",en:"Structural Similarity Index",aliases:["構造的類似性"],cat:"eval",d:"輝度・コントラスト・構造の類似度を組み合わせた画質指標。1で完全一致。",detail:"人間の視覚は構造の違いに敏感だという前提に基づく。PSNRより見た目との対応が良いとされるが、解析タスクへの適否を直接測るものではない。",vs:"PSNRは画素誤差の平均、SSIMは局所構造の類似度。",ex:"圧縮や復元の評価でPSNRと併用される。",related:["PSNR"],src:"dip"},
{t:"デコンボリューション",en:"Deconvolution",aliases:["逆畳み込み"],cat:"rest",d:"PSFによるぼけの畳み込みを逆向きに解き、像を鮮明化する処理。",detail:"原理的には周波数領域の割り算だが、ノイズの増幅が激しいため、正則化や反復法（Richardson-Lucy法など）で安定化させる。PSFの実測または推定が必要。",vs:"鮮鋭化フィルタは見かけの強調、デコンボリューションは劣化過程の逆算。",ex:"蛍光顕微鏡の3次元像のぼけ除去に使う。",related:["点像分布関数","フーリエ変換"],src:"dip"},
{t:"空間校正",en:"Spatial Calibration",aliases:["スケール設定","キャリブレーション"],cat:"eval",d:"1画素が実世界で何μmかという対応付け。長さ・面積測定の前提。",detail:"既知の長さを写して画素数との比を取る。誤差は面積で2乗、体積で3乗に効く。光学構成（対物・カメラ）ごとに校正が必要で、メタデータと対応付けて管理する。",vs:"強度の校正は画素値と物理量の対応付けで、こちらは長さの対応付け。",ex:"対物ミクロメータを写して μm/px を設定する。",related:["重心"],src:"ijana"},
{t:"線形シフト不変系",en:"Linear Shift-Invariant System (LSI)",aliases:["LSI系"],cat:"filt",d:"線形性とシフト不変性を満たす系。出力は入力とインパルス応答の畳み込みで決まる。",detail:"平均・ガウシアン・微分フィルタが該当する。メディアンや形態学は非線形で、この理論の対象外。",vs:"非線形系は重ね合わせが成り立たず、カーネルだけでは記述できない。",ex:"LSIなら周波数応答でフィルタを設計できる。",related:["インパルス応答","周波数応答"],src:"dip"},
{t:"インパルス応答",en:"Impulse Response",aliases:[],cat:"filt",d:"LSI系に点（インパルス）を入力したときの出力。カーネルの理論的な正体。",detail:"任意の入力への出力は、インパルス応答との畳み込みで得られる。ぼけの場合はPSFそのもの。",vs:"周波数応答はこれのフーリエ変換。",ex:"PSFを実測するとは、インパルス応答を測ること。",related:["線形シフト不変系","点像分布関数"],src:"dip"},
{t:"周波数応答",en:"Frequency Response",aliases:[],cat:"filt",d:"インパルス応答のフーリエ変換。周波数ごとの倍率（振幅と位相）を表す。",detail:"出力スペクトルは入力スペクトルと周波数応答の積になる。フィルタ設計の主対象。",vs:"インパルス応答は空間領域の記述、周波数応答は周波数領域の記述。",ex:"|H| が0.5になる周波数が遮断の目安。",related:["インパルス応答","フーリエ変換"],src:"dip"},
{t:"スケールスペース",en:"Scale Space",aliases:[],cat:"filt",d:"σを連続的に変えたガウシアン平滑化画像の族。",detail:"拡散方程式と等価で、スケールを上げても新しい構造は生まれない（因果性）。SIFTの土台。",vs:"画像ピラミッドは離散的な多重解像度表現で、理論的な枠組みはこちら。",ex:"スケールをまたいで特徴点を追跡する。",related:["ガウシアンフィルタ","SIFT"],src:"dip"},
{t:"LoG",en:"Laplacian of Gaussian",aliases:["ラプラシアン・オブ・ガウシアン"],cat:"filt",d:"ガウシアン平滑化の後にラプラシアンを適用したもの。ゼロ交差がエッジを与える。",detail:"MarrとHildrethのエッジ検出法。斑点（ブロブ）検出にも使われる。",vs:"DoGはLoGの近似で、計算が軽い。",ex:"ゼロ交差を数えて輪郭を抽出する。",related:["DoG","ラプラシアン"],src:"ocvfilt"},
{t:"DoG",en:"Difference of Gaussian",aliases:["差分ガウシアン"],cat:"filt",d:"異なるσのガウシアン平滑化同士の差。バンドパス特性を持つ。",detail:"LoGの近似として使われ、網膜の受容野のモデルとしても知られる。",vs:"LoGは微分演算、DoGは引き算による近似。",ex:"SIFT内部の極値検出に使われる。",related:["LoG","スケールスペース"],src:"ocvfilt"},
{t:"ゼロ埋め",en:"Zero Padding",aliases:["ゼロパディング"],cat:"freq",d:"データの周囲にゼロを足してサイズを大きくする操作。",detail:"FFTでは周波数サンプリングが細かくなる（補間）が、分解能は上がらない。畳み込みの境界処理としても使う。",vs:"窓関数は端をなだらかに落とす操作で、目的が異なる。",ex:"FFTサイズを2の累乗に合わせるために使う。",related:["高速フーリエ変換"],src:"ocvfft"},
{t:"ギブス現象",en:"Gibbs Phenomenon",aliases:[],cat:"freq",d:"不連続な信号のフーリエ近似で、不連続点のそばに約9%のオーバーシュートが残る現象。",detail:"項数を増やしても大きさは消えず、幅だけが狭くなる。理想フィルタのリンギングの原因。",vs:"リンギングは画像上の現れ、ギブス現象はその数学的な正体。",ex:"急峻な遮断をやめるとリンギングが弱まる。",related:["理想フィルタ","バターワースフィルタ"],src:"dip"},
{t:"バターワースフィルタ",en:"Butterworth Filter",aliases:[],cat:"freq",d:"H = 1/(1 + (D/D0)^{2n}) で定義される、通過域が平坦な周波数フィルタ。",detail:"次数 n で急峻さを調整する。n が大きいほど理想フィルタに近づき、リンギングも増える。",vs:"ガウシアン型は式が exp 型で、振動のない応答を持つ。",ex:"次数2のローパスが穏当な既定として使われる。",related:["ギブス現象","ローパスフィルタ"],src:"dip"},
{t:"理想フィルタ",en:"Ideal Filter",aliases:[],cat:"freq",d:"遮断周波数の内側を1、外側を0とする矩形特性の周波数フィルタ。",detail:"空間応答は sinc 関数で無限に振動し、強いリンギングを生む。理論上の基準として扱う。",vs:"実務のフィルタは滑らかな特性でリンギングを避ける。",ex:"教科書でリンギングの説明に使われる。",related:["ギブス現象","バターワースフィルタ"],src:"dip"},
{t:"劣化モデル",en:"Degradation Model",aliases:[],cat:"rest",d:"観測画像を g = h ∗ f + n と表すモデル。h は劣化（ぼけ等）、n はノイズ。",detail:"復元問題の出発点。h がLSIである前提で周波数領域の式 G = HF + N が得られる。",vs:"生成モデル一般とは異なり、画像復元に特化した線形モデル。",ex:"PSFとノイズ特性を決めることがモデル化。",related:["逆フィルタ","ウィーナフィルタ"],src:"skrest"},
{t:"逆フィルタ",en:"Inverse Filter",aliases:[],cat:"rest",d:"周波数領域で G/H と割り算する復元法。",detail:"H の小さい・ゼロの周波数でノイズが爆発的に増幅されるため、そのままでは実用にならない。",vs:"ウィーナフィルタはノイズを織り込んで倍率を抑える改良。",ex:"閾値で割り算を打ち切る制限付き版が使われる。",related:["劣化モデル","ウィーナフィルタ"],src:"skrest"},
{t:"ウィーナフィルタ",en:"Wiener Filter",aliases:[],cat:"rest",d:"平均二乗誤差を最小にする線形復元フィルタ。周波数ごとにSNRで倍率が決まる。",detail:"式は F̂ = [H*/(|H|² + S_n/S_f)] G。ノイズがなければ逆フィルタに一致する。",vs:"逆フィルタはノイズを考えない割り算、こちらは最適な重み付け。",ex:"定数Kによる近似形が実務でよく使われる。",related:["逆フィルタ","正則化"],src:"skrest"},
{t:"Richardson-Lucy法",en:"Richardson–Lucy Deconvolution",aliases:["RL法"],cat:"rest",d:"ポアソンノイズを前提とした反復的な復元法（デコンボリューション）。",detail:"最尤推定を反復で解く。非負性が保たれ、蛍光顕微鏡で標準的に使われる。反復回数がパラメータ。",vs:"ウィーナフィルタは線形で1回の計算、こちらは非線形な反復法。",ex:"反復を増やすと鮮明になるがノイズも増える。",related:["デコンボリューション","ウィーナフィルタ"],src:"skrest"},
{t:"正則化",en:"Regularization",aliases:[],cat:"rest",d:"不良設定問題に事前の想定（滑らかさ等）を加えて解を安定させる枠組み。",detail:"データへの適合と想定への近さのバランスで解を選ぶ。復元・分割・学習に共通する考え方。",vs:"単なる平滑化フィルタとは異なり、最適化問題の定式化の一部。",ex:"チホノフ正則化は二乗ノルムを罰金項に使う。",related:["ウィーナフィルタ","エネルギー最小化"],src:"dip"},
{t:"超解像",en:"Super-Resolution",aliases:[],cat:"rest",d:"複数の低解像度観測や学習により、標本化を超える解像度の画像を得る技術。",detail:"古典法の情報源はフレーム間のサブピクセルずれ。学習ベースは生成を含むため、測定用途では注意が要る。",vs:"単なる拡大（補間）は情報を増やさない。",ex:"衛星画像の時系列からの再構成に使われる。",related:["HDR","標本化"],src:"dip"},
{t:"HDR",en:"High Dynamic Range",aliases:["ハイダイナミックレンジ"],cat:"rest",d:"複数露光の合成などで、通常のレンジを超える明暗を保持する表現・技術。",detail:"表示にはトーンマッピングが要る。応答関数の推定が合成の前提。",vs:"ビット深度を上げるだけではセンサーのレンジは広がらない。",ex:"逆光場面で空と影を両立させる。",related:["ダイナミックレンジ","超解像"],src:"dip"},
{t:"分光分布",en:"Spectral Distribution",aliases:["分光パワー分布"],cat:"color",d:"光の波長ごとの強さの分布。色の物理的な実体。",detail:"色覚はこの分布を3種の錐体の応答に圧縮したもの。分布が違っても同じ色に見えることがある。",vs:"RGB値は分光分布そのものではなく、応答の要約。",ex:"光源が変わると同じ物体でも分布が変わる。",related:["XYZ表色系","等色関数"],src:"dip"},
{t:"XYZ表色系",en:"CIE XYZ Color Space",aliases:[],cat:"color",d:"等色関数に基づく国際標準の表色系。Yが輝度に対応する。",detail:"すべての色を非負で表せるため、色空間変換の仲介（共通言語）として使われる。",vs:"RGB表色系はデバイス依存、XYZは標準として定義される。",ex:"プロファイル変換の中継点になる。",related:["分光分布","等色関数"],src:"dip"},
{t:"等色関数",en:"Color Matching Functions",aliases:["カラーマッチング"],cat:"color",d:"等色実験から定められた、波長ごとの3刺激値への変換係数。",detail:"分光分布に等色関数を掛けて積分するとXYZ値が得られる。標準観測者の定義が前提。",vs:"カメラの分光感度は等色関数と一致せず、色のずれの一因になる。",ex:"測色値の計算に使われる。",related:["XYZ表色系","分光分布"],src:"dip"},
{t:"YUV",en:"YUV / YCbCr",aliases:["YCbCr"],cat:"color",d:"輝度Yと色差Cb・Crに分ける色表現。",detail:"視覚は色の変化に鈍いため、色差を間引いてデータ量を減らせる。動画圧縮の基礎。",vs:"RGBは原色の強さ、YUVは明るさと色差への分解。",ex:"4:2:0のクロマサブサンプリングで使われる。",related:["色空間","XYZ表色系"],src:"skcolor"},
{t:"画像間演算",en:"Image Arithmetic",aliases:[],cat:"color",d:"2枚以上の画像の対応画素同士の四則・論理演算。",detail:"差分は変化検出、比はむら補正と比率測定、平均はノイズ低減に使う。位置合わせと型の扱いが前提。",vs:"点演算は1枚の画像内での変換。",ex:"背景差分は画像間演算の一種。",related:["背景差分","チャンネル"],src:"skcolor"},
{t:"チャンネル",en:"Channel",aliases:[],cat:"color",d:"カラー画像を構成するグレースケール画像の1枚。RGBなら3チャンネル。",detail:"処理の多くはチャンネル単位で適用される。蛍光の多重染色では標識ごとに対応する。",vs:"レイヤーは編集上の重なり、チャンネルは色の成分。",ex:"チャンネル分離して個別に測る。",related:["色空間","画像間演算"],src:"skcolor"},
{t:"色空間",en:"Color Space",aliases:[],cat:"color",d:"色を数値の組で表す体系（RGB、XYZ、YUVなど）。",detail:"原色・白色点・ガンマなどの定義を含み、指定なしのRGB値は色を一意に定めない。",vs:"表色系は色の表し方の標準、色空間はその具体的な定義の組。",ex:"作業色空間を固定してから解析する。",related:["XYZ表色系","YUV"],src:"skcolor"},
{t:"視細胞",en:"Photoreceptor Cells",aliases:[],cat:"color",d:"網膜の光受容細胞。色を担う錐体（3種）と暗所の桿体がある。",detail:"分布は中心窩に錐体が密集するなど不均一で、視覚の特性の源になっている。",vs:"カメラの画素は均一に並ぶが、視細胞はそうではない。",ex:"周辺視で色が乏しいのは分布のため。",related:["マッハバンド","コントラスト感度"],src:"dip"},
{t:"マッハバンド",en:"Mach Bands",aliases:[],cat:"color",d:"明暗の境界に、実際にはない明るい帯と暗い帯が見える知覚現象。",detail:"網膜の側抑制によるエッジ強調の現れ。表示の印象とデータの区別に注意が要る。",vs:"リンギングはデータ側の波打ち、こちらは知覚側の効果。",ex:"階段状のグラデーションで観察できる。",related:["視細胞","コントラスト感度"],src:"dip"},
{t:"コントラスト感度",en:"Contrast Sensitivity",aliases:[],cat:"color",d:"空間周波数ごとの、コントラストを知覚できる感度。中間周波数で最も高い。",detail:"対数応答（ウェーバー・フェヒナーの法則）と並ぶ視覚の基本特性。画質評価や圧縮の前提になる。",vs:"視力は解像限界、こちらは周波数ごとの感度の分布。",ex:"JPEGが捨てる成分の選定根拠になる。",related:["視細胞","マッハバンド"],src:"dip"},
{t:"幾何変換",en:"Geometric Transformation",aliases:[],cat:"geom",d:"画素の位置を写像で変える処理。並進・回転・拡大縮小など。",detail:"実装は逆写像＋補間が原則。値を変える濃度変換とは対の概念。",vs:"点演算は値を、幾何変換は位置を変える。",ex:"位置合わせは幾何変換の推定問題。",related:["双線形補間","アフィン変換"],src:"ocvgeo"},
{t:"双線形補間",en:"Bilinear Interpolation",aliases:["バイリニア補間"],cat:"geom",d:"周囲4点の距離に応じた重み付き平均で間の値を求める補間。",detail:"滑らかだがややぼける。ラベル画像には使えない（存在しない値が生まれる）。",vs:"最近傍は元の値の集合を保つが階段状になる。",ex:"回転や拡大の既定としてよく使われる。",related:["最近傍補間","幾何変換"],src:"ocvgeo"},
{t:"最近傍補間",en:"Nearest Neighbor Interpolation",aliases:["ニアレストネイバー"],cat:"geom",d:"最も近い格子点の値をそのまま使う補間。",detail:"値の集合が変わらないため、ラベル画像や二値画像に必須。輪郭は階段状になる。",vs:"双線形は滑らかだが新しい値を作る。",ex:"マスクの拡大縮小に使う。",related:["双線形補間","幾何変換"],src:"ocvgeo"},
{t:"アフィン変換",en:"Affine Transformation",aliases:[],cat:"geom",d:"平行性を保つ幾何変換。回転・並進・拡大縮小・せん断を含む。",detail:"同次座標の3×3行列で表され、3組の対応点で決まる。",vs:"射影変換は平行性を保たず、台形の写りまで扱える。",ex:"画像の傾き補正に使う。",related:["射影変換","同次座標"],src:"ocvgeo"},
{t:"射影変換",en:"Projective Transformation / Homography",aliases:["ホモグラフィ"],cat:"geom",d:"平面から平面への、直線を直線に写す最も一般の変換。",detail:"4組の対応点で決まる。台形補正やパノラマ合成の土台。",vs:"アフィン変換は射影変換の特殊な場合（平行性が保たれる）。",ex:"斜めから撮った文書を正面化する。",related:["アフィン変換","同次座標"],src:"ocvgeo"},
{t:"同次座標",en:"Homogeneous Coordinates",aliases:[],cat:"geom",d:"2次元の点を3次元ベクトルで表す方法。並進を行列の積に含められる。",detail:"(x, y) を (x, y, 1) とし、定数倍は同じ点を表す。射影変換の記述に必須。",vs:"通常の座標では並進は行列の積で表せない。",ex:"変換の合成を行列の積で計算する。",related:["アフィン変換","射影変換"],src:"ocvgeo"},
{t:"ラベリング",en:"Labeling / Connected Components",aliases:["連結成分ラベリング"],cat:"seg",d:"連結成分ごとに異なる番号を振る処理。対象の個数と個別測定の前提。",detail:"連結の定義（4連結/8連結）で対象の数え方が変わる。背景側は逆の定義を使うのが整合的。",vs:"閾値処理は対象か否かの判定、ラベリングは対象の同定。",ex:"粒子解析はラベリングの上に成り立つ。",related:["連結成分","細線化"],src:"ijana"},
{t:"細線化",en:"Thinning / Skeletonization",aliases:["スケルトン化","スケルトン"],cat:"seg",d:"領域をトポロジーを保ちながら1画素幅の線に痩せさせる処理。",detail:"得られるスケルトンは中心軸に相当し、分岐・端点の解析に使う。輪郭ノイズに敏感。",vs:"収縮は形を小さくするが、細線化は幅だけを落として構造を残す。",ex:"血管の分岐構造の定量化に使う。",related:["ラベリング","連結成分"],src:"ocvmorph"},
{t:"クラスタリング",en:"Clustering",aliases:[],cat:"seg",d:"ラベルなしデータ似た者同士のグループに分ける教師なし手法の総称。",detail:"特徴と距離の定義が結果を決める。画像分割は画素を特徴空間でクラスタリングする問題と見なせる。",vs:"分類（識別）はラベル付きデータから学ぶ教師ありの枠組み。",ex:"色のクラスタリングで領域を分ける。",related:["k-means法","領域分割"],src:"dip"},
{t:"k-means法",en:"k-means Clustering",aliases:[],cat:"seg",d:"クラスタ中心との距離二乗和を最小化する代表的なクラスタリング。",detail:"クラスタ数 k の事前指定と初期値への依存（局所解）が前提の注意点。",vs:"GMMは所属を確率で与える拡張、mean shiftは峰を探す方法。",ex:"画素値のk-meansは多値版の閾値処理にあたる。",related:["クラスタリング","領域分割"],src:"dip"},
{t:"領域分割",en:"Segmentation",aliases:["セグメンテーション"],cat:"seg",d:"画像を意味のある領域に分ける処理の総称。",detail:"閾値・クラスタリング・エッジ・最適化など原理は多様。評価には正解注釈との一致度を使う。",vs:"二値化は2クラスへの分割、領域分割は多クラスや意味単位も含む。",ex:"測定の前段として対象を切り出す。",related:["クラスタリング","グラフカット"],src:"dip"},
{t:"動的輪郭モデル",en:"Active Contour Model / Snakes",aliases:["スネーク"],cat:"seg",d:"エネルギーを最小化する形へ輪郭曲線を変形させる分割法。",detail:"滑らかさの内部エネルギーとエッジへの引力の外部エネルギーの和を最小化する。初期位置に依存する。",vs:"グラフカットは大域最適化、こちらは局所的な変形。",ex:"臓器の輪郭抽出で使われてきた。",related:["グラフカット","エネルギー最小化"],src:"dip"},
{t:"グラフカット",en:"Graph Cuts",aliases:[],cat:"seg",d:"画素のラベル付けをグラフの最小カット問題として大域的に解く枠組み。",detail:"データ項と平滑化項の和を最小化する。2値ラベルでは大域最適解が保証される。",vs:"スネークは局所最適化で初期値依存、こちらは大域最適化。",ex:"前景・背景の分離に使う。",related:["動的輪郭モデル","エネルギー最小化"],src:"dip"},
{t:"エネルギー最小化",en:"Energy Minimization",aliases:[],cat:"seg",d:"目的関数（エネルギー）を定義し、その最小解として処理結果を得る定式化。",detail:"データへの適合と事前の想定（平滑さ等）の和でエネルギーを作る。正則化と地続きの考え方。",vs:"手順を直接設計する古典的処理と対比される、定式化の流儀。",ex:"分割・復元・対応付けに共通して現れる。",related:["グラフカット","正則化"],src:"dip"},
{t:"同時生起行列",en:"Gray-Level Co-occurrence Matrix (GLCM)",aliases:["GLCM"],cat:"feat",d:"指定した距離・方向の画素ペアについて、値の組み合わせの頻度を数えた行列。",detail:"テクスチャの統計的表現。コントラスト・均一性などのHaralick特徴の計算源。",vs:"ヒストグラムは単独画素の分布、GLCMはペアの関係の分布。",ex:"組織の種類をGLCM特徴で分類する。",related:["テクスチャ","LBP"],src:"skfeat"},
{t:"LBP",en:"Local Binary Pattern",aliases:["局所バイナリパターン"],cat:"feat",d:"中心画素と近傍画素の大小関係を符号化したテクスチャ記述。",detail:"照明の単調変化に強い。計算が軽く、顔認識などで使われた。",vs:"GLCMは頻度の統計、LBPは局所パターンの符号化。",ex:"質感の分類に使う。",related:["同時生起行列","テクスチャ"],src:"skfeat"},
{t:"テンプレートマッチング",en:"Template Matching",aliases:[],cat:"feat",d:"小画像（テンプレート）を滑らせて類似度が最大の位置を探す方法。",detail:"類似度は差の二乗和や正規化相関。回転・スケール変化に弱い。",vs:"特徴点マッチングは見え方の変化に強い部品ベースの対応付け。",ex:"位置合わせの初期推定や検査に使う。",related:["正規化相関","ハフ変換"],src:"ocvtpl"},
{t:"ハフ変換",en:"Hough Transform",aliases:[],cat:"feat",d:"エッジ点がパラメータ空間へ投票し、形状（直線・円等）を検出する方法。",detail:"直線は ρ = x cosθ + y sinθ で表す。欠けやノイズに強い。",vs:"テンプレートマッチングは見え方、ハフ変換は幾何構造を探す。",ex:"レーン検出や格子の検出に使う。",related:["テンプレートマッチング","エッジ"],src:"ocvhough"},
{t:"正規化相関",en:"Normalized Cross-Correlation",aliases:["NCC"],cat:"feat",d:"平均と分散で正規化した相関。明るさのオフセットとゲインに強い類似度。",detail:"値は−1〜1。テンプレートマッチングや位置合わせの類似度に使う。",vs:"単純な差の二乗和は明るさの差に引っ張られる。",ex:"照明差のある画像同士の照合に使う。",related:["テンプレートマッチング"],src:"ocvtpl"},
{t:"特徴点",en:"Keypoint / Interest Point",aliases:["キーポイント"],cat:"feat",d:"対応付けのために選ばれる、局所的に特徴のある点（主にコーナー）。",detail:"再現性（視点変化でも同じ点に出る）と位置の正確さが要求される。",vs:"エッジ上の点は線方向の位置が定まらず、特徴点には不向き。",ex:"パノラマの対応付けの起点になる。",related:["構造テンソル","記述子"],src:"skfeat"},
{t:"構造テンソル",en:"Structure Tensor",aliases:[],cat:"feat",d:"近傍の勾配の外積を重み付き平均した2×2行列。",detail:"固有値の組が、平坦・エッジ・コーナーの局所構造を分類する。Harris検出器の核。",vs:"勾配そのものは1点の情報、構造テンソルは近傍の分布の要約。",ex:"流れの方向推定にも使われる。",related:["Harrisコーナー検出","特徴点"],src:"skfeat"},
{t:"Harrisコーナー検出",en:"Harris Corner Detection",aliases:["Harris検出器"],cat:"feat",d:"構造テンソルの応答 R = det(M) − k(trace M)² でコーナーを検出する方法。",detail:"固有値を直接計算せずに応答を評価する工夫が特徴。kは0.04〜0.06程度の定数。",vs:"FASTは明暗パターンの比較による高速な別系統。",ex:"古典的な対応付けの前段として使われる。",related:["構造テンソル","FAST"],src:"skfeat"},
{t:"FAST",en:"Features from Accelerated Segment Test",aliases:[],cat:"feat",d:"円周上の画素の明暗パターンでコーナーを判定する高速な検出器。",detail:"連続した明るい画素・暗い画素の弧の有無で判定する。リアルタイム用途向き。",vs:"Harrisは勾配の統計、FASTは値の比較のみで判定する。",ex:"ORBの検出段に使われる。",related:["Harrisコーナー検出","ORB"],src:"ocvfeat2d"},
{t:"記述子",en:"Descriptor",aliases:["特徴量記述子"],cat:"feat",d:"特徴点の近傍の見え方を数値化したもの。対応付けの照合に使う。",detail:"回転・スケール・照明の変化への強さが設計目標。実数ベクトル型と二値型がある。",vs:"検出器は位置を決め、記述子は照合のための表現を作る。",ex:"記述子同士の距離で対応候補を決める。",related:["SIFT","ORB"],src:"ocvfeat2d"},
{t:"SIFT",en:"Scale-Invariant Feature Transform",aliases:[],cat:"feat",d:"スケールスペースで検出し、勾配方向ヒストグラムで記述する古典的特徴量。",detail:"スケールと回転に不変な設計。検出→向き正規化→記述の構成が後の手法の原型。",vs:"ORBは二値記述子で高速な代替。",ex:"画像照合の基準手法として使われる。",related:["記述子","スケールスペース"],src:"ocvfeat2d"},
{t:"ORB",en:"Oriented FAST and Rotated BRIEF",aliases:[],cat:"feat",d:"FAST検出とBRIEF二値記述子を組み合わせた高速な特徴量。",detail:"回転への対応を加えてある。ハミング距離で高速に照合できる。",vs:"SIFTは実数記述子で高精度寄り、ORBは速度寄り。",ex:"リアルタイムの追跡やSLAMに使われる。",related:["FAST","記述子"],src:"ocvfeat2d"},
{t:"RANSAC",en:"Random Sample Consensus",aliases:["ランサック"],cat:"feat",d:"ランダムな部分集合でモデルを当てはめ、外れ値に強い推定を行う方法。",detail:"対応点の誤りを前提に、整合する最大の集合を探す。変換推定の標準的な後段。",vs:"最小二乗は外れ値に弱く、全点を使う前提が異なる。",ex:"ホモグラフィ推定で誤対応を除く。",related:["射影変換","記述子"],src:"ocvgeo"},
{t:"背景差分",en:"Background Subtraction",aliases:[],cat:"video",d:"背景モデルと現在フレームの差から前景を抽出する方法。",detail:"背景は画素ごとの統計モデルとして時間更新されるのが実務形。照明変化への対処が要る。",vs:"フレーム間差分は連続フレーム同士の差で、輪郭部分だけが取れる。",ex:"監視映像の動体検出に使う。",related:["フレーム間差分","画像間演算"],src:"ocvbg"},
{t:"フレーム間差分",en:"Frame Differencing",aliases:[],cat:"video",d:"連続フレーム同士の差の絶対値を閾値処理して変化を抽出する方法。",detail:"単純だが、取れるのは変化した部分（主に輪郭）で、物体の内部は抜ける。",vs:"背景差分は背景モデルとの差で全体像が得られる。",ex:"簡易な動き検出に使う。",related:["背景差分","動画像"],src:"ocvbg"},
{t:"動画像",en:"Video / Image Sequence",aliases:["動画"],cat:"video",d:"時間軸を持つ画像の列 f(x, y, t)。",detail:"フレームレートが時間方向の標本化間隔。動きの情報はフレーム間に宿る。",vs:"静止画の集まりと違い、時間方向の関係自体が処理対象。",ex:"追跡や変化検出の入力になる。",related:["背景差分","オプティカルフロー"],src:"ocvbg"},
{t:"オプティカルフロー",en:"Optical Flow",aliases:[],cat:"video",d:"画像上の見かけの動きの速度場（各点の移動ベクトル）。",detail:"亮度恒常の仮定から拘束式が立つ。開口問題のため追加の仮定（Lucas–Kanade等）で解く。",vs:"物体の真の3次元運動ではなく、像の2次元の見かけの動き。",ex:"動きの方向と大きさの可視化に使う。",related:["カルマンフィルタ","動画像"],src:"ocvflow"},
{t:"カルマンフィルタ",en:"Kalman Filter",aliases:[],cat:"video",d:"線形な運動・観測モデルとガウス誤差の前提で、状態を予測と更新で推定する枠組み。",detail:"追跡では位置・速度の推定に使う。前提が崩れる場面では性能が落ちる。",vs:"パーティクルフィルタは非線形・多峰性を扱える代わりに近似計算。",ex:"欠落したフレームの位置を予測で補う。",related:["パーティクルフィルタ","オプティカルフロー"],src:"dip"},
{t:"パーティクルフィルタ",en:"Particle Filter",aliases:[],cat:"video",d:"状態の候補（粒子）の重み付き集合で確率分布を近似する推定法。",detail:"非線形・多峰性の問題に使える。粒子の数と設計が計算量と精度を決める。",vs:"カルマンフィルタは解析解、こちらはサンプリングによる近似。",ex:"遮蔽の前後の追跡継続に使う。",related:["カルマンフィルタ","オプティカルフロー"],src:"dip"},
{t:"教師あり学習",en:"Supervised Learning",aliases:[],cat:"recog",d:"正解ラベルの付いたデータから入出力の対応を学ぶ枠組み。",detail:"分類と回帰が代表。データの作り方（注釈基準・偏り）が性能を左右する。",vs:"教師なしはラベルなしに構造を探す（クラスタリング等）。",ex:"注釈済み画像で分類器を訓練する。",related:["k近傍法","サポートベクトルマシン"],src:"dip"},
{t:"k近傍法",en:"k-Nearest Neighbors (kNN)",aliases:["kNN"],cat:"recog",d:"特徴空間で最も近いk個の学習サンプルの多数決で分類する方法。",detail:"距離の定義と特徴のスケーリングが性能の本質。学習はデータの保持に近い。",vs:"SVMは分離面を最適化する識別器で、考え方が異なる。",ex:"単純な基準手法として比較に使う。",related:["教師あり学習","サポートベクトルマシン"],src:"dip"},
{t:"サポートベクトルマシン",en:"Support Vector Machine (SVM)",aliases:["SVM"],cat:"recog",d:"クラス間のマージンを最大化する分離面を求める識別器。",detail:"カーネル法で非線形分離にも対応する。境界近傍のサンプル（サポートベクトル）だけが解を決める。",vs:"kNNは近傍の投票、SVMは大域的な分離面の最適化。",ex:"特徴量ベースの分類の標準手法だった。",related:["教師あり学習","k近傍法"],src:"dip"},
{t:"ランダムフォレスト",en:"Random Forest",aliases:[],cat:"recog",d:"データと特徴のランダムな部分集合で多数の決定木を育て、投票で決めるアンサンブル。",detail:"単木のばらつきを平均化して安定させる。特徴の重要度も得られる。",vs:"Boostingは誤りを重み付けして逐次に強める別のアンサンブル。",ex:"表形式の特徴量の分類に強い。",related:["教師あり学習","サポートベクトルマシン"],src:"dip"},
{t:"畳み込みニューラルネットワーク",en:"Convolutional Neural Network (CNN)",aliases:["CNN"],cat:"recog",d:"重み共有の畳み込み層とプーリング層を核とする、画像向けの深層学習モデル。",detail:"畳み込みの重みは学習される。局所性と平行移動への頑健さを構造に埋め込む。",vs:"MLPは全結合で、画像の構造を前提にしない。",ex:"画像分類・物体検出の標準モデル。",related:["誤差逆伝播法","プーリング"],src:"dip"},
{t:"誤差逆伝播法",en:"Backpropagation",aliases:["バックプロパゲーション"],cat:"recog",d:"誤差の勾配を出力側から入力側へ連鎖率で伝え、重みを更新する学習法。",detail:"勾配降下法と組み合わせて使う。学習率などの設計が収束を左右する。",vs:"順伝播は予測の計算、逆伝播は学習のための勾配計算。",ex:"MLPやCNNの訓練に使う。",related:["畳み込みニューラルネットワーク"],src:"dip"},
{t:"プーリング",en:"Pooling",aliases:[],cat:"recog",d:"近傍の代表値（最大値・平均）を取って解像度を落とすCNNの層。",detail:"位置のずれへの鈍感さと計算量の削減が目的。最大プーリングが代表。",vs:"ストライド畳み込みも解像度を落とすが、重みを持つ点が異なる。",ex:"特徴マップを段階的に縮小する。",related:["畳み込みニューラルネットワーク"],src:"dip"},
{t:"ピンホールカメラモデル",en:"Pinhole Camera Model",aliases:[],cat:"cam",d:"全光線が1点を通る理想カメラモデル。透視投影の基礎。",detail:"内部パラメータ（焦点距離・主点）と外部パラメータ（位置・姿勢）で記述される。",vs:"実際のレンズは歪曲などのずれを持ち、モデルの拡張が要る。",ex:"キャリブレーションの理論的な土台。",related:["透視投影","歪曲収差"],src:"ocvcalib"},
{t:"透視投影",en:"Perspective Projection",aliases:[],cat:"cam",d:"3次元点を、奥行きZで割って像面に写す投影。x = f X/Z。",detail:"遠いものが小さく、平行線が一点に集まる見え方の幾何的な正体。",vs:"平行投影はZで割らず、遠近感が出ない（図面など）。",ex:"遠近法の定量的な扱いに使う。",related:["ピンホールカメラモデル","同次座標"],src:"ocvcalib"},
{t:"歪曲収差",en:"Distortion",aliases:["レンズ歪み"],cat:"cam",d:"レンズにより像の位置が理想からずれる現象。放射方向の樽型・糸巻き型が代表。",detail:"距離の奇数次でモデル化される。位置測定の系統誤差になるため、補正してから測る。",vs:"ぼけ（PSF）とは別の、位置のずれの誤差。",ex:"格子パターンの撮影で係数を推定する。",related:["ピンホールカメラモデル","被写界深度"],src:"ocvcalib"},
{t:"被写界深度",en:"Depth of Field",aliases:[],cat:"cam",d:"ピントが合って見える奥行きの範囲。",detail:"絞るほど深くなるが、回折ぼけとのトレードオフがある。焦点距離と撮影距離にも依存する。",vs:"焦点深度は像面側の許容範囲を指す、対の概念。",ex:"顕微鏡では深度が浅いことが測定の制約になる。",related:["歪曲収差","点像分布関数"],src:"dip"},
{t:"エピポーラ幾何",en:"Epipolar Geometry",aliases:[],cat:"cam",d:"2視点間の幾何。対応点が相手画像のエピポーラ線上にあるという制約を与える。",detail:"対応探しを2次元から1次元に減らす。基礎行列・基本行列で表される。",vs:"ホモグラフィは平面場面の特殊な関係、こちらは一般の3次元場面の制約。",ex:"ステレオマッチングの前段で平行化する。",related:["ステレオ視","SfM"],src:"ocvcalib"},
{t:"ステレオ視",en:"Stereo Vision",aliases:["ステレオマッチング"],cat:"cam",d:"2視点の視差から奥行きを復元する仕組み。Z = fB/d。",detail:"対応付けの曖昧さ（無テクスチャ・繰り返し）が難所。遠方ほど奥行き分解能が落ちる。",vs:"単眼の手がかり（陰影・動き）とは別の、幾何による復元。",ex:"奥行きマップの生成に使う。",related:["エピポーラ幾何","SfM"],src:"ocvcalib"},
{t:"SfM",en:"Structure from Motion",aliases:[],cat:"cam",d:"複数枚の写真から、カメラの動きと場面の3次元構造を同時に推定する技術。",detail:"特徴点マッチングと幾何推定を束ね、バンドル調整で全体最適化する。",vs:"ステレオは2視点の固定基線、SfMは多数視点と動きの同時推定。",ex:"写真からの3次元モデル作成に使う。",related:["ステレオ視","エピポーラ幾何"],src:"ocvcalib"},
{t:"OpenCV",en:"OpenCV",aliases:[],cat:"prac",d:"リアルタイム性を重視したコンピュータビジョンの総合ライブラリ。",detail:"画像はNumPy配列（主にuint8、BGR順）で扱う。フィルタ・特徴点・カメラ・機械学習まで揃う。",vs:"scikit-imageは科学用途で型規約を明示する系統。",ex:"カメラ入力のリアルタイム処理に使う。",related:["scikit-image","Jupyter"],src:"ocvfeat2d"},
{t:"scikit-image",en:"scikit-image",aliases:[],cat:"prac",d:"科学用途を意識したPythonの画像処理ライブラリ。",detail:"型の規約（floatは0..1など）を明示する。形態学・復元・測定のアルゴリズムが充実。",vs:"OpenCVはBGR・uint8中心の実時間寄りの系統。",ex:"研究用途の解析パイプラインに使う。",related:["OpenCV","Jupyter"],src:"skfeat"},
{t:"Jupyter",en:"Jupyter Notebook",aliases:["Jupyter Notebook"],cat:"prac",d:"コードと出力（画像・グラフ）を1文書に残せる対話的実行環境。",detail:"セル単位の実行で探索に向く。再現性には上からの通し実行への整形が要る。",vs:"通常のスクリプトは一括実行が前提で、途中確認の手軽さが異なる。",ex:"処理の試行錯誤と記録に使う。",related:["OpenCV","scikit-image"],src:"ocvfeat2d"},
{t:"量子化ノイズ",en:"Quantization Noise",aliases:["量子化誤差"],cat:"base",d:"量子化で生じる、元の値と量子化値の差によるノイズ。",detail:"入力が十分複雑なら一様分布の加算ノイズとみなせる。SN比はビット数で決まり、1ビット増で約6dB改善する。",vs:"センサー由来の読み出しノイズとは発生源が異なる。",ex:"階調の段差としてグラデーションに現れる。",related:["量子化","ビット深度"],src:"dip"},
{t:"バンディング",en:"Banding",aliases:["偽輪郭"],cat:"base",d:"滑らかな階調が段状の帯に見える現象。",detail:"量子化のビット不足で、緩やかなグラデーションに偽の境界が立つ。ディザで目立たなくできる。",vs:"ブロッキングはブロック単位の歪みで、こちらは階調方向の段差。",ex:"空のグラデーション写真で帯が見える。",related:["量子化","ビット深度"],src:"dip"},
{t:"開口数",en:"Numerical Aperture",aliases:["NA"],cat:"base",d:"レンズが光を取り込む角度の範囲を表す量。NA = n sinθ。",detail:"回折限界の分解能 d = 0.61λ/NA を決める。大きいほど分解能は上がるが被写界深度は浅くなる。",vs:"F値は写真レンズの明るさの指標で、開口数とは定義が異なる。",ex:"顕微鏡対物レンズの性能表示に使う。",related:["被写界深度","回折"],src:"dip"},
{t:"読み出しノイズ",en:"Read Noise",aliases:[],cat:"base",d:"センサーの読み出し回路で加わる、露光に依らないノイズ。",detail:"暗い信号ほど相対的に効く。冷却や読み出し速度の調整で抑える設計もある。",vs:"ポアソンノイズは光子到着の統計ゆらぎで、信号量に依存する。",ex:"暗部のざらつきの主因になる。",related:["ポアソンノイズ"],src:"dip"},
{t:"外れ値",en:"Outlier",aliases:[],cat:"base",d:"分布から大きく外れた観測値。",detail:"平均や二乗誤差は外れ値に弱く、少数の逸脱に引っ張られる。中央値などロバストな推定で影響を抑える。",vs:"ノイズは全体に乗るばらつき、外れ値は少数点の大きな逸脱。",ex:"測定ミスで1点だけ飛び抜けた値。",related:["メディアンフィルタ"],src:"dip"},
{t:"期待値",en:"Expected Value",aliases:[],cat:"base",d:"確率変数が取る値の、確率で重み付けした平均。",detail:"画像では強度ヒストグラムを確率分布とみた平均が平均輝度に対応する。最小平均二乗誤差の推定など、復元の基準にも現れる。",vs:"標本平均は有限データの平均で、期待値は分布そのものの量。",ex:"2クラスの期待値の差が分離の目安になる。",related:["ヒストグラム"],src:"dip"},
{t:"歪度",en:"Skewness",aliases:[],cat:"hist",d:"分布の非対称さを表す3次の統計量。",detail:"正で右の裾が長く、負で左の裾が長い。ヒストグラム形状の要約に使う。",vs:"尖度は裾の重さと尖り具合を表す4次の量。",ex:"背景ピークの偏りを見る指標になる。",related:["尖度","ヒストグラム"],src:"dip"},
{t:"尖度",en:"Kurtosis",aliases:[],cat:"hist",d:"分布の尖り具合と裾の重さを表す4次の統計量。",detail:"正規分布を基準に比べて論じる。外れ値の多さの目安になる。",vs:"歪度は左右の偏りを見る量。",ex:"裾が重い分布は外れ値を含みやすい。",related:["歪度","ヒストグラム"],src:"dip"},
{t:"二峰性",en:"Bimodality",aliases:[],cat:"hist",d:"ヒストグラムに山が2つある性質。",detail:"前景と背景が分かれている兆候で、大津の二値化が効く条件とされる。山の間の谷がしきい値の目安になる。",vs:"単峰性は山が1つで、クラスの分離が弱い。",ex:"細胞と背景で2つの山ができる。",related:["大津の方法","ヒストグラム"],src:"ocvth"},
{t:"クリッピング",en:"Clipping",aliases:["飽和"],cat:"hist",d:"値域を超えた値を端の値に切り詰める処理・現象。",detail:"明部が255に張り付くと階調が失われる。CLAHEではクリップ制限がコントラストの過剰な増幅を防ぐ。",vs:"正規化は全体を比例的に圧縮するので、端の情報は潰れない。",ex:"露出オーバーで白飛びした部分。",related:["ダイナミックレンジ","ヒストグラム平坦化"],src:"ocvhist"},
{t:"ガウシアンノイズ",en:"Gaussian Noise",aliases:[],cat:"filt",d:"正規分布に従う加算性のノイズ。",detail:"多くの微小な誤差の和として現れる。平均化で抑えられるが、平滑化はエッジも鈍らせる。",vs:"ごま塩ノイズはインパルス性で、メディアンフィルタが有効。",ex:"暗所撮影の背景のざらつき。",related:["ごま塩ノイズ","ガウシアンフィルタ"],src:"ocvfilt"},
{t:"ボックスフィルタ",en:"Box Filter",aliases:["平均値フィルタ","平均フィルタ"],cat:"filt",d:"全係数が等しい平均フィルタ。最も単純な平滑化カーネル。",detail:"周波数応答がsinc状で遮断が甘く、リンギングの原因にもなる。積分画像を使うと高速に計算できる。",vs:"ガウスフィルタは重みが中心ほど大きく、応答も滑らか。",ex:"近傍3×3の平均を取る処理。",related:["ガウシアンフィルタ","sinc関数"],src:"ocvfilt"},
{t:"重ね合わせの原理",en:"Superposition Principle",aliases:[],cat:"filt",d:"入力の和への応答が、応答の和に等しいという線形系の性質。",detail:"線形性とシフト不変性があれば、系の応答はインパルス応答との畳み込みで完全に表せる。",vs:"メディアンなどの非線形処理では成り立たない。",ex:"明るさ2倍の入力には2倍の応答が返る。",related:["線形シフト不変系","インパルス応答","畳み込み"],src:"dip"},
{t:"ヒステリシス",en:"Hysteresis",aliases:[],cat:"filt",d:"状態が履歴に依存する性質。Canny法では2つのしきい値によるエッジ接続に使う。",detail:"強いエッジに接続した弱い応答だけを残すことで、途切れにくくノイズに強い輪郭が得られる。",vs:"単一のしきい値は応答の強さだけで決め、接続性を見ない。",ex:"輪郭の弱い部分をつなぎ止める判定。",related:["Cannyエッジ検出"],src:"ocvcanny"},
{t:"ハロー",en:"Halo",aliases:[],cat:"filt",d:"強いエッジの周囲に現れる、光の輪のようなアーティファクト。",detail:"アンシャープマスクの掛け過ぎや、局所トーンマッピングで生じる。局所コントラスト操作の副作用。",vs:"リンギングは周波数領域の急峻な遮断による波打ちで、発生機序が異なる。",ex:"輪郭の外側が不自然に光って見える。",related:["アンシャープマスキング","リンギング"],src:"ocvfilt"},
{t:"リンギング",en:"Ringing",aliases:[],cat:"freq",d:"急峻な周波数遮断や強い輪郭の近くに現れる、波状のアーティファクト。",detail:"理想フィルタのインパルス応答（sinc関数）の振動が原因。ギブス現象の画像での現れ。",vs:"ハローは空間領域の局所処理による輪で、発生機序が異なる。",ex:"文字の周りに波紋のような影が出る。",related:["ギブス現象","理想フィルタ","バターワースフィルタ"],src:"ocvfft"},
{t:"位相",en:"Phase",aliases:[],cat:"freq",d:"フーリエ成分のずれを表す角度。構造の位置情報を担う。",detail:"振幅だけでは画像の形はほぼ復元できず、位相が輪郭や配置を決めることが知られている。",vs:"振幅（パワースペクトル）は周波数成分の強さを表す。",ex:"位相だけを入れ替えると別の画像の構造になる。",related:["周波数スペクトル"],src:"ocvfft"},
{t:"自己相関",en:"Autocorrelation",aliases:[],cat:"freq",d:"信号と、それをずらした自分自身との相関。",detail:"周期性の検出に使う。パワースペクトルとはフーリエ変換の対の関係（ウィーナー・ヒンチンの定理）にある。",vs:"相互相関は2つの異なる信号の間の類似度。",ex:"繰り返し模様の周期を測る。",related:["周波数スペクトル"],src:"ocvfft"},
{t:"窓関数",en:"Window Function",aliases:[],cat:"freq",d:"有限区間の切り出しで生じる端の不連続を和らげる重み関数。",detail:"DFTは信号が周期的に続くと仮定するため、端の段差がスペクトルの漏れを起こす。ハニング窓などで抑える。",vs:"ゼロ埋めは見かけの密度を上げるだけで、漏れ自体は抑えない。",ex:"端をなだらかに落としてからFFTする。",related:["ゼロ埋め","離散フーリエ変換"],src:"ocvfft"},
{t:"直流成分",en:"DC Component",aliases:["DC成分"],cat:"freq",d:"周波数0の成分。画像の平均値に対応する。",detail:"シフト後のFFT結果の中心に現れる。取り除くと平均輝度が失われる。",vs:"交流成分は周波数0以外の、変化を表す成分の総称。",ex:"スペクトル中心の最も明るい点。",related:["周波数スペクトル"],src:"ocvfft"},
{t:"遮断周波数",en:"Cutoff Frequency",aliases:["カットオフ周波数"],cat:"freq",d:"フィルタが成分を通す／止めるの境界となる周波数。",detail:"理想フィルタではこの半径で不連続に切り替わる。バターワースフィルタではゲインが半分になる点が目安。",vs:"次数は遮断の急峻さを決める別の量。",ex:"ローパスの半径D0として指定する。",related:["ローパスフィルタ","バターワースフィルタ"],src:"ocvfft"},
{t:"ノッチフィルタ",en:"Notch Filter",aliases:[],cat:"freq",d:"特定の周波数だけを狙って除去するフィルタ。",detail:"周期ノイズはスペクトル上で点状に現れるため、その点だけを消すと画像本体への影響が小さい。",vs:"ローパスは高周波全体を落とすため、鮮鋭度も失う。",ex:"網目模様の干渉ノイズだけを消す。",related:["ローパスフィルタ"],src:"ijfft"},
{t:"バンドパスフィルタ",en:"Bandpass Filter",aliases:[],cat:"freq",d:"中間の周波数帯だけを通すフィルタ。",detail:"ローパスとハイパスの組み合わせで作れる。DoG（ガウス差分）はその近似になっている。",vs:"バンドリジェクトは逆に中間帯だけを止める。",ex:"特定の粗さのテクスチャだけを抽出する。",related:["ローパスフィルタ","ハイパスフィルタ","DoG"],src:"ocvfft"},
{t:"バタフライ演算",en:"Butterfly Operation",aliases:[],cat:"freq",d:"FFTで繰り返し現れる、2点の和と差（に回転因子を掛ける）基本演算。",detail:"Cooley–Tukey分割の最小単位。蝶が羽を広げた形の信号線図が名前の由来。",vs:"素朴なDFTは全点の総和を毎回計算し、この再利用をしない。",ex:"8点FFTでは各段で4回現れる。",related:["高速フーリエ変換","離散フーリエ変換"],src:"ocvfft"},
{t:"sinc関数",en:"Sinc Function",aliases:["シンク関数"],cat:"freq",d:"sin(x)/x の形の関数。理想ローパスフィルタのインパルス応答。",detail:"無限に振動しながら減衰するため、そのまま使うとリンギングになる。補間理論でも中心的な役割を持つ。",vs:"ガウス関数は振動せず単調に減衰する。",ex:"理想フィルタの断面形状。",related:["理想フィルタ","リンギング"],src:"dip"},
{t:"オーバーシュート",en:"Overshoot",aliases:[],cat:"freq",d:"段差の近くで値が行き過ぎて盛り上がる現象。",detail:"ギブス現象では段差の約9%に達する。フィルタを滑らかにしても消えず、幅だけが狭まる。",vs:"アンダーシュートは反対側に沈む行き過ぎ。",ex:"エッジの直前が少し明るく盛り上がる。",related:["ギブス現象","リンギング"],src:"dip"},
{t:"端効果",en:"Border Effect",aliases:["境界効果"],cat:"freq",d:"画像の端で近傍が欠けるために生じる、処理の偏り。",detail:"周波数領域では周期仮定による反対側からの回り込み、空間領域ではパディング方法の影響として現れる。",vs:"ゼロ埋めは周波数軸の補間の話で、端効果は画像境界の話。",ex:"端の画素だけフィルタ結果が暗くなる。",related:["ゼロ埋め"],src:"ocvfft"},
{t:"パーセバルの定理",en:"Parseval's Theorem",aliases:[],cat:"freq",d:"信号の総エネルギーが、空間領域と周波数領域で等しいという定理。",detail:"Σ|f|² = (1/MN)Σ|F|² の形で書ける。エネルギーが保存されることが、フィルタ設計の見通しを与える。",vs:"相関定理は相関とスペクトルの積の関係を述べる別の定理。",ex:"フィルタ前後でエネルギーの増減を検算する。",related:["周波数スペクトル","離散フーリエ変換"],src:"ocvfft"},
{t:"ポアソンノイズ",en:"Poisson Noise",aliases:["ショットノイズ"],cat:"rest",d:"光子の到着数の統計ゆらぎによるノイズ。分散が平均（信号量）に等しい。",detail:"暗所ほど相対的に支配的になる。Richardson-Lucy法はこのノイズモデルを前提にする。",vs:"読み出しノイズは信号量に依らない、回路由来のノイズ。",ex:"低照度の蛍光画像の粒状感。",related:["読み出しノイズ","Richardson-Lucy法"],src:"skrest"},
{t:"トーンマッピング",en:"Tone Mapping",aliases:[],cat:"rest",d:"HDRの広い輝度範囲を、表示可能な範囲へ圧縮する処理。",detail:"大域的な曲線を適用する方式と、局所適応型がある。局所型はハローを生みやすい。",vs:"ガンマ補正は表示特性への単純な冪変換で、範囲圧縮の設計とは目的が異なる。",ex:"逆光写真の暗部と明部を同時に見せる。",related:["HDR","ダイナミックレンジ","ハロー"],src:"dip"},
{t:"サブピクセル",en:"Subpixel",aliases:[],cat:"rest",d:"画素の間隔より細かい精度（位置・解像）のこと。",detail:"補間や複数フレームのずれを利用して到達する。超解像や高精度な位置計測の基礎。",vs:"画素単位の精度では、量子化された格子上の値しか得られない。",ex:"0.1画素の精度で位置を推定する。",related:["超解像","双線形補間"],src:"skrest"},
{t:"メタメリズム",en:"Metamerism",aliases:["条件等色"],cat:"color",d:"分光分布が異なるのに、同じ色に見える現象と、その色の組。",detail:"三刺激値が一致すれば同じ色に見えるために起こる。照明が変わると一致が崩れることがある。",vs:"同じ分光分布の色は、照明や観測者が変わっても一致が保たれる。",ex:"印刷物と画面で色が合って見えること。",related:["XYZ表色系","等色関数"],src:"skcolor"},
{t:"クロマサブサンプリング",en:"Chroma Subsampling",aliases:[],cat:"color",d:"色差成分の解像度を輝度より落として、情報量を減らす方式。",detail:"視覚は色の細部には鈍いことを利用する。JPEGの4:2:0が代表例。",vs:"輝度も一緒に落とす通常の縮小とは、落とす成分が異なる。",ex:"動画配信の帯域削減に使う。",related:["YUV","色空間"],src:"dip"},
{t:"ウェーバー・フェヒナーの法則",en:"Weber–Fechner Law",aliases:["ウェーバーの法則"],cat:"color",d:"感覚量は刺激の対数に比例するという法則。",detail:"輝度差の知覚が絶対量ではなく比率で決まることの基礎。ガンマや対数変換の知覚的な根拠になる。",vs:"スティーブンスの冪法則は別の近似式で、指数は感覚の種類ごとに異なる。",ex:"暗部では小さな輝度差にも気づく。",related:["マッハバンド","コントラスト感度"],src:"dip"},
{t:"sRGB",en:"sRGB",aliases:[],cat:"color",d:"ディスプレイ表示の標準として広く使われるRGB色空間。",detail:"原色の色度とガンマ特性が規格化されている。前提なしにRGBと言う場合、多くはsRGBを指す。",vs:"Adobe RGBはより広い色域を持つ別の規格。",ex:"Web画像の標準の色空間。",related:["色空間","XYZ表色系"],src:"skcolor"},
{t:"ブリードスルー",en:"Bleed-through",aliases:[],cat:"color",d:"蛍光画像などで、あるチャンネルの信号が別のチャンネルに漏れて写る現象。",detail:"発光・励起スペクトルの重なりで起こる。単独染色の対照画像で漏れ量を測り、補正する。",vs:"自己蛍光は試料自体の発光で、漏れ込みとは発生源が異なる。",ex:"緑の蛍光が赤チャンネルにも写る。",related:["チャンネル","画像間演算"],src:"ijana"},
{t:"レシオメトリ",en:"Ratiometric Imaging",aliases:["比率イメージング"],cat:"color",d:"2波長の強度比から量を推定する蛍光イメージング手法。",detail:"比を取ることで、色素濃度や照明のむらなど共通の変動を打ち消せる。カルシウムイメージングが代表例。",vs:"単一波長の強度測定は、濃度と量の区別がつかない。",ex:"2波長励起の比でカルシウム濃度を測る。",related:["画像間演算","チャンネル"],src:"ijana"},
{t:"レジストレーション",en:"Registration",aliases:["位置合わせ"],cat:"geom",d:"複数の画像の座標を一致させる処理。",detail:"剛体・アフィン・非剛体などの変換モデルを選び、類似度を最適化して推定する。経時変化の比較や超解像の前提になる。",vs:"パノラマ合成はレジストレーションを含む応用の一つ。",ex:"治療前後の画像の位置を揃える。",related:["アフィン変換","射影変換","超解像"],src:"ocvgeo"},
{t:"再投影誤差",en:"Reprojection Error",aliases:[],cat:"geom",d:"推定した幾何モデルで投影し直した点と、実測点との距離。",detail:"キャリブレーションやSfMの精度指標になる。バンドル調整はこの誤差の総和を最小化する。",vs:"代数誤差は計算は簡単だが、幾何的な意味を持たない。",ex:"キャリブレーションの良し悪しを画素単位で測る。",related:["バンドル調整","射影変換"],src:"ocvcalib"},
{t:"最小二乗法",en:"Least Squares",aliases:[],cat:"geom",d:"誤差の二乗和を最小にする推定法。",detail:"変換パラメータや直線のあてはめの基本になる。外れ値に弱いため、RANSACなどと組み合わせる。",vs:"最尤推定は確率モデルの尤度を最大化する枠組みで、ノイズがガウス分布なら最小二乗と一致する。",ex:"対応点からホモグラフィを求める。",related:["RANSAC","外れ値"],src:"dip"},
{t:"距離変換",en:"Distance Transform",aliases:[],cat:"seg",d:"各前景画素に、最も近い背景までの距離を値として与える変換。",detail:"分水嶺の種の生成や、太さの測定、重なった対象の分離に使う。ユークリッド距離が代表的。",vs:"細線化は幅を1画素に潰す処理で、距離そのものは保持しない。",ex:"粒子の中心ほど大きな値になる画像。",related:["細線化","ラベリング","分水嶺"],src:"skdt"},
{t:"分水嶺",en:"Watershed",aliases:["ウォーターシェッド"],cat:"seg",d:"画像を地形とみて、谷ごとに領域を分ける分割法。",detail:"触れ合った粒子や細胞の分離に強い。種（マーカー）を置く制御型が実務では主流。",vs:"しきい値処理だけでは、接触した対象を分離できない。",ex:"重なった細胞を1個ずつに分ける。",related:["距離変換","領域分割"],src:"skdt"},
{t:"混合ガウスモデル",en:"Gaussian Mixture Model",aliases:["GMM"],cat:"seg",d:"複数のガウス分布の重み付き和で、データの分布を表すモデル。",detail:"EMアルゴリズムで推定する。各画素・特徴を、クラスの確率つきで割り当てられる（ソフトな割当て）。",vs:"k-means法は最も近い中心への硬い割当てのみを行う。",ex:"背景モデルとして動画像処理にも使う。",related:["クラスタリング","k-means法"],src:"dip"},
{t:"ミーンシフト",en:"Mean Shift",aliases:["平均シフト"],cat:"seg",d:"密度の高い方へ点を繰り返し移動させ、山ごとにクラスタを作る手法。",detail:"クラスタ数を事前に決めなくてよい。帯域幅（カーネルの幅）が山の細かさを決める。",vs:"k-means法は中心の数kを先に決める必要がある。",ex:"色の分布の山ごとに領域を分ける。",related:["クラスタリング","k-means法"],src:"dip"},
{t:"トップハット変換",en:"Top-hat Transform",aliases:[],cat:"seg",d:"原画像とオープニング結果の差を取るモルフォロジー演算。",detail:"背景より明るい小さな構造だけを抽出する（ホワイトトップハット）。暗い構造にはブラックハットを使う。",vs:"オープニング自体は、小構造を除去した背景の推定にあたる。",ex:"むらのある背景から小さな斑点だけを抜く。",related:["オープニング","モルフォロジー処理"],src:"ocvmorph"},
{t:"ミンコフスキー和",en:"Minkowski Sum",aliases:[],cat:"seg",d:"2つの集合の要素同士の和で作る集合。膨張の集合論的な定義に現れる。",detail:"膨張は構造化要素とのミンコフスキー和として、収縮はその双対として定義される。",vs:"畳み込みは値の積と和の演算で、集合の和とは別の演算。",ex:"膨張処理の数学的な定義。",related:["膨張","モルフォロジー処理"],src:"ocvmorph"},
{t:"シェーディング",en:"Shading",aliases:["照明むら"],cat:"seg",d:"照明の不均一で生じる、緩やかな輝度のむら。",detail:"背景推定（ローリングボールやオープニング）で補正する。定量測定では系統誤差になる。",vs:"ビネッティングはレンズの周辺光量落ちで、原因が光学系にある。",ex:"画像の端だけが暗くなるむら。",related:["ローリングボール"],src:"ijana"},
{t:"ローリングボール",en:"Rolling Ball",aliases:[],cat:"seg",d:"画像面の下を球が転がる軌跡で背景を推定する手法。ImageJの背景除去の原理として知られる。",detail:"球の半径より小さい構造は前景として残り、緩やかな背景だけが差し引かれる。",vs:"オープニングによる背景推定は、構造化要素の形に依存する。",ex:"照明むらを背景として差し引く。",related:["シェーディング","モルフォロジー処理"],src:"ijana"},
{t:"ガボールフィルタ",en:"Gabor Filter",aliases:[],cat:"feat",d:"ガウス窓を掛けた正弦波のフィルタ。方向と周波数に選択性を持つ。",detail:"視覚野の単純型細胞の応答に似るとされる。テクスチャや指紋の解析に使う。",vs:"Sobelフィルタは勾配の近似で、周波数の選択性は持たない。",ex:"特定方向の縞模様だけを抽出する。",related:["テクスチャ"],src:"skfeat"},
{t:"ハミング距離",en:"Hamming Distance",aliases:[],cat:"feat",d:"2つのビット列で、異なるビットの数。",detail:"二値記述子（ORBなど）のマッチングは、ハミング距離の小さい相手を探す。高速に計算できる。",vs:"ユークリッド距離は実数ベクトルの記述子（SIFTなど）で使う。",ex:"記述子同士の近さの尺度。",related:["ORB","SIFT"],src:"ocvfeat2d"},
{t:"BRIEF",en:"BRIEF",aliases:[],cat:"feat",d:"特徴点まわりの画素対の明暗比較をビット列にする二値記述子。",detail:"回転・スケールの不変性は持たないが高速。ORBはBRIEFに方向付けを加えて改良したもの。",vs:"SIFTは勾配ヒストグラムによる実数の記述子で、頑健だが計算が重い。",ex:"高速なマッチングの下地になる記述子。",related:["ORB","記述子"],src:"ocvfeat2d"},
{t:"KAZE",en:"KAZE",aliases:[],cat:"feat",d:"非線形スケール空間を使う特徴点の検出・記述手法。",detail:"ガウスぼかしの代わりに非線形拡散でスケールを作り、輪郭を保ったまま多スケール化する。",vs:"SIFTはガウスぼかしによる線形スケール空間を使う。",ex:"輪郭の多い画像での特徴点検出。",related:["SIFT","スケールスペース"],src:"ocvfeat2d"},
{t:"固有値",en:"Eigenvalue",aliases:[],cat:"feat",d:"行列がベクトルの向きを変えず、大きさだけを変える、その倍率。",detail:"構造テンソルの2つの固有値の大小で、平坦・縁・角を判定する（Harris検出の基礎）。",vs:"固有ベクトルは、対応する向きを表す。",ex:"両方の固有値が大きい点が角になる。",related:["構造テンソル","Harrisコーナー検出"],src:"dip"},
{t:"特徴ベクトル",en:"Feature Vector",aliases:["特徴空間"],cat:"feat",d:"対象を数値の組（ベクトル）として表したもの。",detail:"分類やクラスタリングは、特徴空間での距離や境界として定式化される。成分の尺度を揃える（正規化）ことが前提になることが多い。",vs:"記述子は、特徴点まわりの局所表現に限った呼び方。",ex:"色と形の数値を並べた表現。",related:["記述子","クラスタリング"],src:"dip"},
{t:"検量線",en:"Calibration Curve",aliases:[],cat:"eval",d:"既知の標準試料の信号と量の関係を表す曲線。",detail:"測定強度を濃度などの物理量に換算する根拠になる。直線性の範囲と切片（背景）の確認が要る。",vs:"空間校正は長さの換算で、こちらは量（濃度）の換算。",ex:"標準液の蛍光強度から未知試料の濃度を求める。",related:["空間校正","ダイナミックレンジ"],src:"ijana"},
{t:"モスキートノイズ",en:"Mosquito Noise",aliases:[],cat:"eval",d:"強い輪郭の周囲に、蚊が飛ぶように現れる圧縮ノイズ。",detail:"高周波成分の量子化誤差が原因。ブロッキングと並ぶ、JPEGや動画圧縮の代表的なアーティファクト。",vs:"ブロッキングはブロック境界の段差として現れる。",ex:"文字の周りのざらつき。",related:["ブロッキング","離散コサイン変換"],src:"dip"},
{t:"ブロッキング",en:"Blocking Artifact",aliases:["ブロックノイズ","ブロック歪み"],cat:"eval",d:"ブロック単位の圧縮で、境界に段差が現れるアーティファクト。",detail:"低ビットレートで顕著になる。ブロックごとに独立に量子化されることが原因。",vs:"モスキートノイズは輪郭周辺のざらつきとして現れる。",ex:"空の部分に四角い段差が見える。",related:["モスキートノイズ","離散コサイン変換"],src:"dip"},
{t:"LZW",en:"LZW",aliases:[],cat:"eval",d:"辞書式の可逆圧縮アルゴリズム。TIFFやGIFで使われる。",detail:"繰り返しパターンを辞書に登録し、短い符号に置き換える。劣化はないが、ノイズの多い画像では圧縮率が下がる。",vs:"JPEGは非可逆で、写真では高い圧縮率が得られる代わりに歪みが出る。",ex:"TIFF保存時の圧縮方式の選択肢。",related:["可逆圧縮"],src:"dip"},
{t:"開口問題",en:"Aperture Problem",aliases:[],cat:"video",d:"小さな窓を通して見ると、動きのうち縁に垂直な成分しか分からない問題。",detail:"オプティカルフローの拘束式が1本しか得られないことに対応する。角のような2方向の手がかりがある場所では解ける。",vs:"対応付けの曖昧さは大域的な問題で、こちらは局所の窓に起因する。",ex:"斜めの棒が窓の中で横に動いて見える。",related:["オプティカルフロー","亮度恒常"],src:"ocvflow"},
{t:"亮度恒常",en:"Brightness Constancy",aliases:[],cat:"video",d:"物体上の点の明るさは、移動しても変わらないという仮定。",detail:"オプティカルフローの拘束式 I_x u + I_y v + I_t = 0 の前提になる。照明変化や影の動きで破れる。",vs:"勾配恒常は明るさの勾配が不変とする、より強い仮定の変種。",ex:"動く物体の同じ点は同じ明るさ、という前提。",related:["オプティカルフロー","開口問題"],src:"ocvflow"},
{t:"オクルージョン",en:"Occlusion",aliases:["遮蔽"],cat:"video",d:"手前の物体に隠れて、対象が見えなくなること。",detail:"追跡では見失いの主因になる。予測でつなぐか、再検出で復帰させる。",vs:"フレームアウトは画角の外に出ることで、隠れる現象とは異なる。",ex:"人が柱の後ろに隠れる場面。",related:["カルマンフィルタ","オプティカルフロー"],src:"ocvflow"},
{t:"Lucas-Kanade法",en:"Lucas–Kanade Method",aliases:["ルーカス・カナデ法"],cat:"video",d:"近傍のフローは一定と仮定し、最小二乗で動きを求める手法。",detail:"開口問題を、窓内の複数の画素の方程式を束ねて解く。ピラミッド化で大きな動きにも対応する。",vs:"Horn-Schunck法は全体の滑らかさを課す大域的な手法。",ex:"特徴点のフレーム間追跡。",related:["オプティカルフロー","Horn-Schunck法","最小二乗法"],src:"ocvflow"},
{t:"Horn-Schunck法",en:"Horn–Schunck Method",aliases:["ホーン・シュンク法"],cat:"video",d:"フロー場全体の滑らかさを正則化として課す、大域的なオプティカルフロー推定法。",detail:"密なフローが得られるが、動きの境界まで滑らかになってしまう。",vs:"Lucas-Kanade法は局所の窓ごとに解く手法。",ex:"画面全体の動き場の推定。",related:["オプティカルフロー","Lucas-Kanade法","正則化"],src:"ocvflow"},
{t:"活性化関数",en:"Activation Function",aliases:[],cat:"recog",d:"ニューロンの出力に非線形性を与える関数。ReLUやシグモイドが代表。",detail:"これがないと、多層にしても全体が1つの線形変換に潰れてしまう。勾配消失の起こりにくさが選択の基準になる。",vs:"損失関数は出力と正解のずれを測る、学習のもう一方の部品。",ex:"ReLUは負の入力を0にする関数。",related:["多層パーセプトロン","誤差逆伝播法"],src:"dip"},
{t:"決定木",en:"Decision Tree",aliases:[],cat:"recog",d:"特徴への質問を枝分かれさせて分類するモデル。",detail:"解釈しやすいが過学習しやすい。ランダムフォレストは決定木の集団でこれを抑える。",vs:"サポートベクトルマシンは境界（超平面）で分ける幾何的なモデル。",ex:"しきい値の質問を繰り返す分類。",related:["ランダムフォレスト","サポートベクトルマシン"],src:"dip"},
{t:"汎化",en:"Generalization",aliases:[],cat:"recog",d:"学習データだけでなく、未知のデータでも性能が出る性質。",detail:"過学習の反対側にある目標。データ量、正則化、検証データでの評価で管理する。",vs:"学習データでの精度は当てはまりの良さで、汎化とは別に測る。",ex:"新しい画像でも正しく分類できること。",related:["過学習"],src:"dip"},
{t:"過学習",en:"Overfitting",aliases:["過適合"],cat:"recog",d:"学習データに合わせ過ぎて、未知のデータで性能が落ちる状態。",detail:"モデルの自由度に対してデータが不足すると起こる。正則化、データ拡張、早期終了で抑える。",vs:"学習不足は、訓練データにも当てはまっていない状態。",ex:"訓練では満点だが本番で崩れるモデル。",related:["汎化","正則化"],src:"dip"},
{t:"学習率",en:"Learning Rate",aliases:[],cat:"recog",d:"勾配降下法でパラメータを更新する歩幅。",detail:"大き過ぎると発散し、小さ過ぎると収束が遅い。学習の途中で減衰させるスケジュールがよく使われる。",vs:"エポック数はデータ全体を何周するかの回数で、歩幅とは別の調整量。",ex:"学習の進み具合を決める最重要の調整量。",related:["勾配降下法","誤差逆伝播法"],src:"dip"},
{t:"勾配降下法",en:"Gradient Descent",aliases:[],cat:"recog",d:"損失の勾配の逆向きに少しずつパラメータを動かす最適化法。",detail:"誤差逆伝播で得た勾配を使う。確率的勾配降下法（SGD）はミニバッチで勾配を近似する。",vs:"最小二乗法は線形の場合に一括で解けるが、こちらは反復で近づく汎用の枠組み。",ex:"山の斜面を下るように損失を減らす。",related:["誤差逆伝播法","学習率","最小二乗法"],src:"dip"},
{t:"全結合層",en:"Fully Connected Layer",aliases:["全結合"],cat:"recog",d:"前段の全ユニットと結合する層。分類の最終段に置かれることが多い。",detail:"パラメータ数が多くなりやすい。CNNでは畳み込み層で特徴を作り、全結合層で判断する構成が典型。",vs:"畳み込み層は局所結合と重み共有でパラメータを抑える。",ex:"特徴をクラス確率に変換する最終層。",related:["畳み込みニューラルネットワーク","多層パーセプトロン"],src:"dip"},
{t:"パーセプトロン",en:"Perceptron",aliases:[],cat:"recog",d:"入力の重み付き和をしきい値で判定する、最も単純な学習モデル。",detail:"線形分離可能な問題しか解けないことが限界として知られ、多層化と誤差逆伝播が突破口になった。",vs:"多層パーセプトロンは隠れ層を持ち、非線形な境界を表せる。",ex:"ニューラルネットワークの原型。",related:["多層パーセプトロン","教師あり学習"],src:"dip"},
{t:"多層パーセプトロン",en:"Multilayer Perceptron",aliases:["MLP"],cat:"recog",d:"隠れ層を持つ順伝播型のニューラルネットワーク。",detail:"誤差逆伝播法で学習する。画像ではCNNが主流だが、抽出済みの特徴量からの分類などに今も使う。",vs:"CNNは畳み込みによる局所構造の利用を前提にした構造。",ex:"特徴ベクトルを入力する分類器。",related:["パーセプトロン","誤差逆伝播法","畳み込みニューラルネットワーク"],src:"dip"},
{t:"ブースティング",en:"Boosting",aliases:["Boosting"],cat:"recog",d:"弱い識別器を逐次的に作り、重み付き多数決で強い識別器にする手法。",detail:"前の段が間違えたデータを重視して次を作る（AdaBoost）。Viola-Jonesの顔検出は、Haar状特徴とAdaBoost、カスケードの組み合わせで知られる。",vs:"ランダムフォレストは木を並列に作るバギング系の集団学習。",ex:"弱い分類器の積み重ねで顔を検出する。",related:["ランダムフォレスト","教師あり学習"],src:"dip"},
{t:"アノテーション",en:"Annotation",aliases:["注釈付け"],cat:"recog",d:"データに正解ラベルや領域を付ける作業。",detail:"教師あり学習の品質は、アノテーションの正確さと一貫性に強く依存する。半教師あり学習はその量を減らす工夫。",vs:"画像処理のラベリングは連結成分への番号付けで、場面によって意味が異なる。",ex:"画像に写る対象へ枠と名前を付ける。",related:["教師あり学習","ラベリング"],src:"dip"},
{t:"内部パラメータ",en:"Intrinsic Parameters",aliases:[],cat:"cam",d:"カメラ自体の幾何（焦点距離・主点・歪み係数）を表すパラメータ。",detail:"キャリブレーションで求める。レンズ交換やズームで変わる。",vs:"外部パラメータはカメラの位置と姿勢で、場面ごとに変わる。",ex:"焦点距離を画素単位で表した値。",related:["外部パラメータ","ピンホールカメラモデル","主点"],src:"ocvcalib"},
{t:"外部パラメータ",en:"Extrinsic Parameters",aliases:[],cat:"cam",d:"カメラの位置と姿勢（回転と並進）を表すパラメータ。",detail:"世界座標からカメラ座標への変換として表される。撮影ごとに変わる。",vs:"内部パラメータはカメラ固有で、撮影では不変。",ex:"2台のカメラの相対位置と向き。",related:["内部パラメータ","ピンホールカメラモデル"],src:"ocvcalib"},
{t:"主点",en:"Principal Point",aliases:[],cat:"cam",d:"光軸が像面と交わる点。画像座標の原点となるべき点。",detail:"通常は画像中心の付近だが、厳密にはずれている。内部パラメータの一つとして推定する。",vs:"焦点はレンズの光学的な点で、像面上の主点とは場所が異なる。",ex:"キャリブレーションで求める中心座標。",related:["内部パラメータ","ピンホールカメラモデル"],src:"ocvcalib"},
{t:"焦点距離",en:"Focal Length",aliases:[],cat:"cam",d:"レンズ中心から像面までの距離。写る範囲と拡大率を決める。",detail:"透視投影 x = f X/Z の f に対応する。画素単位で表すと内部パラメータになる。長いほど望遠になる。",vs:"被写界深度はピントの合う奥行きの範囲で、距離そのものではない。",ex:"広角と望遠の違いを決める量。",related:["透視投影","ピンホールカメラモデル","内部パラメータ"],src:"ocvcalib"},
{t:"回折",en:"Diffraction",aliases:[],cat:"cam",d:"波が障害物の縁で回り込む現象。開口が小さいほど像をぼかす。",detail:"絞るほど被写界深度は深くなるが、回折ぼけが増えるトレードオフがある。エアリーディスクが点像の大きさの限界を決める。",vs:"収差はレンズ形状の不完全さによるずれで、回折は波動性そのものによる。",ex:"絞り過ぎると全体が眠くなる。",related:["被写界深度","開口数","点像分布関数"],src:"dip"},
{t:"フィルファクタ",en:"Fill Factor",aliases:[],cat:"cam",d:"画素の面積のうち、光を受ける部分の割合。",detail:"回路の部分は光を受けないため、マイクロレンズで集光して実効の感度を補う。",vs:"量子効率は、当たった光子を電子に変える割合で、別の量。",ex:"受光面積の割合としての表示。",related:["撮像素子"],src:"dip"},
{t:"ローリングシャッター",en:"Rolling Shutter",aliases:[],cat:"cam",d:"行ごとに時刻をずらして読み出すシャッター方式。",detail:"速い動きで像が傾いたり歪んだりする。CMOSセンサーで一般的。",vs:"グローバルシャッターは全画素が同時露光で、時刻のずれがない。",ex:"動くプロペラが曲がって写る。",related:["撮像素子"],src:"dip"},
{t:"レクティフィケーション",en:"Rectification",aliases:["画像平行化"],cat:"cam",d:"ステレオ画像対を、エピポーラ線が水平になるよう変形する処理。",detail:"対応探しが同じ行の中だけの1次元探索になる。キャリブレーション結果から計算する。",vs:"濃度の正規化は画素値の話で、こちらは幾何の変形。",ex:"ステレオマッチングの前処理。",related:["エピポーラ幾何","ステレオ視"],src:"ocvcalib"},
{t:"バンドル調整",en:"Bundle Adjustment",aliases:[],cat:"cam",d:"再投影誤差の総和を最小化し、カメラと3次元点を全体で最適化する処理。",detail:"SfMの最終段にあたる。非線形最小二乗として解く。",vs:"三角測量はカメラを固定して、点の位置だけを求める処理。",ex:"SfMの推定を仕上げる最適化。",related:["SfM","再投影誤差","最小二乗法"],src:"ocvcalib"},
{t:"アクティブステレオ",en:"Active Stereo",aliases:[],cat:"cam",d:"プロジェクタでパターンを投影し、対応付けを助けるステレオ法。",detail:"無テクスチャの面でも対応が取れる。構造化光法の一種。",vs:"通常のステレオ（パッシブ）は、場面の見た目だけに頼る。",ex:"白い壁の奥行きを測る。",related:["ステレオ視","エピポーラ幾何"],src:"ocvcalib"},
{t:"NumPy",en:"NumPy",aliases:[],cat:"prac",d:"Pythonの数値計算ライブラリ。画像を配列として扱う基盤になる。",detail:"OpenCVもscikit-imageも、画像をNumPy配列で表す。ベクトル演算で画素処理を高速に書ける。",vs:"画像処理そのものの関数は持たず、配列操作が役割。",ex:"画像の平均や差分を配列演算で書く。",related:["OpenCV","scikit-image"],src:"ocvfeat2d"},
{t:"モルフォロジー処理",en:"Mathematical Morphology",aliases:["形態学処理","モルフォロジー演算"],cat:"seg",d:"集合の形の操作で画像を処理する分野・手法の総称。",detail:"膨張・収縮を基本に、オープニング、クロージング、トップハット変換などを組み立てる。構造要素が処理の形を決める。",vs:"空間フィルタリングは値の重み付き和で定義され、こちらは集合の包含関係で定義される。",ex:"二値画像の穴埋めや突起の除去。",related:["膨張","収縮","構造要素"],src:"ocvmorph"},
{t:"離散コサイン変換",en:"Discrete Cosine Transform",aliases:["DCT"],cat:"eval",d:"信号を余弦波の和に分解する変換。JPEG圧縮の基盤。",detail:"エネルギーが低周波に集中する性質を利用し、高周波を粗く量子化して情報を削る。8×8ブロック単位で適用される。",vs:"フーリエ変換は複素指数関数を使い、こちらは実数の余弦だけを使う。",ex:"JPEGの圧縮過程の中核。",related:["ブロッキング","モスキートノイズ"],src:"dip"},
{t:"可逆圧縮",en:"Lossless Compression",aliases:["ロスレス圧縮"],cat:"eval",d:"復元時に元のデータを完全に再現できる圧縮。",detail:"冗長性の除去だけで、情報を削らない。PNGや、LZW圧縮のTIFFが代表。医療・計測など劣化が許されない用途で必須になる。",vs:"非可逆圧縮は知覚しにくい情報を捨てて、高い圧縮率を得る。",ex:"計測用画像の保存形式。",related:["LZW"],src:"dip"},
{t:"撮像素子",en:"Image Sensor",aliases:["イメージセンサ"],cat:"cam",d:"光を電気信号に変える素子。CCDやCMOSが代表。",detail:"画素ごとにフォトダイオードが並び、光子を電子に変える。フィルファクタや量子効率が感度を決める。",vs:"レンズは光を集める光学系で、撮像素子は光を受けて変換する側。",ex:"カメラの心臓部にあたる部品。",related:["フィルファクタ","ローリングシャッター"],src:"dip"},
{t:"レイリー基準",en:"Rayleigh Criterion",aliases:[],cat:"base",d:"2つの点像が分解できる限界の目安。エアリーディスクの中心が相手の最初の暗環に重なる距離。",detail:"d = 0.61λ/NA で与えられる。開口数と波長が分解能の理論限界を決める。",vs:"ナイキスト基準は標本化間隔の条件で、こちらは光学系の分解限界。",ex:"顕微鏡の分解能の理論値。",related:["開口数","点像分布関数"],src:"dip"},
{t:"グレースケール",en:"Grayscale",aliases:["グレースケール画像"],cat:"base",d:"明るさだけを値に持つ単一チャンネルの画像。",detail:"色情報を持たず、階調の段数がビット深度で決まる。多くの画像処理はグレースケールを前提に定式化される。",vs:"カラー画像は複数のチャンネルで色を表す。",ex:"蛍光強度を写したモノクロ画像。",related:["ビット深度","量子化"],src:"dip"},
{t:"トポロジー",en:"Topology",aliases:["位相幾何学的性質"],cat:"seg",d:"連結の仕方や穴の数など、伸縮しても変わらない図形の性質。",detail:"デジタル画像では4連結/8連結の選び方でトポロジーが変わる。対象と背景で連結性を対にしないと矛盾（連結パラドックス）が生じる。",vs:"幾何は距離や角度を扱い、トポロジーはつながり方だけを扱う。",ex:"穴の数（オイラー数）による形状の分類。",related:["ラベリング","細線化"],src:"skdt"},
{t:"マージン",en:"Margin",aliases:[],cat:"recog",d:"分類境界と最も近いデータ点との距離。SVMの中心概念。",detail:"マージンを最大化する境界が、未知データへの汎化に優れるとされる。境界を決める近傍の点をサポートベクトルと呼ぶ。",vs:"損失の値は当てはまりの量、マージンは境界の余裕の量。",ex:"境界から最も近い点までの幅。",related:["サポートベクトルマシン","汎化"],src:"dip"},
{t:"カスケード",en:"Cascade",aliases:["カスケード分類器"],cat:"recog",d:"軽い識別器を多段につなぎ、明らかな負例を早期に捨てる構造。",detail:"Viola-Jones顔検出で有名。大半の窓は最初の数段で棄却されるため、全体として高速になる。",vs:"単一の強い識別器は、全ての窓に同じ計算をかける。",ex:"顔でない窓を次々にふるい落とす検出器。",related:["ブースティング"],src:"dip"},
{t:"パターン認識",en:"Pattern Recognition",aliases:[],cat:"recog",d:"データの規則性を見つけて、分類や識別を行う分野・技術の総称。",detail:"特徴抽出と識別器の設計が二本柱。統計的アプローチが古典的な中核で、深層学習もその延長にある。",vs:"画像処理は画像そのものの変換、パターン認識は意味の判断を担う。",ex:"文字認識や顔検出を含む分野。",related:["教師あり学習","特徴ベクトル"],src:"dip"},
{t:"トーンカーブ",en:"Tone Curve",aliases:[],cat:"hist",d:"入力画素値と出力画素値の対応を表す曲線。点演算の変換関数そのものを指す。",detail:"横軸が入力、縦軸が出力。直線は無変換、S字はコントラスト強調、逆S字は圧縮。ガンマ補正はべき乗という1つの形で、トーンカーブは任意の形を許す一般形。実装はルックアップテーブルに落とすのが普通。",vs:"ヒストグラム平坦化は分布から変換を自動で決める。トーンカーブは形を人が設計する。",ex:"写真編集で影の部分だけを持ち上げる調整。",related:["ガンマ補正","濃度変換","ルックアップテーブル"],src:"ocvhist"},
{t:"離散データ",en:"Discrete Data",aliases:[],cat:"base",d:"取りうる値が飛び飛びに限られるデータ。画素値（0〜255の整数）が典型例。",detail:"数えられる値や、量子化された測定値がこれにあたる。画像は空間方向も値の方向も離散化されているため、画像データそのものが離散データ。",vs:"連続データは切れ目のない量。現実の光の強さは連続だが、記録される時点で離散になる。",ex:"画素値、画素数、検出個数など。",related:["連続データ","量子化","標本化"],src:"dip"},
{t:"連続データ",en:"Continuous Data",aliases:[],cat:"base",d:"取りうる値が切れ目なく連続なデータ。長さや明るさの物理量そのもの。",detail:"カメラは連続した光の分布を、標本化（空間の離散化）と量子化（値の離散化）によって離散データへ変換して記録する。",vs:"離散データは段階の飛んだ値。変換の際に量子化誤差などの情報の欠落が生じる。",ex:"レンズが結ぶ像の光の強さ分布。",related:["離散データ","標本化","量子化"],src:"dip"},
{t:"信号",en:"Signal",aliases:[],cat:"base",d:"情報を担う量の、時間的・空間的な変化。",detail:"画像は「明るさの空間分布」という2次元信号。画像処理の多くの課題は、信号とノイズを見分け、必要な成分を取り出すことに帰着する。",vs:"ノイズは信号に混じる不要な変動。両者の区別は目的に依存する。",ex:"音声波形、心電図、画像の画素値の並び。",related:["ノイズ","周波数","ダイナミックレンジ"],src:"dip"},
{t:"ノイズ",en:"Noise",aliases:[],cat:"base",d:"信号に混入する不要な変動の総称。",detail:"発生源によって性質が異なり、熱雑音のような信号に無関係なものと、ショットノイズのような信号量に依存するものがある。除去処理は信号自体も傷めるため、まず性質を知ることが先決。",vs:"アーティファクトは処理の過程で生じる偽の構造。ノイズは主として取得段階の乱れを指す。",ex:"暗所写真のざらつき、センサの熱雑音。",related:["ガウシアンノイズ","ポアソンノイズ","アーティファクト","信号"],src:"dip"},
{t:"アーティファクト",en:"Artifact",aliases:[],cat:"base",d:"処理や圧縮の過程で生じ、実物には存在しない偽の構造や歪み。",detail:"リンギング、モアレ、ブロッキングなどが代表例。欠けた情報を処理が補って見せた結果であり、そのまま測定すると誤った結論につながる。",vs:"ノイズは取得時の乱れでランダム性が中心。アーティファクトは構造を持った偽情報。",ex:"JPEG圧縮のブロックノイズ、理想フィルタのリンギング。",related:["リンギング","モアレ","ブロッキング","ノイズ"],src:"dip"},
{t:"解像度",en:"Resolution",aliases:[],cat:"base",d:"細かさを表す能力の総称。文脈によって指すものが異なる。",detail:"画素の細かさ（空間解像度）、値の段階数（ビット深度）、光学系が2点を分離できる能力（分解能）は別の概念。画素数が多くても光学分解能が低ければ細部は写らない。",vs:"分解能は光学系の分離能力に限って使うことが多い。",ex:"「解像度が高い」は画素数・分解能・ビット深度のどれを指すか確認が要る。",related:["標本化","ビット深度","レイリー基準","画素"],src:"dip"},
{t:"画素値",en:"Pixel Value",aliases:["濃度値"],cat:"base",d:"各画素が保持する数値。8ビットのグレースケール画像では0〜255。",detail:"カラー画像ではチャンネルごとに値を持つ。センサの出力に撮像条件が乗った相対値であり、そのままでは物理量（反射率など）を表さない点が、定量測定での注意点になる。",vs:"画素（ピクセル）は場所の単位、画素値はその場所の数値。",ex:"しきい値処理や濃度変換は画素値への操作。",related:["画素","ビット深度","グレースケール"],src:"dip"},
{t:"平均",en:"Mean",aliases:["平均値"],cat:"hist",d:"データの合計を個数で割った代表値。",detail:"外れ値に引っ張られやすい。画像では領域内の明るさの平均として頻用され、ヒストグラムからも計算できる。確率分布の期待値の推定量でもある。",vs:"中央値は外れ値に強い。分布が歪んでいるときは両者がずれる。",ex:"画像全体の平均濃度、領域の平均輝度。",related:["中央値","期待値","分散"],src:"dip"},
{t:"中央値",en:"Median",aliases:[],cat:"hist",d:"データを大きさ順に並べたとき、中央に位置する値。",detail:"外れ値の影響を受けにくい代表値で、メディアンフィルタの基礎になる。平均と異なり、データに実在する値（偶数個では中央2つの平均）になる。",vs:"平均は全データを使うため滑らかだが、外れ値に弱い。",ex:"近傍9画素の中央値を取るメディアンフィルタ。",related:["平均","最頻値","外れ値"],src:"dip"},
{t:"最頻値",en:"Mode",aliases:[],cat:"hist",d:"データの中で最も頻繁に現れる値。",detail:"ヒストグラムのピーク（山の頂点）にあたる。背景が画面の多くを占める画像では、背景の濃度が最頻値になることが多い。",vs:"平均・中央値は分布の中心、最頻値は分布の山。",ex:"ヒストグラムの最大ピークの濃度値。",related:["ヒストグラム","二峰性","中央値"],src:"dip"},
{t:"分散",en:"Variance",aliases:[],cat:"hist",d:"データのばらつきを表す量。平均からの偏差の二乗の平均。",detail:"単位が元の量の二乗になる。クラス内分散とクラス間分散の分解は、大津の方法の基礎になっている。",vs:"標準偏差は分散の平方根で、元の量と同じ単位に戻る。",ex:"均一な領域では小さく、テクスチャのある領域では大きい。",related:["標準偏差","平均","大津の方法"],src:"dip"},
{t:"標準偏差",en:"Standard Deviation",aliases:[],cat:"hist",d:"分散の平方根。データと同じ単位でばらつきを表す。",detail:"正規分布では平均±1σの範囲に約68%のデータが入る。記号はσ。ガウシアンフィルタのσ（カーネルの広がり）とは役割が異なる。",vs:"分散は二乗の単位、標準偏差は元の単位。",ex:"ノイズ量の目安として平坦部の標準偏差を測る。",related:["分散","正規分布","ガウシアンフィルタ"],src:"dip"},
{t:"正規分布",en:"Normal Distribution",aliases:["ガウス分布"],cat:"hist",d:"平均を中心に左右対称な釣鐘型の確率分布。",detail:"多くの小さな誤差の和は正規分布に近づく（中心極限定理）。ガウシアンノイズの分布であり、混合ガウスモデルの部品でもある。",vs:"一様分布は範囲内の値が均等に出る分布。",ex:"測定誤差のモデルとして最もよく使われる。",related:["確率分布","標準偏差","ガウシアンノイズ","混合ガウスモデル"],src:"dip"},
{t:"確率分布",en:"Probability Distribution",aliases:[],cat:"hist",d:"各値の出やすさを表す関数や表。",detail:"ヒストグラムを合計1に正規化すると、経験的な確率分布になる。ヒストグラム平坦化は、この分布を一様に近づける操作とみなせる。",vs:"ヒストグラムは度数の集計、確率分布はそれを確率として表したもの。",ex:"濃度値の確率分布 p(r)。",related:["正規分布","期待値","ヒストグラム平坦化"],src:"dip"},
{t:"相関",en:"Correlation",aliases:[],cat:"hist",d:"2つの量が連動して変化する度合い。",detail:"相関係数は−1から1の値を取り、1に近いほど同じ向きに連動する。相関があることは因果関係を意味しない。自己相関は、信号とずらした自分自身との相関。",vs:"自己相関は同一信号同士、相互相関は異なる信号同士の相関。",ex:"テンプレートと画像の相関を取るマッチング。",related:["自己相関","テンプレートマッチング","類似度"],src:"dip"},
{t:"階調",en:"Gradation",aliases:[],cat:"hist",d:"明暗の段階の細かさと、つながりの滑らかさ。",detail:"ビット深度が不足すると階調が飛び、滑らかなグラデーションに縞（バンディング）が現れる。トーンカーブは階調の配分を変える操作。",vs:"階調数は段階の数そのもの、階調は現れ方全体を指すことが多い。",ex:"夕景の空の階調が潰れる、保たれる。",related:["ビット深度","バンディング","トーンカーブ"],src:"ocvhist"},
{t:"周波数",en:"Frequency",aliases:[],cat:"freq",d:"繰り返しの速さ。画像では単位長あたりの明暗の繰り返し回数（空間周波数）を指す。",detail:"周期Tとは f = 1/T の関係にある。細かい模様ほど高周波、なだらかな変化ほど低周波。フーリエ変換は画像を周波数成分へ分解し、周波数スペクトルとして表す。",vs:"時間信号の周波数（Hz）に対し、画像では空間周波数（cycles/mmなど）を使う。",ex:"縞模様の細かさ。文字の輪郭は高周波成分を多く含む。",related:["周波数スペクトル","周期信号","高速フーリエ変換","ナイキスト周波数"],src:"ocvfft"},
{t:"周期信号",en:"Periodic Signal",aliases:["周期データ"],cat:"freq",d:"一定の周期で同じ波形を繰り返す信号。",detail:"離散フーリエ変換は、有限長のデータを周期信号の一部とみなして扱う。そのため両端の不連続がスペクトル漏れの原因になり、窓関数はその対策として使われる。",vs:"非周期信号は繰り返しを持たないが、DFTの枠組みでは周期として扱われる。",ex:"正弦波、矩形波、縞模様のパターン。",related:["周波数","窓関数","離散フーリエ変換"],src:"ocvfft"},
{t:"振幅",en:"Amplitude",aliases:[],cat:"freq",d:"波の大きさ。中心からの最大の振れ幅。",detail:"フーリエ変換の絶対値（振幅スペクトル）は、各周波数成分の強さを表す。信号は振幅と位相の両方がそろって初めて決まる。",vs:"位相は波のずれ、振幅は波の大きさ。",ex:"振幅スペクトルで周期ノイズのピークを探す。",related:["周波数スペクトル","位相","周波数"],src:"ocvfft"},
{t:"勾配",en:"Gradient",aliases:[],cat:"filt",d:"値の空間的な変化率。画像では近傍画素との差分で近似する。",detail:"勾配の大きさはエッジの強さ、勾配の方向はエッジに垂直な向きを与える。微分フィルタは勾配の推定器であり、構造テンソルは勾配の分布をまとめたもの。",vs:"ラプラシアンは2階微分で、勾配（1階微分）とは性質が異なる。",ex:"Sobelフィルタによる勾配の大きさと方向。",related:["微分","ラプラシアン","構造テンソル"],src:"ocvfilt"},
{t:"微分",en:"Differentiation",aliases:[],cat:"filt",d:"変化率を求める演算。離散データでは隣との差分で近似する。",detail:"微分は高周波成分を増幅するためノイズに弱い。平滑化と組み合わせたLoGやDoGが実用上の定石になっている。",vs:"積分は変化の蓄積。微分はその逆操作。",ex:"差分フィルタで輪郭を浮かび上がらせる。",related:["勾配","ラプラシアン","ガウシアンフィルタ"],src:"ocvfilt"},
{t:"近傍",en:"Neighborhood",aliases:[],cat:"filt",d:"注目画素を取り囲む画素の集まり。",detail:"3×3近傍が最小の実用単位。フィルタリング、モルフォロジー処理、連結の判定は、いずれも近傍の定義の上に成り立っている。",vs:"カーネルは近傍への重みの組、近傍は場所の範囲そのもの。",ex:"3×3近傍の平均を取る平滑化。",related:["カーネル","連結性","モルフォロジー処理"],src:"ocvfilt"},
{t:"マスク",en:"Mask",aliases:[],cat:"filt",d:"処理の対象領域を指定するための画像や配列。",detail:"マスクが0の位置は処理しない、数えない、といった制御に使う。フィルタの係数配列を指す「マスク（カーネル）」とは別物で、文脈で区別する。",vs:"領域マスクは場所の指定、カーネルは重みの指定。",ex:"マスク外を除外してヒストグラムを計算する。",related:["カーネル","ラベリング"],src:"ocvfilt"},
{t:"輪郭",en:"Contour",aliases:[],cat:"seg",d:"領域の外周をなす境界線。",detail:"二値画像から境界画素をたどって得る。周囲長や輪郭の形状は、形状特徴の入力になる。OpenCVのfindContoursが代表的な実装。",vs:"エッジは濃度変化の場所、輪郭は領域の境界としての線。",ex:"物体の輪郭を抽出して形を比べる。",related:["ラベリング","細線化","円形度"],src:"dip"},
{t:"連結性",en:"Connectivity",aliases:[],cat:"seg",d:"画素同士がつながっているとみなす約束。4連結と8連結が基本。",detail:"対象を8連結、背景を4連結のように異なる約束を組み合わせると、トポロジーの矛盾（穴の数え違いなど）を避けられる。",vs:"連結成分は、連結性の約束のもとでつながった画素の集まりそのもの。",ex:"斜めの線がつながって見えるかは連結性の約束次第。",related:["ラベリング","連結成分","トポロジー"],src:"skdt"},
{t:"特徴量",en:"Feature",aliases:[],cat:"feat",d:"画像や領域から測定して得られる、性質を数値化したもの。",detail:"面積・円形度などの形状特徴、テクスチャ特徴、SIFTなどの局所特徴がある。認識の性能は、特徴量の選び方と識別器の組み合わせで決まる。",vs:"特徴ベクトルは、特徴量を並べたベクトル表現そのものを指す。",ex:"面積、周囲長、平均濃度、GLCMのコントラスト。",related:["特徴ベクトル","テクスチャ","画像モーメント"],src:"dip"},
{t:"類似度",en:"Similarity",aliases:[],cat:"feat",d:"2つの対象がどれだけ似ているかを表す数値。",detail:"相関係数、差の二乗和（SSD）、内積を正規化したコサイン類似度など、定義は複数ある。テンプレートマッチングは類似度が最大の位置を探す処理。",vs:"距離は小さいほど似ている、類似度は大きいほど似ている、という向きの違いがある。",ex:"テンプレートとの正規化相互相関。",related:["テンプレートマッチング","相関","ユークリッド距離"],src:"ocvtpl"},
{t:"ユークリッド距離",en:"Euclidean Distance",aliases:[],cat:"feat",d:"通常の直線距離。三平方の定理で計算される距離。",detail:"特徴空間における距離の基本形。特徴量ごとに単位や尺度が違うと、大きな値の特徴に支配されるため、正規化してから使うことが多い。",vs:"マンハッタン距離は、軸に沿った移動量の合計で測る距離。",ex:"k近傍法で最も近い訓練例を探す。",related:["距離変換","類似度","k近傍法"],src:"dip"},
{t:"輝度",en:"Luminance",aliases:[],cat:"color",d:"明るさの量。色味を取り除いた明暗の成分。",detail:"YUV表色系のYが輝度信号。人間の視覚は色の違いより輝度の変化に敏感で、色差を間引くクロマサブサンプリングが成立する理由になっている。",vs:"明度は色の見た目の明るさ（HSVのV）で、定義が異なる。",ex:"グレースケール化は輝度への変換。",related:["YUV","グレースケール","クロマサブサンプリング"],src:"dip"},
{t:"色相",en:"Hue",aliases:[],cat:"color",d:"赤・黄・緑・青といった色味の種類。円環上の角度で表すことが多い。",detail:"HSV色空間のH。色相だけを取り出すと、照明による明るさの変化の影響を抑えて、色で分類できる場面がある。",vs:"彩度は鮮やかさ、明度は明るさ。色相は色味そのもの。",ex:"赤い領域を色相の範囲で切り取る。",related:["彩度","明度","分光分布"],src:"dip"},
{t:"彩度",en:"Saturation",aliases:[],cat:"color",d:"色の鮮やかさ。無彩色（灰色）からの離れ具合。",detail:"彩度0が灰色で、大きくなるほど鮮やかになる。HSV色空間のS。",vs:"明度は明るさの軸で、彩度とは独立に変わる。",ex:"くすんだ色は彩度が低い。",related:["色相","明度"],src:"dip"},
{t:"明度",en:"Value (Brightness)",aliases:[],cat:"color",d:"色の明るさ。HSV（HSB）色空間のV（B）。",detail:"RGBの最大値で定義される単純な明るさで、物理的な輝度とは異なる。色相・彩度と組み合わせて、色を直感的に指定できる。",vs:"輝度は人間の感度を重み付けした明るさ。明度はRGBの最大値。",ex:"明度を上げると全体が白っぽくなる。",related:["色相","彩度","輝度"],src:"dip"},
{t:"波長",en:"Wavelength",aliases:[],cat:"color",d:"波の山から次の山までの長さ。光では色に対応する物理量。",detail:"可視光はおよそ380〜780nmの範囲。分光分布は、波長ごとの光の強さを表したもの。",vs:"周波数とは、波長×周波数＝波の速さ、の関係で結ばれる。",ex:"赤は長波長側、青・紫は短波長側。",related:["分光分布","等色関数","周波数"],src:"dip"},
{t:"混同行列",en:"Confusion Matrix",aliases:[],cat:"recog",d:"分類結果の正誤を、実際のクラスと予測クラスの組み合わせで集計した表。",detail:"適合率、再現率、F値などの指標はすべてこの表から計算される。どのクラス同士を間違えやすいかも読み取れる。",vs:"正解率は表全体の要約、混同行列はその内訳そのもの。",ex:"2クラスなら真陽性・偽陽性・偽陰性・真陰性の4マス。",related:["適合率","再現率"],src:"dip"},
{t:"適合率",en:"Precision",aliases:[],cat:"recog",d:"正と予測したもののうち、実際に正だった割合。",detail:"誤検出（偽陽性）を嫌う場面で重視される。再現率とはトレードオフの関係にあり、しきい値の選び方で両者が変わる。",vs:"再現率は実際の正をどれだけ拾えたか、適合率は予測の的確さ。",ex:"検出器が誤検出ばかりなら適合率が下がる。",related:["再現率","混同行列"],src:"dip"},
{t:"再現率",en:"Recall",aliases:[],cat:"recog",d:"実際に正であるもののうち、正と予測できた割合。",detail:"見逃し（偽陰性）を嫌う場面で重視される。適合率とのトレードオフがあり、用途に応じてしきい値で調整する。",vs:"適合率は予測した正の的確さ、再現率は拾い漏らしの少なさ。",ex:"病変の見逃しを避けたい検査では再現率を優先する。",related:["適合率","混同行列"],src:"dip"},
{t:"訓練データ",en:"Training Data",aliases:["学習データ"],cat:"recog",d:"モデルのパラメータを調整するために使うデータ。",detail:"評価用のテストデータとは分離が鉄則で、同じデータで評価すると汎化性能を正しく測れない。量だけでなく、偏りやラベルの正確さが性能を左右する。",vs:"テストデータは評価専用。訓練データで性能を測ると過大評価になる。",ex:"ラベル付き画像の集合で分類器を学習させる。",related:["汎化","過学習","交差検証","アノテーション"],src:"dip"},
{t:"損失関数",en:"Loss Function",aliases:[],cat:"recog",d:"予測の悪さを1つの数値にまとめる関数。",detail:"学習は、損失関数を小さくする方向にパラメータを更新する過程。二乗誤差や交差エントロピーが代表例。評価指標そのものとは一致しないことも多い。",vs:"評価指標は性能の物差し、損失関数は学習を駆動するための物差し。",ex:"分類では交差エントロピー、回帰では二乗誤差が定番。",related:["勾配降下法","学習率","汎化"],src:"dip"},
{t:"交差検証",en:"Cross-Validation",aliases:["クロスバリデーション"],cat:"recog",d:"データを複数に分割し、訓練と評価の組み合わせを入れ替えて性能を測る方法。",detail:"k分割交差検証では、k通りの評価の平均を取るため、1回の分割の偶然に左右されにくい。ハイパーパラメータの選択にも使う。",vs:"ホールドアウトは1回の分割だけの評価で、手軽だが結果がばらつく。",ex:"5分割交差検証で分類器の性能を比較する。",related:["訓練データ","汎化","ハイパーパラメータ"],src:"dip"},
{t:"ハイパーパラメータ",en:"Hyperparameter",aliases:[],cat:"recog",d:"学習の前に人が決めておく設定値。学習率、近傍数k、正則化の強さなど。",detail:"データから自動的には決まらないため、交差検証などで候補を比較して選ぶ。モデルのパラメータ（学習で決まる値）とは区別される。",vs:"パラメータは学習で決まる値、ハイパーパラメータは学習の進め方を決める値。",ex:"SVMのマージンの許容度、k近傍法のk。",related:["学習率","交差検証","正則化"],src:"dip"},
{t:"絞り",en:"Aperture",aliases:["F値"],cat:"cam",d:"レンズを通る光の量を決める開口の大きさ。F値で表される。",detail:"F値が小さいほど開口が大きく、光が増えて被写界深度は浅くなる。絞りすぎると回折で像が甘くなる。",vs:"シャッター速度は光を当てる時間、絞りは光の通り道の広さ。",ex:"F1.8は明るいレンズ、F16では被写界深度が深い。",related:["被写界深度","回折","焦点距離"],src:"dip"},
{t:"感度",en:"ISO Sensitivity",aliases:["ISO感度"],cat:"cam",d:"撮像素子が光を信号に変える増幅度合いの設定。ISO値で表す。",detail:"ISOを上げるほど暗い場面でも撮れるが、信号の増幅に伴ってノイズも目立つようになる。",vs:"絞りとシャッター速度は光の量そのもの、感度は受け取る側の増幅。",ex:"暗所でISO感度を上げるとノイズが増える。",related:["ノイズ","撮像素子","ダイナミックレンジ"],src:"dip"},
{t:"収差",en:"Aberration",aliases:[],cat:"cam",d:"レンズによる理想の結像からのずれの総称。",detail:"球面収差、コマ収差、非点収差、像面湾曲、歪曲収差が単色収差の5種で、ほかに色収差がある。歪曲収差は像の幾何を歪ませ、他は主にボケの原因になる。",vs:"歪曲収差は収差の一種で、直線が曲がって写るずれを指す。",ex:"画面周辺で像が流れるのは収差の影響。",related:["歪曲収差","回折","被写界深度"],src:"dip"}
];
